insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 28, '''അവന് തന്റെ സഹോദരന്റെ ഭാഗത്തുനിന്ന് വല്ല ഇളവും ലഭിക്കുകയാണെങ്കിൽ ..'' എന്നതിന്റെ വിവക്ഷ', 'بَابٌ: تَأْوِيلُ قَوْلِهِ عَزَّ وَجَلَّ: ''فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ'' ..', 548 from books where volume_id=3 and book_no=7 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
