insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (3, 17, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1029) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "إِنَّ الزَّمَانَ قَدِ اسْتَدَارَ كَهَيْئَتِهِ يَوْمَ خَلَقَ اللهُ السَّمَاوَاتِ وَالأَرْضَ، السَّنَةُ اثْنَا عَشَرَ شَهْرًا مِنْهَا أَرْبَعَةٌ حُرُمٌ، ثَلاثَةٌ مُتَوَالِيَاتٍ: ذُو الْقَعْدَةِ، وَذُو الْحِجَّةِ، وَالْمُحَرَّمُ، وَرَجَبُ شَهْرُ مُضَرَ الَّذِي بَيْنَ جُمَادَى وَشَعْبَانَ". ثُمَّ قَالَ: "أَيُّ شَهْرٍ هَذَا". قُلْنَا: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ، قَالَ: "أَلَيْسَ ذَا الْحِجَّةِ". قُلْنَا: بَلَى، قَالَ: "فَأَيُّ بَلَدٍ هَذَا". قُلْنَا: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ، قَالَ: "أَلَيْسَ الْبَلْدَةَ". قُلْنَا: بَلَى، قَالَ: "فَأَيُّ يَوْمٍ هَذَا". قُلْنَا: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَسَكَتَ حَتَّى ظَنَنَّا أَنَّهُ سَيُسَمِّيهِ بِغَيْرِ اسْمِهِ، قَالَ: "أَلَيْسَ يَوْمَ النَّحْرِ". قُلْنَا: بَلَى يَا رَسُولَ اللهِ، قَالَ: "فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ – قَالَ مُحَمَّدٌ: وَأَحْسِبُهُ قَالَ – وَأَعْرَاضَكُمْ، حَرَامٌ عَلَيْكُمْ كَحُرْمَةِ يَوْمِكُمْ هَذَا، فِي بَلَدِكُمْ هَذَا، فِي شَهْرِكُمْ هَذَا، وَسَتَلْقَوْنَ رَبَّكُمْ فَيَسْأَلُكُمْ عَنْ أَعْمَالِكُمْ، فَلا تَرْجِعُنَّ بَعْدِي كُفَّارًا – أَوْ: ضُلَّالًا – يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ، أَلَا لِيُبَلِّغِ الشَّاهِدُ الْغَائِبَ، فَلَعَلَّ بَعْضَ مَنْ يُبَلَّغُهُ يَكُونُ أَوْعَى لَهُ مِنْ بَعْضِ مَنْ سَمِعَهُ". ثُمَّ قَالَ: "أَلَا هَلْ بَلَّغْتُ". (ق)', 'അബൂബക്റ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു ആകാശഭൂമികൾ പടച്ച ദിവസം മുതൽ കാലം അതിന്റെ രൂപത്തിൽ കറങ്ങി. ഒരു വർഷം പന്ത്രണ്ട് മാസമാണ്. അതിൽ നാല് മാസങ്ങൾ യുദ്ധം നിഷിദ്ധമായ മാസമാണ്. ദുൽഖഅ്ദ, ദുൽഹജ്ജ്, മുഹർറം എന്നീ മൂന്ന് തുടർച്ചയായ മാസങ്ങളും ശഅ്ബാന്റെയും ജമാദുൽ ഉഖ്റയുടേയും ഇടയിലുള്ള മുളറിന്റെ മാസമായ റജബുമാണവ." പിന്നീട് പ്രവാചകൻ(സ) ചോദിച്ചു: "ഏത് മാസമാണിത്?" അല്ലാഹുവിനും റസൂലിനുമറിയാം, ഞങ്ങൾ പ്രതിവചിച്ചു. പ്രവാചകൻ(സ) ഒരുപാട് നേരം മൗനം ദീക്ഷിച്ചു. ഈ മാസത്തിന് നബി(സ) വേറെ പേര് വെക്കുമെന്ന് ഞങ്ങൾ വിചാരിച്ചു. "ഇത് ദുൽ ഹിജ്ജയല്ലേ?" നബി(സ) ചോദിച്ചു. അതെ, ഞങ്ങൾ പറഞ്ഞു. നബി(സ) ചോദിച്ചു: "ഈ പ്രദേശമേതാണ്?" അല്ലാഹുവിനും റസൂലിനുമറിയാം, ഞങ്ങൾ പറഞ്ഞു. ഈ പ്രദേശത്തിന് വേറെയൊരു നാമമിടുമോ എന്ന് ഞങ്ങൾ ഭാവിക്കാൻ മാത്രം നബി(സ) മൗനമവലംബിച്ചു. പിന്നെ നബി(സ) ചോദിച്ചു: "ഇത് അൽബൽദയല്ലേ?" ഞങ്ങൾ പറഞ്ഞു: അതെ. നബി(സ) വീണ്ടും ചോദിച്ചു: "ഇതേത് ദിവസമാണ്?" ഞങ്ങൾ പറഞ്ഞു: അല്ലാഹുവിനും റസൂലിനുമറിയാം. ഈ ദിവസത്തിനും നബി(സ) പുതിയ നാമം നൽകുമെന്ന് ഞങ്ങൾ വിചാരിച്ചു. നബി(സ) അത്രമേൽ മൗനം ദീക്ഷിച്ചു. നബി(സ) ചോദിച്ചു. "ഇത് നഹർ ദിനമല്ലയോ?" ഞങ്ങൾ പറഞ്ഞു: അതേ, പ്രവാചകരേ. "ഈ ദിവസം നിങ്ങൾക്ക് നിഷിദ്ധമായത് പോലെ, ഈ പ്രദേശം നിങ്ങൾക്ക് നിഷിദ്ധമായത് പോലെ, ഈ മാസം നിഷിദ്ധമായത് പോലെ നിങ്ങളുടെ രക്തവും സമ്പത്തും - മുഹമ്മദ് എന്ന നിവേദകൻ പറയുന്നു: നബി(സ) ഇപ്രകാരം പറഞ്ഞുവെന്ന് ഞാൻ കരുതുന്നു - അഭിമാനവും നിങ്ങൾക്ക് ഹറാമാണ്. നിങ്ങളുടെ നാഥനെ നിങ്ങൾ കണ്ടുമുട്ടും. അവൻ നിങ്ങളോട് നിങ്ങളുടെ കർമ്മങ്ങളെക്കുറിച്ച് ചോദിക്കും. എനിക്ക് ശേഷം പരസ്പരം കഴുത്തറുക്കുന്ന സത്യനിഷേധികളായി - അല്ലെങ്കിൽ: പിഴച്ചവരായി - നിങ്ങൾ മാറരുത്. ഇവിടെ സന്നിഹിതരായവർ അസന്നിഹിതർക്ക് ഈ സന്ദേശം എത്തിക്കട്ടെ. ഒരുപക്ഷേ, സത്യം കേട്ടവനേക്കാൾ അതിനോട് സൂക്ഷ്മത കൈകൊള്ളുന്നത് അവൻ എത്തിച്ചുകൊടുത്തവനായിരിക്കാം." ശേഷം അവിടന്ന് പറഞ്ഞു: "അറിയുക, ഞാൻ എത്തിച്ചു തന്നില്ലെയോ?" (ബു,മു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 523, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ لَقِيَ اللهَ لَا يُشْرِكُ بِهِ شَيْئًا – لَمْ يَتَنَدَّ بِدَمٍ حَرَامٍ – دَخَلَ الْجَنَّةَ". (جه)', 'ഉഖ്ബതുബ്നു ആമിറുൽജുഹനി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനോട് ആരെയും പങ്കുചേർക്കാതെ - അക്രമമായി ഒരാളെയും വധിക്കാതെ - അല്ലാഹുവിനെ ആരെങ്കിലും കണ്ടുമുട്ടിയാൽ അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കും." (ജ)', 'عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ', 'ഉഖ്ബതുബ്നു ആമിറുൽജുഹനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَجُلًا قَرَأَ آيَةً سَمِعْتُ مِنَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خِلافَهَا، فَأَخَذْتُ بِيَدِهِ فَأَتَيْتُ بِهِ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "كِلاكُمَا مُحْسِنٌ". قَالَ: "لَا تَخْتَلِفُوا، فَإِنَّ مَنْ كَانَ قَبْلَكُمْ اخْتَلَفُوا فَهَلَكُوا". (خ)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ)യിൽ നിന്ന് കേട്ടതിന് വിപരീതമായി ഒരാൾ ഖുർആൻ ഓതുന്നത് ഞാൻ കേട്ടു. അയാളുടെ കൈപിടിച്ച് കൊണ്ട് ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ രണ്ടുപേരും ഓതിയത് ശരിയാണ്. നിങ്ങൾ ഭിന്നിക്കരുത്. കാരണം നിങ്ങൾക്ക് മുമ്പുള്ളവർ നശിച്ചത് ഭിന്നിപ്പ് കാരണമാണ്." (ബു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: اسْتَبَّ رَجُلَانِ، رَجُلٌ مِنَ الْمُسْلِمِينَ، وَرَجُلٌ مِنَ الْيَهُودِ، قَالَ الْمُسْلِمُ: وَالَّذِي اصْطَفَى مُحَمَّدًا عَلَى الْعَالَمِينَ، فَقَالَ الْيَهُودِيُّ: وَالَّذِي اصْطَفَى مُوسَى عَلَى الْعَالَمِينَ، فَرَفَعَ الْمُسْلِمُ يَدَهُ عِنْدَ ذَلِكَ فَلَطَمَ وَجْهَ الْيَهُودِيِّ، فَذَهَبَ الْيَهُودِيُّ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَهُ بِمَا كَانَ مِنْ أَمْرِهِ وَأَمْرِ الْمُسْلِمِ، فَدَعَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمُسْلِمَ فَسَأَلَهُ عَنْ ذَلِكَ فَأَخْبَرَهُ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُخَيِّرُونِي عَلَى مُوسَى، فَإِنَّ النَّاسَ يَصْعَقُونَ يَوْمَ الْقِيَامَةِ فَأَصْعَقُ مَعَهُمْ، فَأَكُونُ أَوَّلَ مَنْ يُفِيقُ، فَإِذَا مُوسَى بَاطِشٌ جَانِبَ الْعَرْشِ، فَلَا أَدْرِي أَكَانَ فِيمَنْ صَعِقَ فَأَفَاقَ قَبْلِي، أَوْ كَانَ مِمَّنْ اسْتَثْنَى اللهُ". (خ)', 'അബൂഹുറൈറ(റ): രണ്ടുപേർ പരസ്പരം ചീത്തവിളിച്ചു. ഒരാൾ മുസ്ലിമും മറ്റെയാൾ ജൂതനും. മുസ്ലിം പറഞ്ഞു: മനുഷ്യരാശിയിൽ വെച്ച് മുഹമ്മദ്(സ)യെ ഏറ്റവും ഉത്കൃഷ്ടരായി തെരെഞ്ഞെടുത്തവൻതന്നെ സത്യം. അപ്പോൾ ജൂതൻ പറഞ്ഞു: മനുഷ്യരാശിയിൽ വെച്ച് മൂസാ(അ)മിനെ ഏറ്റവും ഉത്കൃഷ്ടവാനായി തെരഞ്ഞെടുത്തവൻതന്നെ സത്യം. ഉടനെ മുസ്ലിം തന്റെ കൈയുയർത്തി ജൂതന്റെ മുഖത്തടിച്ചു. ജൂതൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് ആവലാതി ബോധിപ്പിക്കുകയും സംഭവങ്ങൾ വിവരിക്കുകയും ചെയ്തു. അപ്പോൾ നബി(സ) മുസ്ലിമിനെ വിളിപ്പിച്ചു. അദ്ദേഹത്തോട് കാര്യം ചോദിച്ചു. അദ്ദേഹം ഉണ്ടായത് പറഞ്ഞു: അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ മൂസയേക്കാൾ എന്നെ ഉത്കൃഷ്ടനാക്കരുത്. അന്ത്യനാളിൽ എല്ലാവരും ബോധരഹിതരായി വീഴും. അവരുടെ കൂടെ ഞാനും വീഴും. ആദ്യമായി ബോധം തെളിയുന്നവൻ ഞാനായിരിക്കും. കണ്ണുതുറന്ന് നോക്കുമ്പോൾ മൂസ(അ) അർശിന്റെ ഭാഗം പിടിച്ച് അതാ നിൽക്കുന്നു. എനിക്കറിയില്ല, അവർ ബോധരഹിതനായി എന്റെ മുമ്പേ ബോധം തെളിഞ്ഞവരിൽ പെട്ടവരാണോ അതോ അല്ലാഹു പ്രത്യേകം മാറ്റിനിർത്തിയവരിൽ പെട്ടവരാണോ എന്ന്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 524, 524, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَحِلُّ دَم [امْرِئٍ] مُسْلِمٍ – يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَنِّي رَسُولُ اللهِ – إِلَّا بِإِحْدَى ثَلاثٍ: الثَّيِّبُ الزَّانِي، وَالنَّفْسُ بِالنَّفْسِ، وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും ഞാനല്ലാഹുവിന്റെ ദൂതനാണെന്നും സാക്ഷ്യം വഹിക്കുന്ന ഒരു മുസ്ലിമായ വ്യക്തിയുടെ രക്തം മൂന്ന് കാര്യങ്ങൾ കൊണ്ട് മാത്രമേ അനുവദനീയമാകുകയുള്ളൂ: വിവാഹിതനായ വ്യഭിചാരി, കൊലക്ക് പകരമുള്ള കൊല, മതം പരിത്യജിച്ച് ഇസ്ലാമിക മുഖ്യധാരയിൽ നിന്ന് മാറി നിൽക്കുന്നവർ." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'امْرِئٍ', null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "لَا يَحِلُّ قَتْلُ مُسْلِمٍ إِلَّا فِي إِحْدَى ثَلاثِ خِصَالٍ: زَانٍ مُحْصَنٌ فَيُرْجَمُ، وَرَجُلٌ يَقْتُلُ مُسْلِمًا مُتَعَمِّدًا، وَرَجُلٌ يَخْرُجُ مِنَ الْإِسْلَامِ فَيُحَارِبُ اللهَ عَزَّ وَجَلَّ وَرَسُولَهُ فَيُقْتَلُ، أَوْ يُصَلَّبُ، أَوْ يُنْفَى مِنَ الأَرْضِ". (ن)', 'ആഇശ(റ): തിരുമേനി(സ) പറഞ്ഞു: "മൂന്നാലൊരു കാരണങ്ങൾ കൊണ്ടെല്ലാതെ ഒരുമുസ്ലിമിനെ വധിക്കാൻ പാടില്ല: വിവാഹിതനായ വ്യഭിചാരി, അവനെ എറിഞ്ഞുകൊല്ലണം. മുസ്ലിമായ വ്യക്തിയെ മനഃപൂർവ്വം വധിച്ചവൻ, ഇസ്ലാമിൽ നിന്ന് പുറത്തു പോയി അല്ലാഹുവിനോടും റസൂലിനോടും യുദ്ധം പ്രഖ്യാപിക്കുന്നയാൾ, അവനെ വധിക്കുകയോ കുരിശിലേറ്റുകയോ നാടുകടത്തുകയോ വേണം." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ قَالَ: كُنَّا مَعَ عُثْمَانَ وَهُوَ مَحْصُورٌ فِي الدَّارِ، وَكَانَ فِي الدَّارِ مَدْخَلٌ مَنْ دَخَلَهُ سَمِعَ كَلَامَ مَنْ عَلَى الْبَلَاطِ، فَدَخَلَهُ عُثْمَانُ، فَخَرَجَ إِلَيْنَا وَهُوَ مُتَغَيِّرٌ لَوْنُهُ، فَقَالَ: إِنَّهُمْ لَيَتَوَاعَدُونِي بِالْقَتْلِ آنِفًا، قَالَ: قُلْنَا: يَكْفِيكَهُمُ اللهُ يَا أَمِيرَ الْمُؤْمِنِينَ، قَالَ: وَلِمَ يَقْتُلُونَنِي؟ سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا بِإِحْدَى ثَلَاثٍ: كُفْرٌ بَعْدَ إِسْلَامٍ، أَوْ زِنًا بَعْدَ إِحْصَانٍ، أَوْ قَتْلُ نَفْسٍ بِغَيْرِ نَفْسٍ". فَوَاللهِ مَا زَنَيْتُ فِي جَاهِلِيَّةٍ وَلَا فِي إِسْلَامٍ قَطُّ، وَلَا أَحْبَبْتُ أَنَّ لِي بِدِينِي بَدَلًا مُنْذُ هَدَانِي اللهُ، وَلَا قَتَلْتُ نَفْسًا، فَبِمَ يَقْتُلُونَنِي؟. (د,ت,ن,جه)', 'അബൂഉമാമതുബ്നു സഹ്ൽ(റ): ഞങ്ങൾ വീട്ടിൽ തടവുകാരനാക്കപ്പെട്ട ഉസ്മാൻ(റ)വിന്റെ കൂടെയായിരുന്നു. വീട്ടിൽ ഒരു പ്രവേശനസ്ഥാനമുണ്ട്. അവിടെ നിന്നാൽ ''ബിലാഥി''ലുള്ളവന്റെ സംസാരം കേൾക്കാം. ഉസ്മാൻ(റ) അവിടെ നിന്നു. ഉസ്മാൻ(റ) ഞങ്ങളുടെയടുത്തേക്ക് വന്നു. അദ്ദേഹത്തിന്റെ നിറം വ്യത്യാസപ്പെട്ടിരുന്നു. അദ്ദേഹം പറഞ്ഞു: അവർ എന്നെ ഇപ്പോൾ തന്നെ കൊല്ലുമെന്ന് ഭീഷണിപ്പെടുത്തുന്നു. ഞങ്ങൾ പറഞ്ഞു: ഓ അമീറുൽ മുഅ്മിനീൻ, അവർക്കെതിരെ നിങ്ങൾക്ക് അല്ലാഹു തന്നെ മതി. ഉസ്മാൻ(റ) പറഞ്ഞു: അവർ എന്തിനാണ് എന്നെ കൊല്ലുന്നത്? ഞാൻ തിരുമേനി(സ) പറയുന്നതായി കേട്ടിട്ടുണ്ട്: "മൂന്നാലൊരു കാരണങ്ങൾ കൊണ്ടല്ലാതെ ഒരു മുസ്ലിമിന്റെ രക്തം ഹലാലാകില്ല: ഇസ്ലാമിന് ശേഷം സത്യനിഷേധം നടത്തുക, വിവാഹത്തിന് ശേഷം വ്യഭിചരിക്കുക, ഒരു വ്യക്തിയെ അകാരണമായി വധിക്കുക." അല്ലാഹുവാണ് സത്യം, ഞാൻ ജാഹിലിയ്യാ കാലത്തും ഇസ്ലാമിൽ വന്നതിനുശേഷവും വ്യഭിചരിച്ചിട്ടില്ല. അല്ലാഹു എനിക്ക് സന്മാർഗം കാണിച്ചതിനു ശേഷം എന്റെ മതത്തിൽ ഞാനൊരു മാറ്റം ആഗ്രഹിച്ചിട്ടില്ല. ഒരാളെയും ഞാൻ വധിച്ചിട്ടില്ല. പിന്നെ എന്തിനാണ് അവരെന്നെ വധിക്കുന്നത്? (ദ,തു,ന,ജ)', 'أَبِي أُمَامَةَ بْنِ سَهْلٍ قَالَ', 'അബൂഉമാമതുബ്നു സഹ്ൽ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 525, 525, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللهُ عَنْهُمَا أَنَّهُمَا قَالَا: خَرَجَ عَبْدُ اللهِ بْنُ سَهْلِ بْنِ زَيْدٍ وَمُحَيِّصَةُ بْنُ مَسْعُودِ بْنِ زَيْدٍ، حَتَّى إِذَا كَانَا بِخَيْبَرَ تَفَرَّقَا فِي بَعْضِ مَا هُنَاكَ، ثُمَّ إِنَّ مُحَيِّصَةَ وَجَدَ عَبْدَ اللهِ بْنَ سَهْلٍ قَتِيلًا قَدْ قُتِلَ، فَدَفَنَهُ ثُمَّ أَقْبَلَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ هُوَ وَحُوَيِّصَةُ بْنُ مَسْعُودٍ وَعَبْدُ الرَّحْمَنِ بْنُ سَهْلٍ، وَكَانَ أَصْغَرَ الْقَوْمِ، ذَهَبَ عَبْدُ الرَّحْمَنِ لِيَتَكَلَّمَ قَبْلَ صَاحِبَيْهِ، قَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "كَبِّرْ لِلْكُبْرِ". فَصَمَتَ وَتَكَلَّمَ صَاحِبَاهُ، ثُمَّ تَكَلَّمَ مَعَهُمَا، فَذَكَرُوا لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَقْتَلَ عَبْدِ اللهِ بْنِ سَهْلٍ، فَقَالَ لَهُمْ: "أَتَحْلِفُونَ خَمْسِينَ يَمِينًا فَتَسْتَحِقُّونَ صَاحِبَكُمْ؟ أَوْ: قَاتِلَكُمْ". قَالُوا: وَكَيْفَ نَحْلِفُ وَلَمْ نَشْهَدْ؟ قَالَ: "فَتُبَرِّئُكُمْ يَهُودُ بِخَمْسِينَ يَمِينًا". قَالُوا: وَكَيْفَ نَقْبَلُ أَيْمَانَ قَوْمٍ كُفَّارٍ؟ فَلَمَّا رَأَى ذَلِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَعْطَى عَقْلَهُ. قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'റാഫിഉബ്നു ഖദീജ്(റ): അബ്ദുല്ലാഹിബ്നു സഹ്ൽ(റ): മുഹയ്യിസതുബ്നു മസ്ഊദുബിൻ സൈദ്(റ) എന്നിവർ ഒന്നിച്ച് യാത്ര തിരിച്ചു. അങ്ങനെ അവർ ഖൈബറിലെത്തിയപ്പോൾ അവിടെ വെച്ച് ചിലയിടങ്ങളിലേക്കായി അവർ വേർപ്പിരിഞ്ഞു. മുഹയ്യിസ(റ) പിന്നീട് അബ്ദുല്ലാഹിബ്നു സഹ്ൽ(റ) കൊല്ലപ്പെട്ടതായി കണ്ടെത്തി. മുഹയ്യിസ(റ) അദ്ദേഹത്തെ ഖബറടക്കി. അദ്ദേഹവും ഹുവയ്യിസുബ്നു മസ്ഊദ്(റ)വും അബ്ദുർറഹ്മാനുബ്നു സഹ്ൽ(റ)വും പ്രവാചക സന്നിധിയിലേക്ക് തിരിച്ചു. അബ്ദുല്ലാഹിബ്നു സഹ്ൽ(റ) കൂട്ടത്തിൽ ചെറിയവനായിരുന്നു. അബ്ദുർറഹ്മാൻ(റ) തന്റെ രണ്ട് കൂട്ടുകാർക്ക് മുമ്പ് സംസാരിക്കാൻ തുടങ്ങി. പ്രവാചകർ(സ) പറഞ്ഞു: "വലിയവർ പറയട്ടെ." അപ്പോൾ അബ്ദുർറഹ്മാൻ(റ) മൗനം ദീക്ഷിച്ചു. മറ്റു രണ്ടു പേർ സംസാരിച്ചു. പിന്നീട് അവർ രണ്ട് പേരുടേയും കൂടെ അദ്ദേഹവും സംസാരിച്ചു. അബ്ദുല്ലാഹിബ്നു സഹ്ൽ(റ)വിന്റെ കൊലയെപ്പറ്റി അവർ നബി(സ)യോട് സംസാരിച്ചു. പ്രവാചകർ(സ) അവരോട് ചോദിച്ചു: "നിങ്ങൾ അൻപത് പ്രാവശ്യം സത്യം ചെയ്യുമോ? അങ്ങനെയെങ്കിൽ ഘാതകന്റെ നഷ്ടപരിഹാരത്തിന് നിങ്ങൾ അർഹരാകും." അവർ പറഞ്ഞു: ഞങ്ങളെങ്ങനെയാണ് സത്യം ചെയ്യുക, ഞങ്ങൾ സംഭവത്തിന് സാക്ഷികളല്ലല്ലോ? പ്രവാചകർ(സ) ചോദിച്ചു: "എന്നാൽ ജൂതർ അമ്പത് പ്രാവശ്യം സത്യം ചെയ്താലോ?" അവർ പറഞ്ഞു: സത്യനിഷേധികളുടെ സത്യം എങ്ങനെയാണ് ഞങ്ങൾ സ്വീകരിക്കുക. ഇത് കേട്ട പ്രവാചകർ(സ) അവർക്ക് ദിയത്ത് (നഷ്ടപരിഹാരം) നൽകി. (ബു,മു,ദ,തു,ന,ജ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 526, 526, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ سَهْلِ بْنِ أَبِي حَثْمَةَ، عَنْ رِجَالٍ مِنْ كُبَرَاءِ قَوْمِهِ: أَنَّ عَبْدَ اللهِ بْنَ سَهْلٍ وَمُحَيِّصَةَ خَرَجَا إِلَى خَيْبَرَ مِنْ جَهْدٍ أَصَابَهُمْ، فَأَتَى مُحَيِّصَةُ فَأَخْبَرَ أَنَّ عَبْدَ اللهِ بْنَ سَهْلٍ قَدْ قُتِلَ وَطُرِحَ فِي عَيْنٍ أَوْ فَقِيرٍ، فَأَتَى يَهُودَ فَقَالَ: أَنْتُمْ وَاللهِ قَتَلْتُمُوهُ، قَالُوا: وَاللهِ مَا قَتَلْنَاهُ، ثُمَّ أَقْبَلَ حَتَّى قَدِمَ عَلَى قَوْمِهِ فَذَكَرَ لَهُمْ ذَلِكَ، ثُمَّ أَقْبَلَ هُوَ وَأَخُوهُ حُوَيِّصَةُ – وَهُوَ أَكْبَرُ مِنْهُ – وَعَبْدُ الرَّحْمَنِ بْنُ سَهْلٍ، فَذَهَبَ مُحَيِّصَةُ لِيَتَكَلَّمَ، وَهُوَ الَّذِي كَانَ بِخَيْبَرَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِمُحَيِّصَةَ: "كَبِّرْ كَبِّرْ" يُرِيدُ السِّنَّ. فَتَكَلَّمَ حُوَيِّصَةُ، ثُمَّ تَكَلَّمَ مُحَيِّصَةُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِمَّا أَنْ يَدُوا صَاحِبَكُمْ، وَإِمَّا أَنْ يُؤْذِنُوا بِحَرْبٍ". فَكَتَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِمْ فِي ذَلِكَ، فَكَتَبُوا: إِنَّا وَاللهِ مَا قَتَلْنَاهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِحُوَيِّصَةَ وَمُحَيِّصَةَ وَعَبْدِ الرَّحْمَنِ: "أَتَحْلِفُونَ وَتَسْتَحِقُّونَ دَمَ صَاحِبِكُمْ". قَالُوا: لَا، قَالَ: "فَتَحْلِفُ لَكُمْ يَهُودُ". قَالُوا: لَيْسُوا بِمُسْلِمِينَ، فَوَادَاهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ عِنْدِهِ، فَبَعَثَ إِلَيْهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِائَةَ نَاقَةٍ حَتَّى أُدْخِلَتْ عَلَيْهِمُ الدَّارَ، فَقَالَ سَهْلٌ: فَلَقَدْ رَكَضَتْنِي مِنْهَا نَاقَةٌ حَمْرَاءُ. (ق,ن,جه)', 'സഹ്ലുബ്നു അബീഹസ്മ(റ) തന്റെ സമൂഹത്തിലെ ഉന്നതരിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: അബ്ദുല്ലാഹിബ്നു സഹ്ൽ(റ)വും മുഹയ്യിസ(റ)വും അവർക്കുണ്ടായ ചില ബുദ്ധിമുട്ടുകൾ നിമിത്തം ഖൈബറിലേക്ക് പുറപ്പെട്ടു. മുഹയ്യിസ(റ) അവിടെയെത്തി. അബ്ദുല്ലാഹിബ്നു സ്ഹ്ൽ(റ) കൊല്ലപ്പെട്ട വിവരം മുഹയ്യിസ(റ)വിനോട് ആരോ പറഞ്ഞു. അദ്ദേഹം ഏതോ അരുവിയിലേക്കോ കിണറ്റിലേക്കോ എറിയപ്പെട്ടിരിക്കുന്നു. മുഹയ്യിസ(റ) ജൂതരുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, നിങ്ങളാണ് അദ്ദേഹത്തെ കൊന്നത്. അവർ പറഞ്ഞു. അല്ലാഹുവാണ് സത്യം, ഞങ്ങളദ്ദേഹത്തെ കൊന്നിട്ടില്ല. മുഹയ്യിസ(റ) തന്റെ സമൂഹത്തിലേക്ക് പോയി വിവരമറിയിച്ചു. അദ്ദേഹവും തന്റെ ജ്യേഷ്ഠ സഹോദരൻ ഹുവയ്യിസ(റ)വും അബ്ദുറഹ്മാനുബ്നു സഹ്ൽ(റ)വും പുറപ്പെട്ടു. മുഹയ്യിസ(റ) നബി(സ)യോട് സംസാരിക്കാൻ ചെന്നു. ഖൈബറിലുണ്ടായിരുന്നത് അദ്ദേഹമായിരുന്നു. നബി(സ) മുഹയ്യിസ(റ)വിനോട് പറഞ്ഞു: "വലിയവർ പറയട്ടെ." അവിടുന്ന് ഉദ്ദേശിച്ചത് വയസ്സായിരുന്നു. ഹുവയ്യിസ(റ) സംസാരിച്ചു. പിന്നെ മുഹയ്യിസ(റ)വും സംസാരിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഒന്നുകിൽ നിങ്ങളുടെ കൂട്ടുകാരന് അവർ നഷ്ടപരിഹാരം നൽകട്ടെ, അല്ലെങ്കിൽ അവർ യുദ്ധത്തിന് തയ്യാറായിക്കൊള്ളട്ടെ." നബി(സ) അവരിലേക്ക് ഇവ്വിഷയകമായി കത്തയച്ചു. അവർ തിരിച്ചെഴുതി: നിശ്ചയം ഞങ്ങളയാളെ കൊന്നിട്ടില്ല. ഹുവയ്യിസ(റ), മുഹയ്യിസ(റ), അബ്ദുർറഹ്മാൻ(റ) എന്നിവരോടായി നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സത്യം ചെയ്യുന്നുണ്ടോ, അങ്ങനെയെങ്കിൽ നിങ്ങളുടെ കൂട്ടുകാരന്റെ നഷ്ടപരിഹാരം നിങ്ങൾക്ക് കിട്ടും." അവർ പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കു വേണ്ടി ജൂതർ സത്യം ചെയ്താലോ?" അവർ പറഞ്ഞു: അവർ മുസ്ലിംകളല്ലല്ലോ, അപ്പോൾ നബി(സ) സ്വന്തം വകയിൽ നിന്ന് അയാൾക്ക് നഷ്ടപരിഹാരം നൽകി. അവർക്ക് നബി(സ) നൂറ് ഒട്ടകം അവരുടെ വീട്ടിലേക്ക് അയച്ചുകൊടുത്തു. സഹ്ൽ(റ) പറയുന്നു: അതിൽ പെട്ട ഒരു ചുവന്ന ഒട്ടകം എന്നെ ചവിട്ടി. (ബു,മു,ന,ജ)', 'سَهْلِ بْنِ أَبِي حَثْمَةَ، عَنْ رِجَالٍ مِنْ كُبَرَاءِ قَوْمِهِ', 'സഹ്ലുബ്നു അബീഹസ്മ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 526, 527, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَوَّلُ قَسَامَةٍ كَانَتْ فِي الْجَاهِلِيَّةِ: كَانَ رَجُلٌ مِنْ بَنِي هَاشِمٍ اسْتَأْجَرَ رَجُلًا مِنْ قُرَيْشٍ مِنْ فَخِذِ أَحَدِهِمْ، قَالَ: فَانْطَلَقَ مَعَهُ فِي إِبِلِهِ، فَمَرَّ بِهِ رَجُلٌ مِنْ بَنِي هَاشِمٍ قَدِ انْقَطَعَتْ عُرْوَةُ جُوَالِقِهِ، فَقَالَ: أَغِثْنِي بِعِقَالٍ أَشُدُّ بِهِ عُرْوَةَ جُوَالِقِي، لَا تَنْفِرُ الْإِبِلُ. فَأَعْطَاهُ عِقَالًا يَشُدُّ بِهِ عُرْوَةَ جُوَالِقِهِ، فَلَمَّا نَزَلُوا وَعُقِلَتِ الْإِبِلُ إِلَّا بَعِيرًا وَاحِدًا، فَقَالَ الَّذِي اسْتَأْجَرَهُ: مَا شَأْنُ هَذَا الْبَعِيرِ لَمْ يُعْقَلْ مِنْ بَيْنِ الْإِبِلِ؟ قَالَ: لَيْسَ لَهُ عِقَالٌ. قَالَ: فَأَيْنَ عِقَالُهُ؟ قَالَ مَرَّ بِي رَجُلٌ مِنْ بَنِي هَاشِمٍ قَدِ انْقَطَعَتْ عُرْوَةُ جُوَالِقِهِ، فَاسْتَغَاثَنِي فَقَالَ: أَغِثْنِي بِعِقَالٍ أَشُدُّ بِهِ عُرْوَةَ جُوَالِقِي لَا تَنْفِرُ الْإِبِلُ، فَأَعْطَيْتُهُ عِقَالًا. فَحَذَفَهُ بِعَصًا كَانَ فِيهَا أَجَلُهُ، فَمَرَّ بِهِ رَجُلٌ مِنْ أَهْلِ الْيَمَنِ فَقَالَ: أَتَشْهَدُ الْمَوْسِمَ؟ قَالَ: مَا أَشْهَدُ، وَرُبَّمَا شَهِدْتُ. قَالَ: هَلْ أَنْتَ مُبَلِّغٌ عَنِّي رِسَالَةً مَرَّةً مِنَ الدَّهْرِ؟ قَالَ: نَعَمْ. قَالَ: إِذَا شَهِدْتَ الْمَوْسِمَ فَنَادِ: يَا آلَ قُرَيْشٍ، فَإِذَا أَجَابُوكَ فَنَادِ: يَا آلَ هَاشِمٍ، فَإِذَا أَجَابُوكَ فَسَلْ عَنْ أَبِي طَالِبٍ فَأَخْبِرْهُ: أَنَّ فُلَانًا قَتَلَنِي فِي عِقَالٍ. وَمَاتَ الْمُسْتَأْجَرُ، فَلَمَّا قَدِمَ الَّذِي اسْتَأْجَرَهُ أَتَاهُ أَبُو طَالِبٍ فَقَالَ: مَا فَعَلَ صَاحِبُنَا؟ قَالَ: مَرِضَ، فَأَحْسَنْتُ الْقِيَامَ عَلَيْهِ، ثُمَّ مَاتَ، فَنَزَلْتُ فَدَفَنْتُهُ. فَقَالَ: كَانَ ذَا أَهْلَ ذَاكَ مِنْكَ. فَمَكُثَ حِينًا، ثُمَّ إِنَّ الرَّجُلَ الْيَمَانِيَّ الَّذِي كَانَ أَوْصَى إِلَيْهِ أَنْ يُبَلِّغَ عَنْهُ وَافَى الْمَوْسِمَ، قَالَ: يَا آلَ قُرَيْشٍ. قَالُوا: هَذِهِ قُرَيْشٌ. قَالَ: يَا آلَ بَنِي هَاشِمٍ. قَالُوا: هَذِهِ بَنُو هَاشِمٍ. قَالَ: أَيْنَ أَبُو طَالِبٍ؟ قَالَ: هَذَا أَبُو طَالِبٍ. قَالَ: أَمَرَنِي فُلَانٌ أَنْ أُبَلِّغَكَ رِسَالَةً: أَنَّ فُلَانًا قَتَلَهُ فِي عِقَالٍ. فَأَتَاهُ أَبُو طَالِبٍ فَقَالَ: اخْتَرْ مِنَّا إِحْدَى ثَلَاثٍ: إِنْ شِئْتَ أَنْ تُؤَدِّيَ مِائَةً مِنَ الْإِبِلِ، فَإِنَّكَ قَتَلْتَ صَاحِبَنَا خَطَأً. وَإِنْ شِئْتَ يَحْلِفْ خَمْسُونَ مِنْ قَوْمِكَ: أَنَّكَ لَمْ تَقْتُلْهُ. فَإِنْ أَبَيْتَ قَتَلْنَاكَ بِهِ. فَأَتَى قَوْمَهُ فَذَكَرَ ذَلِكَ لَهُمْ، فَقَالُوا: نَحْلِفُ. فَأَتَتْهُ امْرَأَةٌ مِنْ بَنِي هَاشِمٍ كَانَتْ تَحْتَ رَجُلٍ مِنْهُمْ قَدْ وَلَدَتْ لَهُ، فَقَالَتْ: يَا أَبَا طَالِبٍ، أُحِبُّ أَنْ تُجِيزَ ابْنِي هَذَا بِرَجُلٍ مِنَ الْخَمْسِينَ، وَلَا تُصْبِرْ يَمِينَهُ. فَفَعَلَ، فَأَتَاهُ رَجُلٌ مِنْهُمْ فَقَالَ: يَا أَبَا طَالِبٍ، أَرَدْتَ خَمْسِينَ رَجُلًا أَنْ يَحْلِفُوا مَكَانَ مِائَةٍ مِنَ الْإِبِلِ، يُصِيبُ كُلَّ رَجُلٍ بَعِيرَانِ، فَهَذَانِ بَعِيرَانِ فَاقْبَلْهُمَا عَنِّي وَلَا تُصْبِرْ يَمِينِي حَيْثُ تُصْبَرُ الْأَيْمَانُ. فَقَبِلَهُمَا، وَجَاءَ ثَمَانِيَةٌ وَأَرْبَعُونَ رَجُلًا حَلَفُوا. قَالَ ابْنُ عَبَّاسٍ: فَوَالَّذِي نَفْسِي بِيَدِهِ، مَا حَالَ الْحَوْلُ وَمِنَ الثَّمَانِيَةِ وَالْأَرْبَعِينَ عَيْنٌ تَطْرِفُ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ജാഹിലിയ്യാ കാലത്തുണ്ടായ ആദ്യത്തെ ഖസാമത് (കൊല്ലപ്പെട്ടവന്റെ അവകാശികൾ കൊല സ്ഥിരീകരിക്കാൻ വേണ്ടി കൂട്ട സത്യം ചെയ്യൽ) താഴെ വിവരിക്കുന്നതുപോലെയിരുന്നു: ഖുറൈശീ ഉപഗോത്രത്തിൽ പെട്ട ഒരാളെ ബനൂഹാശിമിൽ പെട്ട ഒരാൾ കൂലിക്കെടുത്തു. അയാൾ അദ്ദേഹത്തിന്റെ ഒട്ടക സംഘത്തിൽ ഒപ്പം കൂടി. ഇടയിൽ, കൂലിക്ക് വിളിക്കപ്പെട്ടവന്റെ അരികിലൂടെ ഒരു ഹാശിമി നടന്നു പോയി. അയാളുടെ തോൽപ്പാത്രത്തിന്റെ പിടി പൊട്ടിയിരുന്നു. അയാൾ പറഞ്ഞു: ഒട്ടകത്തിന്റെ കയർ തന്ന് എന്നെ സഹായിക്കൂ. അതു കൊണ്ട് എന്റെ തോൽപ്പാത്രത്തിന്റെ പിടി കെട്ടാം. ഒട്ടകം വിരന്നോടുകയില്ല. അപ്പോൾ കൂലിക്ക് വിളിക്കപ്പെട്ടവൻ തോൽപ്പാത്രം കെട്ടാൻ ഒട്ടകക്കയർ അയാൾക്ക് നൽകി. അങ്ങനെ അവർ ഒരിടത്ത് ഇറങ്ങിയപ്പോൾ ഒരൊട്ടകമല്ലാത്ത എല്ലാറ്റിനെയും കെട്ടിയിട്ടു. അപ്പോൾ കൂലിക്ക് വിളിച്ചവൻ ചോദിച്ചു: എന്താണ് ഈ ഒട്ടകത്തെ മാത്രം കെട്ടിയിടാത്തത്? അയാൾ പറഞ്ഞു: അതിന് കയറില്ല. കൂലിക്ക് വിളിച്ചവൻ ചോദിച്ചു: എവിടെ അതിന്റെ കയർ? അയാൾ പറഞ്ഞു: എന്റെ അരികിലൂടെ ബനൂ ഹാശിമിൽ പെട്ട ഒരാൾ നടന്ന് പോയിരുന്നു. അയാളുടെ തോൽപ്പാത്രത്തിന്റെ പിടി പൊട്ടിയപ്പോൾ അയാൾ എന്നോട്, എന്റെ തോൽപ്പാത്രത്തിന്റെ പിടി കെട്ടാൻ ഒരു ഒട്ടകക്കയർ തന്നു സഹായിക്കൂ, എന്ന് സഹായമഭ്യർത്ഥിച്ചു, ഒട്ടകം പിടിവിട്ടു പോവുകയില്ലെന്നും പറഞ്ഞു. ഞാനയാൾക്ക് ഒരു കയർ എടുത്ത് കൊടുത്തു. അപ്പോൾ കൂലിക്ക് വിളിച്ചവൻ ഒരു വടി കൊണ്ട് അയാളെ എറിഞ്ഞു. ആ ഏറിൽ അയാളുടെ ആയുസ്സ് നിർണ്ണയിക്കപ്പെട്ടിരുന്നു. ഉടനെ കൂലിക്ക് വിളിക്കപ്പെട്ടവന്റെ അടുത്തുകൂടെ ഒരു യമനി നടന്ന് പോയി. അയാൾ യമനിയോട് ചോദിച്ചു: നിങ്ങൾ മൗസിമിൽ പോകുമോ? യമനി പറഞ്ഞു: ഇല്ല. ഒരു പക്ഷെ പോയെന്നും വരും. അയാൾ ചോദിച്ചു: നിങ്ങൾ ഒരു സന്ദേശം അവർക്കെന്നെങ്കിലും എത്തിച്ചു കൊടുക്കുമോ? യമനി പറഞ്ഞു: അതെ. അയാൾ പറഞ്ഞു: നിങ്ങൾ മൗസിമിൽ എത്തിയാൽ ഉച്ചത്തിൽ വിളിച്ച് പറയുക: ഓ, ഖുറൈശികളേ. അവർ നിങ്ങൾക്ക് ഉത്തരം നൽകിയാൽ നിങ്ങൾ വീണ്ടും ഉച്ചത്തിൽ വിളിച്ച് പറയുക: ഓ, ഹാശിമിന്റെ സന്തതികളേ. അവർ നിങ്ങൾക്ക് മറുപടി നൽകിയാൽ നിങ്ങൾ അവരോട് അബൂത്വാലിബിനെ കുറിച്ച് അന്വേഷിക്കുക. എന്നിട്ട് അബൂത്വാലിബിനോട് പറയുക: ഇന്നാലിന്നവൻ ഒരു ഒട്ടകത്തിന്റെ കയറിന്റെ പേരിൽ എന്നെ കൊന്നിരിക്കുന്നു. അങ്ങനെ കൂലിക്ക് വിളിക്കപ്പെട്ടവൻ മരിച്ചു. കൂലിക്കെടുത്തവൻ നാട്ടിൽ വന്നപ്പോൾ അബൂത്വാലിബ് അദ്ദേഹത്തെ സമീപിച്ചു കൊണ്ട് ചോദിച്ചു: ഞങ്ങളുടെ ആളെ നീ എന്ത് ചെയ്തു? അയാൾ പറഞ്ഞു: അയാൾ രോഗിയായി, ഞാനദ്ദേഹത്തെ പരിചരിച്ചു. പിന്നെ അദ്ദേഹം മരണപ്പെട്ടു. ഞാൻ യാത്ര നിർത്തി അദ്ദേഹത്തെ മറവ് ചെയ്തു. അന്നേരം അബൂത്വാലിബ് പറഞ്ഞു: അവൻ നിന്റെ കൂട്ടരുടെ കൂടെയായിരുന്നല്ലോ (നിനക്കെന്തും ചെയ്യാമല്ലോ). അങ്ങനെ കാലം കടന്നുപോയി. അങ്ങനെ അയാളുടെ സന്ദേശം എത്തിക്കാമെന്നേറ്റെടുത്ത യമനി മൗസിമിൽ വന്നു. അദ്ദേഹം വിളിച്ചു: ഖുറൈശികളേ. അവർ വിളി കേട്ടു. അദ്ദേഹം വീണ്ടും വിളിച്ചു: ഓ ഹാശിം സന്തതികളേ! അവരും വിളി കേട്ടു. അദ്ദേഹം ചോദിച്ചു: എവിടെയാണ് അബൂത്വാലിബ്? അബൂത്വാലിബ് പറഞ്ഞു: ഞാനാണ് അബൂത്വാലിബ്. യമനി പറഞ്ഞു: ഇന്നാലിന്നവൻ ഒരു സന്ദേശം നിങ്ങൾക്കെത്തിക്കാൻ എന്നോട് ആവശ്യപ്പെട്ടിട്ടുണ്ട്. അദ്ദേഹത്തെ ഇന്നവൻ ഒട്ടകത്തിന്റെ കയറിന്റെ പേരിൽ കൊന്നിരിക്കുന്നു. അപ്പോൾ അബൂത്വാലിബ് കൂലിക്ക് വിളിച്ചവന്റെ അടുത്തുചെന്നു. എന്നിട്ട് പറഞ്ഞു: മൂന്നിലൊന്ന് നിനക്ക് തെരഞ്ഞെടുക്കാം. നീ ഞങ്ങളിൽ നിന്നൊരാളെ അവിചാരിതമായി കൊല ചെയ്തിരിക്കുന്നു. ഒന്നുകിൽ നൂറ് ഒട്ടകം നഷ്ടപരിഹാരമായി നൽകണം. അല്ലെങ്കിൽ നീ അവനെ കൊന്നിട്ടില്ലെന്ന് നിന്റെ കുടുംബത്തിൽ പെട്ട അമ്പത് പേർ സത്യം ചെയ്യണം. അതിനും നീ വിസമ്മതിച്ചാൽ ഞങ്ങൾ അവന് പകരമായി നിന്നെ വധിക്കും. ഉടനെ അയാൾ തന്റെ കുടുംബത്തിൽ ചെന്ന് കാര്യം പറഞ്ഞു. അവർ പറഞ്ഞു: ഞങ്ങൾ സത്യംചെയ്യാൻ തയ്യാറാണ്. അപ്പോൾ അബൂത്വാലിബിന്റെ അടുത്ത് ബനൂഹാശിമിൽ പെട്ട ഒരു സ്ത്രീ വന്നു. അവൾ അവരിൽ ഒരാളുടെ കീഴിലായിരുന്നു. അയാളിൽ നിന്ന് ഒരു കുട്ടിയുമുണ്ടായിരുന്നു അവൾക്ക്. അവൾ പറഞ്ഞു: ഓ അബൂത്വാലിബ്, അമ്പതിൽ ഒരാൾക്ക് പകരം എന്റെ ഈ പുത്രനെ  വെക്കാൻ ഞാനാഗ്രഹിക്കുന്നു. ഇവനെ നിങ്ങൾ സത്യംചെയ്യാൻ പിടിച്ചുവെക്കരുത്. അബൂത്വാലിബ് അനുസരിച്ചു. അന്നേരം കൂലിക്ക് വിളിച്ചവന്റെ സമൂഹത്തിൽപെട്ട മറ്റൊരാൾ  കൂടി അബൂത്വാലിബിനെ സമീപിച്ചു പറഞ്ഞു: അബൂത്വാലിബേ, നൂറ് ഒട്ടകങ്ങൾക്ക് പകരം അമ്പത് ആളുകൾ സത്യംചെയ്യുമെന്ന് നിങ്ങളുദ്ദേശിക്കുന്നു. രണ്ട് ഒട്ടകത്തിന് ഒരാൾ എന്ന തോതിൽ. ഇതാ രണ്ട് ഒട്ടകം. എനിക്ക് പകരം ഇത് സ്വീകരിക്കുക. സത്യംചെയ്യുന്ന സമയത്ത് സത്യംചെയ്യാൻ എന്നെ പിടിച്ചുവെക്കരുത്. അബൂത്വാലിബ് അവയെ സ്വീകരിച്ചു. നാൽപത്തിയെട്ട് ആളുകൾ വന്നു. അവർ സത്യം ചെയ്തു. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, ഒരു വർഷം തികയുമ്പോഴേക്കും നാൽപത്തിയെട്ട് പേരും കോങ്കണ്ണന്മാരായി. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 527, 529, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ يَهُودِيَّةً مِنْ أَهْلِ خَيْبَرَ سَمَّتْ شَاةً مَصْلِيَّةً، ثُمَّ أَهْدَتْهَا لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخَذَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الذِّرَاعَ فَأَكَلَ مِنْهَا، وَأَكَلَ رَهْطٌ مِنْ أَصْحَابِهِ مَعَهُ، ثُمَّ قَالَ لَهُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ارْفَعُوا أَيْدِيَكُمْ". وَأَرْسَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَهُودِيَّةِ فَدَعَاهَا، فَقَالَ لَهَا: "أَسَمَمْتِ هَذِهِ الشَّاةَ". قَالَتِ الْيَهُودِيَّةُ: مَنْ أَخْبَرَكَ؟ قَالَ: "أَخْبَرَتْنِي هَذِهِ فِي يَدِي" لِلذِّرَاعِ، قَالَتْ: نَعَمْ، قَالَ: "فَمَا أَرَدْتِ إِلَى ذَلِكَ". قَالَتْ: قُلْتُ: إِنْ كَانَ نَبِيًّا فَلَنْ يَضُرَّهُ، وَإِنْ لَمْ يَكُنْ نَبِيًّا اسْتَرَحْنَا مِنْهُ. فَعَفَا عَنْهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يُعَاقِبْهَا، وَتُوُفِّيَ بَعْضُ أَصْحَابِهِ الَّذِينَ أَكَلُوا مِنَ الشَّاةِ، وَاحْتَجَمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى كَاهِلِهِ مِنْ أَجْلِ الَّذِي أَكَلَ مِنَ الشَّاةِ، حَجَمَهُ أَبُو هِنْدٍ بِالْقَرْنِ وَالشَّفْرَةِ، وَهُوَ مَوْلًى لِبَنِي بَيَاضَةَ مِنَ الأَنْصَارِ. (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഖൈബർ നിവാസിയായ ഒരു ജൂതസ്ത്രീ വേവിച്ച ആട്ടിറച്ചിയിൽ വിഷം ചേർത്തു. അവളത് നബി(സ)ക്ക് ഹദ്യ നൽകി. നബി(സ) കൊറുകെടുത്ത് ഭക്ഷിക്കാൻ തുടങ്ങി. ഒരു കൂട്ടം സ്വഹാബികളും നബി(സ)യുടെ കൂടെ ഭക്ഷിച്ചു. പിന്നീട് നബി(സ) സ്വഹാബികളോടായി പറഞ്ഞു: "നിങ്ങൾ കൈയ്യുയർത്തുക." ജൂതസ്ത്രീയുടെ അടുത്തേക്ക് നബി(സ) ആളയച്ച് അവളെ വിളിപ്പിച്ചു. നബി(സ) അവളോട് ചോദിച്ചു: "നീ ആടിൽ വിഷം ചേർത്തിയിരുന്നോ?" ജൂതസ്ത്രീ ചോദിച്ചു: ആരാണ് നിങ്ങൾക്കത് പറഞ്ഞുതന്നത്? നബി(സ) പറഞ്ഞു: "എന്റെ കയ്യിലുള്ള ഈ കൊറുകാണ് എനിക്കത് പറഞ്ഞുതന്നത്." അവൾ പറഞ്ഞു: അതെ. നബി(സ) ചോദിച്ചു: "നിന്റെ ഉദ്ദേശ്യമെന്തായിരുന്നു?" ജൂതസ്ത്രീ പറഞ്ഞു: അദ്ദേഹം നബിയാണെങ്കിൽ അദ്ദേഹത്തിനത് ഏശുകയില്ല. അദ്ദേഹം നബിയല്ലെങ്കിൽ ഞങ്ങൾക്കദ്ദേഹത്തിൽ നിന്ന് സ്വൈര്യം കിട്ടുമല്ലോ! നബി(സ) അവൾക്ക് മാപ്പ് നൽകി, അവളെ ശിക്ഷിച്ചില്ല. ആട്ടിറച്ചി ഭക്ഷിച്ച ചില സ്വഹാബികൾ വഫാത്തായി. ആട്ടിറച്ചി ഭക്ഷിച്ച കാരണത്താൽ നബി(സ) തന്റെ പിരടിയിൽ കൊമ്പുവെച്ചു. അബൂഹിന്ദാണ് കത്തി, കൊമ്പ് എന്നിവ ഉപയോഗിച്ച് നബി(സ)യെ കൊമ്പുവെച്ചത്. അൻസാറുകളിൽ പെട്ട ബനൂബയാളയിലെ അടിമയാണ് അദ്ദേഹം. (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 529, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ جَارِيَةً كَانَ عَلَيْهَا أَوْضَاحٌ لَهَا، فَرَضَخَ رَأْسَهَا يَهُودِيٌّ بِحَجَرٍ، فَدَخَلَ عَلَيْهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَبِهَا رَمَقٌ، فَقَالَ لَهَا: "مَنْ قَتَلَكِ؟ فُلَانٌ قَتَلَكِ". فَقَالَتْ: لَا، بِرَأْسِهَا، قَالَ: "فُلَانٌ قَتَلَكِ". قَالَتْ: نَعَمْ، بِرَأْسِهَا، فَأَمَرَ بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُتِلَ بَيْنَ حَجَرَيْنِ. (ق,د,ن,جه)', 'അനസ്(റ): വെള്ളിയാഭരണങ്ങൾ ധരിച്ച ഒരു പെൺകുട്ടിയുണ്ടായിരുന്നു. ഒരു ജൂതൻ കല്ല് കൊണ്ട് അവളുടെ തലക്കടിച്ചു. അങ്ങനെ അവൾ മരണാസന്നയായി അവസാനശ്വാസം വലിച്ചുകൊണ്ടിരിക്കവെ റസൂൽ(സ) അവളുടെയടുത്തേക്ക് കടന്നുവന്നു. എന്നിട്ട് അവിടന്ന് ചോദിച്ചു: "ആരാണ് നിന്നെ കൊന്നത്? ഇന്നയാളാണോ നിന്നെ കൊന്നത്?" അവൾ തലകൊണ്ട് ആംഗ്യേന ''അല്ല'' എന്നു പറഞ്ഞു. തിരുമേനി(സ) ചോദിച്ചു: "ഇന്നവനാണോ നിന്നെ കൊന്നത്?" അവൾ ആംഗ്യേന ''അതെ'' എന്നു പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ)യുടെ കൽപനപ്രകാരം അയാളെ രണ്ട് കല്ലുകൾക്കിടയിലിട്ടു കൊന്നു. (ബു,മു,ദ,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذْ جِيءَ بِرَجُلٍ قَاتِلٍ فِي عُنُقِهِ النِّسْعَةُ، قَالَ: فَدَعَا وَلِيَّ الْمَقْتُولِ فَقَالَ: "أَتَعْفُو". قَالَ: لَا، قَالَ: "أَفَتَأْخُذُ الدِّيَةَ". قَالَ: لَا، قَالَ: "أَفَتَقْتُلُ". قَالَ: نَعَمْ، قَالَ: "اذْهَبْ بِهِ". فَلَمَّا وَلَّى قَالَ: "أَتَعْفُو". قَالَ: لَا، قَالَ: "أَفَتَأْخُذُ الدِّيَةَ". قَالَ: لَا، قَالَ: "أَفَتَقْتُلُ". قَالَ: نَعَمْ، قَالَ: "اذْهَبْ بِهِ". فَلَمَّا كَانَ فِي الرَّابِعَةِ قَالَ: "أَمَا إِنَّكَ إِنْ عَفَوْتَ عَنْهُ يَبُوءُ بِإِثْمِهِ وَإِثْمِ صَاحِبِهِ". قَالَ: فَعَفَا عَنْهُ، قَالَ: فَأَنَا رَأَيْتُهُ يَجُرُّ النِّسْعَةَ. (د,ن)', 'വാഇലുബ്നു ഹുജ്ർ(റ): ഞാൻ പ്രവാചക സന്നിധിയിലാവുമ്പോൾ പിരടിയിൽ കയർ ബന്ധിച്ച ഘാതകനെ കൊണ്ടുവന്നു. നബി(സ) വധിക്കപ്പെട്ടവന്റെ രക്ഷിതാവിനെ വിളിച്ചു. എന്നിട്ടദ്ദേഹത്തോട് ചോദിച്ചു: "നിങ്ങൾ മാപ്പ് കൊടുക്കുമോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. "നിങ്ങൾ നഷ്ടപരിഹാരം സ്വീകരിക്കുമോ?" റസൂൽ(സ) വീണ്ടും ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾ അദ്ദേഹത്തെ കൊല്ലുകയാണോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "എന്നാൽ നിങ്ങളദ്ദേഹത്തെ കൊണ്ടുപോകുക." അദ്ദേഹം പിന്തിരിഞ്ഞപ്പോൾ നബി(സ) ചോദിച്ചു: "നിങ്ങൾ മാപ്പുകൊടുക്കുന്നുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. "നിങ്ങൾ നഷ്ടപരിഹാരം സ്വീകരിക്കുന്നുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. നബി(സ) വീണ്ടും ചോദിച്ചു: "നിങ്ങൾ അദ്ദേഹത്തെ കൊല്ലുകയാണോ?" അതെ, അദ്ദേഹം പ്രതികരിച്ചു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അദ്ദേഹത്തെ കൊണ്ടുപോകുക." നാലാം പ്രാവശ്യം പ്രവാചകൻ(സ) പറഞ്ഞു: "നിങ്ങൾ അദ്ദേഹത്തിന് മാപ്പ് കൊടുക്കുകയാണെങ്കിൽ തന്റെ പാപവും വധിക്കപ്പെട്ടവന്റെ പാപവും അദ്ദേഹം വഹിക്കേണ്ടി വരും." അപ്പോൾ അയാൾ അദ്ദേഹത്തിന് മാപ്പ് കൊടുത്തു. വാഇലുബ്നു ഹുജ്ർ പറയുന്നു: അദ്ദേഹം കയർ വലിച്ചുനടക്കുന്നത് ഞാൻ കണ്ടു. (ദ,ന)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 530, 530, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ عَنْ أَبِيهِ قَالَ مُوسَى: وَجَدِّهِ – رَضِيَ اللهُ عَنْهُمَا – وَكَانَا شَهِدَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حُنَيْنًا: أَنَّ مُحَلِّمَ بْنَ جَثَّامَةَ اللَّيْثِيَّ قَتَلَ رَجُلًا مِنْ أَشْجَعَ فِي الْإِسْلَامِ، وَذَلِكَ أَوَّلُ غِيَرٍ قَضَى بِهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَتَكَلَّمَ عُيَيْنَةُ فِي قَتْلِ الأَشْجَعِيِّ لِأَنَّهُ مِنْ غَطَفَانَ، وَتَكَلَّمَ الأَقْرَعُ بْنُ حَابِسٍ دُونَ مُحَلِّمٍ لِأَنَّهُ مِنْ خِنْدِفَ، فَارْتَفَعَتِ الأَصْوَاتُ وَكَثُرَتِ الْخُصُومَةُ وَاللَّغَطُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عُيَيْنَةُ أَلَا تَقْبَلُ الْغِيَرَ". فَقَالَ عُيَيْنَةُ: لَا وَاللهِ حَتَّى أُدْخِلَ عَلَى نِسَائِهِ مِنَ الْحَرْبِ وَالْحُزْنِ مَا أَدْخَلَ عَلَى نِسَائِي. قَالَ: ثُمَّ ارْتَفَعَتِ الأَصْوَاتُ وَكَثُرَتِ الْخُصُومَةُ وَاللَّغَطُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عُيَيْنَةُ أَلَا تَقْبَلُ الْغِيَرَ". فَقَالَ عُيَيْنَةُ مِثْلَ ذَلِكَ أَيْضًا، إِلَى أَنْ قَامَ رَجُلٌ مِنْ بَنِي لَيْثٍ يُقَالُ لَهُ مُكَيْتِلٌ، عَلَيْهِ شِكَّةٌ وَفِي يَدِهِ دَرَقَةٌ، فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي لَمْ أَجِدْ لِمَا فَعَلَ هَذَا فِي غُرَّةِ الإِسْلَامِ مَثَلًا إِلَّا غَنَمًا وَرَدَتْ، فَرُمِيَ أَوَّلُهَا فَنَفَرَ آخِرُهَا، اسْنُنِ الْيَوْمَ وَغَيِّرْ غَدًا. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَمْسُونَ فِي فَوْرِنَا هَذَا وَخَمْسُونَ إِذَا رَجَعْنَا إِلَى الْمَدِينَةِ". وَذَلِكَ فِي بَعْضِ أَسْفَارِهِ، وَمُحَلِّمٌ رَجُلٌ طَوِيلٌ آدَمُ، وَهُوَ فِي طَرَفِ النَّاسِ، فَلَمْ يَزَالُوا حَتَّى تَخَلَّصَ فَجَلَسَ بَيْنَ يَدَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَيْنَاهُ تَدْمَعَانِ، فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي قَدْ فَعَلْتُ الَّذِي بَلَغَكَ، وَإِنِّي أَتُوبُ إِلَى اللهِ تَبَارَكَ وَتَعَالَى، فَاسْتَغْفِرِ اللهَ عَزَّ وَجَلَّ لِي يَا رَسُولَ اللهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَقَتَلْتَهُ بِسِلَاحِكَ فِي غُرَّةِ الإِسْلَامِ، اللَّهُمَّ لَا تَغْفِرْ لِمُحَلِّمٍ" بِصَوْتٍ عَالٍ، فَقَامَ وَإِنَّهُ لَيَتَلَقَّى دُمُوعَهُ بِطَرَفِ رِدَائِهِ، قَالَ ابْنُ إِسْحَقَ: فَزَعَمَ قَوْمُهُ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اسْتَغْفَرَ لَهُ بَعْدَ ذَلِكَ. (د)', 'ഉർവതുബ്നു സുബൈർ(റ) സ്വന്തം പിതാവിൽ നിന്നും വലിയുപ്പയിൽ നിന്നും നിവേദനം: അവർ രണ്ടുപേരും റസൂൽ(സ)യോടു കൂടെ ഹുനൈനിൽ പങ്കെടുത്തവരാണ്: ലൈസ് ഗോത്രക്കാരനായ മുഹല്ലമുബ്നു ജസ്സാമ എന്നയാൾ അശ്ജഅ് ഗോത്രത്തിൽ പെട്ട ഒരാളെ ഇസ്ലാമിന്റെ ആദ്യകാലത്ത് കൊലചെയ്തു. റസൂൽ(സ) ആദ്യമായി നഷ്ടപരിഹാരം വിധിച്ച സംഭവമാണത്. അശ്ജഇയുടെ കൊലയെക്കുറിച്ച് ഉയൈന സംസാരിച്ചു. കാരണം അദ്ദേഹം ഗഥ്ഫാൻ ഗോത്രത്തിൽ പെട്ടവരാണ്. അഖ്റഉബ്നു ഹാബിസ് എന്നയാൾ മുഹല്ലിമിന് വേണ്ടി സംസാരിച്ചു. കാരണം അദ്ദേഹം ഖിൻദഖ് ഗോത്രത്തിൽ പെട്ടയാളാണ്. ശബ്ദകോലാഹലങ്ങളും തർക്കവിതർക്കങ്ങളും അധികരിച്ചു. റസൂൽ(സ) ചോദിച്ചു: "ഉയൈനാ, നിങ്ങൾ നഷ്ടപരിഹാരം സ്വീകരിക്കുന്നുവോ?" അപ്പോൾ ഉയൈന പറഞ്ഞു: ഇല്ല, അല്ലാഹുവാണ് സത്യം, എന്റെ സ്ത്രീകൾ സഹിച്ചതുപോലെ ദുഃഖവും പോരാട്ടവും അവന്റെ സ്ത്രീകളും സഹിക്കുന്നത് വരെ. നിവേദകൻ പറയുന്നു: വീണ്ടും തർക്കവിതർക്കവും ശബ്ദകോലാഹലങ്ങളും ഉയർന്നു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഉയൈനാ, നിങ്ങൾ നഷ്ടപരിഹാരം സ്വീകരിക്കുന്നുവോ?" ഉയൈന ആദ്യത്തെ പോലെ വീണ്ടും പറഞ്ഞു. ബനുല്ലൈസ് ഗോത്രത്തിൽ നിന്നും മുകൈതിൽ എന്നൊരാൾ എണീക്കുന്നത് വരെ അത് തുടർന്നു. അദ്ദേഹത്തിന്റെ അടുത്ത് ആയുധവും തോൽ കൊണ്ട് നിർമ്മിച്ച പരിചയുമുണ്ട്. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇദ്ദേഹം ചെയ്ത ഈ പ്രവർത്തനത്തിന് ഇസ്ലാമിന്റെ പ്രാരംഭത്തിൽ ഞാനൊരു ഉപമ കാണുന്നില്ല, ഇതല്ലാതെ; ഒരാട്ടിൻപറ്റം മുന്നിട്ടു വന്നു, അതിൽ നിന്ന് ഒന്നിനെ മുറിവേൽപിച്ചു. അപ്പോൾ എല്ലാം തന്നെ പിന്തിരിഞ്ഞു. ഇന്ന് ഒരു നിയമമുണ്ടാക്കുക, നാളെ അത് മാറ്റുകയും ചെയ്യുക. റസൂൽ(സ) പറഞ്ഞു: "ഇപ്പോൾ 50 ഒട്ടകത്തെ നഷ്ടപരിഹാരമായി സ്വീകരിക്കുക. 50 എണ്ണം മദീനയിൽ മടങ്ങിയെത്തിയതിന് ശേഷവും." അത് യാത്രയുടെ ഇടയിലായിരുന്നു. മുഹല്ലിം നീണ്ട തവിട്ടുനിറത്തിലുള്ള മനുഷ്യനാണ്. അദ്ദേഹം ജനങ്ങൾക്കിടയിലായിരുന്നു. അദ്ദേഹം ഇടയിലൂടെ വന്ന് തിരുമേനി(സ)യുടെ മുമ്പിൽ ഇരിക്കുന്നത് വരെ ജനങ്ങൾ അതേ നില തുടർന്നു. അദ്ദേഹത്തിന്റെ രണ്ട് കണ്ണുകളും ഒലിക്കുന്നുണ്ട്. അദ്ദേഹം പറഞ്ഞു: റസൂലേ, അങ്ങ് അറിഞ്ഞത് ഞാൻ ചെയ്തിട്ടുണ്ട്. അല്ലാഹുവിലേക്ക് ഞാൻ ഖേദിക്കുന്നു. അല്ലാഹുവിനോട് അങ്ങ് എനിക്ക് വേണ്ടി പൊറുക്കലിനെ തേടിയാലും, റസൂലേ. റസൂൽ(സ) പറഞ്ഞു: "ഇസ്ലാമിന്റെ ആദ്യത്തിൽ നീ അവനെ ആയുധം കൊണ്ട് വധിച്ചുവോ, അല്ലാഹുവേ നീ മുഹല്ലിമിന് പൊറുത്തുകൊടുക്കരുത്." വളരെ ഉയർന്ന ശബ്ദത്തിലായിരുന്നു അത്. അദ്ദേഹം എണീറ്റു. വസ്ത്രത്തിന്റെ തലപ്പ് കൊണ്ട് അദ്ദേഹം കണ്ണുനീർ തുടച്ചുകൊണ്ടിരുന്നു. ഇബ്നു ഇസ്ഹാഖ് പറയുന്നു: ഇതിന് ശേഷം തിരുമേനി(സ) അദ്ദേഹത്തിന് വേണ്ടി പൊറുക്കലിനെ തേടിയിട്ടുണ്ടെന്ന് അദ്ദേഹത്തിന്റെ സമൂഹം വാദിക്കുന്നുണ്ട്. (ദ)', 'عُرْوَةَ بْنِ الزُّبَيْرِ عَنْ أَبِيهِ قَالَ مُوسَى', 'ഉർവതുബ്നു സുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 530, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي السَّفَرِ قَالَ: دَقَّ رَجُلٌ مِنْ قُرَيْشٍ سِنَّ رَجُلٍ مِنَ الأَنْصَارِ، فَاسْتَعْدَى عَلَيْهِ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ فَقَالَ لِمُعَاوِيَةَ: يَا أَمِيرَ الْمُؤْمِنِينَ، إِنَّ هَذَا دَقَّ سِنِّي. قَالَ مُعَاوِيَةُ: إِنَّا سَنُرْضِيكَ. وَأَلَحَّ الآخَرُ عَلَى مُعَاوِيَةَ فَأَبْرَمَهُ فَلَمْ يُرْضِهِ، فَقَالَ لَهُ مُعَاوِيَةُ: شَأْنَكَ بِصَاحِبِكَ. وَأَبُو الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ جَالِسٌ عِنْدَهُ، فَقَالَ أَبُو الدَّرْدَاءِ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – قَالَ: سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي – يَقُولُ: "مَا مِنْ رَجُلٍ يُصَابُ بِشَيْءٍ فِي جَسَدِهِ فَيَتَصَدَّقَ بِهِ، إِلَّا رَفَعَهُ اللهُ بِهِ دَرَجَةً وَحَطَّ عَنْهُ بِهِ خَطِيئَةً". قَالَ الأَنْصَارِيُّ: أَأَنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي. قَالَ: فَإِنِّي أَذَرُهَا لَهُ. قَالَ مُعَاوِيَةُ: لَا جَرَمَ، لَا أُخَيِّبُكَ. فَأَمَرَ لَهُ بِمَالٍ. (ت,جه)', 'അബൂസഫർ(റ): ഖുറൈശി ഗോത്രത്തിൽ പെട്ട ഒരു വ്യക്തി ഒരു അൻസാരിയുടെ പല്ല് കുത്തിപ്പൊട്ടിച്ചു. അദ്ദേഹം മുആവിയ(റ)വിനോട് പരാതി പറഞ്ഞു: അമീറുൽ മുഅ്മിനീൻ, ഇയാൾ എന്റെ പല്ല് പൊട്ടിച്ചു. മുആവിയ(റ) പറഞ്ഞു: നിങ്ങളെ ഞാൻ തൃപ്തിപ്പെടുത്താം. ശേഷം അയാൾ മുആവിയ(റ)വിനോട് കൂടുതലായി ചോദ്യമുന്നയിക്കുകയും മടുപ്പിക്കുകയും ചെയ്തു. മുആവിയ(റ)വിനെ അദ്ദേഹം തൃപ്തിപ്പെടുത്തിയില്ല. അപ്പോൾ മുആവിയ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: നിന്റെയാളോട് നിനക്കിഷ്ടമുള്ളതു പ്രകാരം ചെയ്യുക. അദ്ദേഹത്തിന്റെയടുത്ത് അബുദ്ദർദാഅ്(റ) ഇരിക്കുന്നുണ്ടായിരുന്നു. അബൂദ്ദർദാഅ്(റ) പറഞ്ഞു: പ്രവാചകർ(സ) പറഞ്ഞതായി ഞാൻ കേട്ടിട്ടുണ്ട്; എന്റെ കാതുകൾ അവ ശ്രവിച്ചു, ഹൃദയം അവ സൂക്ഷിച്ചു വെച്ചു: "ഒരു വ്യക്തിയുടെ ദേഹത്തിൽ വല്ല പരിക്കും സംഭവിച്ചു. അദ്ദേഹം അത് സഹിക്കുന്നത് ഒരു ധർമ്മമായി കണ്ടു. എന്നാൽ അദ്ദേഹത്തിന്റെ സ്ഥാനം അല്ലാഹു ഉയർത്തുകയും പാപങ്ങൾ പൊറുക്കുകയും ചെയ്യും." അൻസാരി ചോദിച്ചു: നിങ്ങൾ അല്ലാഹുവിന്റെ റസൂലിൽ നിന്ന് അപ്രകാരം കേട്ടിട്ടുണ്ടോ? അബൂദ്ദർദാഅ്(റ) പറഞ്ഞു: അതെന്റെ കാതുകൾ കേൾക്കുകയും ഹൃദയം സൂക്ഷിക്കുകയും ചെയ്തിരിക്കുന്നു. അൻസാരി പറഞ്ഞു: അയാൾക്ക് വേണ്ടി ഞാനത് ഉപേക്ഷിക്കുന്നു. മുആവിയ(റ) പറഞ്ഞു: കുഴപ്പമില്ല. നിങ്ങളെ ഞാൻ നിരാശനാക്കുന്നില്ല. മുആവിയ(റ) അദ്ദേഹത്തിന് സമ്പത്ത് കൊടുക്കാൻ ആവശ്യപ്പെട്ടു. (തു,ജ)', 'أَبِي السَّفَرِ قَالَ', 'അബൂസഫർ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عَلَى الْمُقْتَتِلِينَ أَنْ يَنْحَجِزُوا: الأَوَّلُ فَالأَوَّلُ، وَإِنْ كَانَتِ امْرَأَةً". قَالَ دَاوُدُ: بَلَغَنِي أَنَّ عَفْوَ النِّسَاءِ فِي الْقَتْلِ جَائِزٌ إِذَا كَانَتْ إِحْدَى الأَوْلِيَاءِ. (د,ن)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നു: "കൊല്ലപ്പെട്ടവരുടെ ആളുകൾക്ക് മാപ്പുനൽകാനുള്ള അവകാശമുണ്ട്. അവരിൽ ഏറ്റവും ആദ്യത്തവർക്കാണ് ആ അവകാശം, അത് ഒരു സ്ത്രീയാണെങ്കിലും ശരി." അബൂദാവൂദ്(റ) പറഞ്ഞു: കൊന്നതിന് സത്രീകൾ മാപ്പുനൽകുന്നത് അനുവദനീയമാണ്, അവൾ രക്ഷിതാക്കളിൽ ഒന്നാമത്തെവളാണെങ്കിൽ. (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 532, 532, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُقْتَلُ نَفْسٌ ظُلْمًا إِلَّا كَانَ عَلَى ابْنِ آدَمَ الأَوَّلِ كِفْلٌ مِنْ دَمِهَا، لِأَنَّهُ كَانَ أَوَّلَ مَنْ سَنَّ الْقَتْلَ". (ق,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): പ്രവാചകർ(സ) പറഞ്ഞു: "അവിഹിതമായി ഒരു വ്യക്തി വധിക്കപ്പെടുമ്പോൾ ആദം(അ)ന്റെ ആദ്യ പുത്രന് ആ രക്തത്തിൽ ഒരു പങ്കുണ്ടാകും. കാരണം ആദ്യമായി വധം നടപ്പിലാക്കിയത് അദ്ദേഹമായിരുന്നു." (ബു,മു,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَتَلَ نَفْسَهُ بِحَدِيدَةٍ فَحَدِيدَتُهُ فِي يَدِهِ، يَتَوَجَّأُ بِهَا فِي بَطْنِهِ فِي نَارِ جَهَنَّمَ، خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا. وَمَنْ شَرِبَ سُمًّا فَقَتَلَ نَفْسَهُ فَهُوَ يَتَحَسَّاهُ فِي نَارِ جَهَنَّمَ، خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا. وَمَنْ تَرَدَّى مِنْ جَبَلٍ فَقَتَلَ نَفْسَهُ فَهُوَ يَتَرَدَّى فِي نَارِ جَهَنَّمَ، خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഇരുമ്പുദണ്ഡ് ഉപയോഗിച്ച് ആരെങ്കിലും ആത്മഹത്യ ചെയ്താൽ നരകത്തിൽവെച്ച് ആ ദണ്ഡ് അവൻ എന്നെന്നും വയറ്റിൽ കുത്തിക്കൊണ്ടേയിരിക്കും. വിഷം കുടിച്ച് ആരെങ്കിലും ആത്മഹത്യ ചെയ്താൽ നരകത്തിൽ വെച്ച് ശാശ്വതമായി അത് കഴിക്കേണ്ടി വരും. ആരെങ്കിലും മല മുകളിൽ നിന്ന് ചാടി ആത്മഹത്യ ചെയ്താൽ, അവൻ നരകത്തിലേക്ക് ശാശ്വതനായി നിപതിച്ചു കൊണ്ടിരിക്കും."(ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْكَبَائِرُ: الشِّرْكُ بِاللهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَقَتْلُ النَّفْسِ، وَقَوْلُ الزُّورِ". (ن)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വൻദോഷങ്ങൾ ഇവയൊക്കെയാണ്: അല്ലാഹുവിനോട് പങ്കുചേർക്കൽ, മാതാപിതാക്കളെ ബുദ്ധിമുട്ടിക്കൽ, ആത്മഹത്യ ചെയ്യൽ, നുണ പറയൽ." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْنَا عَلِيًّا فَقُلْنَا: هَلْ عِنْدَكُمْ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَيْءٌ سِوَى الْقُرْآنِ؟ فَقَالَ: لَا وَالَّذِي فَلَقَ الْحَبَّةَ وَبَرَأَ النَّسَمَةَ، إِلَّا أَنْ يُعْطِيَ اللهُ عَزَّ وَجَلَّ عَبْدًا فَهْمًا فِي كِتَابِهِ، أَوْ مَا فِي هَذِهِ الصَّحِيفَةِ. قُلْتُ: وَمَا فِي الصَّحِيفَةِ؟ قَالَ: فِيهَا الْعَقْلُ، وَفِكَاكُ الأَسِيرِ، وَأَنْ لَا يُقْتَلَ مُسْلِمٌ بِكَافِرٍ. (ن,جه)', 'അബൂജുഹൈഫ(റ): ഞങ്ങൾ അലി(റ)വിനോട് ചോദിച്ചു: ഖുർആനല്ലാത്ത വല്ലതും നിങ്ങൾക്ക് അല്ലാഹുവിന്റെ റസൂലിൽ നിന്ന് ലഭിച്ചിട്ടുണ്ടോ? അലി(റ) പറഞ്ഞു: ഇല്ല, ധാന്യങ്ങളെ മുളപ്പിക്കുന്നവനും സൃഷ്ടികളെ പടക്കുകയും ചെയ്തവനെത്തന്നെയാണ് സത്യം, അല്ലാഹു അവന്റെ ഗ്രന്ഥത്തിൽ അടിമക്ക് നൽകിയ അവഗാഹവും ഈ ഏടിൽ ഉള്ളതുമല്ലാതെ മറ്റൊന്നുമില്ല. ഞാൻ ചോദിച്ചു: ഈ ഏടിൽ എന്താണുള്ളത്? അദ്ദേഹം പറഞ്ഞു: ഇതിൽ പ്രതിക്രിയയും അടിമ വിമോചനവുമുണ്ട്. സത്യനിഷേധിയെ കൊന്നതിന് ഒരു മുസ്ലിം വധിക്കപ്പെടരുതെന്നുമുണ്ട്. (ന,ജ)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 533, 533, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ قُرَيْظَةُ وَالنَّضِيرُ، وَكَانَ النَّضِيرُ أَشْرَفَ مِنْ قُرَيْظَةَ، وَكَانَ إِذَا قَتَلَ رَجُلٌ مِنْ قُرَيْظَةَ رَجُلًا مِنَ النَّضِيرِ قُتِلَ بِهِ، وَإِذَا قَتَلَ رَجُلٌ مِنَ النَّضِيرِ رَجُلًا مِنْ قُرَيْظَةَ أَدَّى مِائَةَ وَسْقٍ مِنْ تَمْرٍ، فَلَمَّا بُعِثَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَتَلَ رَجُلٌ مِنَ النَّضِيرِ رَجُلًا مِنْ قُرَيْظَةَ، فَقَالُوا: ادْفَعُوهُ إِلَيْنَا نَقْتُلْهُ. فَقَالُوا: بَيْنَنَا وَبَيْنَكُمُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَأَتَوْهُ، فَنَزَلَتْ: {وَإِنْ حَكَمْتَ فَاحْكُمْ بَيْنَهُمْ بِالْقِسْطِ} [المائدة: ٤٢] وَالْقِسْطُ النَّفْسُ بِالنَّفْسِ، ثُمَّ نَزَلَتْ: {أَفَحُكْمَ الْجَاهِلِيَّةِ يَبْغُونَ} [المائدة: ٥٠] (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഖുറൈള, നളീർ എന്നീ രണ്ടു ഗോത്രങ്ങളുണ്ടായിരുന്നു. നളീർ ഖുറൈളയെക്കാൾ ശ്രേഷ്ഠരായിരുന്നു. ഖുറൈളയിലെ ആരെങ്കിലും നളീറിലെ ഒരംഗത്തെ വധിച്ചാൽ പ്രതിക്രിയയായി അവൻ വധിക്കപ്പെടും. നളീറുകാരൻ ഖുറൈളക്കാരനെ വധിച്ചാൽ നൂറ് വസ്ഖ് കാരക്ക നൽകും. അങ്ങനെ തിരുമേനി(സ)യുടെ നിയോഗത്തിനുശേഷം ഒരു നളീറുകാരൻ ഖുറൈളക്കാരനെ വധിച്ചു. ഖുറൈളക്കാർ പറഞ്ഞു: ഘാതകനെ ഞങ്ങൾക്ക് വിട്ടുതരൂ, ഞങ്ങൾക്കവനെ വധിക്കണം. നളീർഗോത്രക്കാർ പറഞ്ഞു: നിങ്ങൾക്കും ഞങ്ങൾക്കുമിടയിൽ നബി(സ)യുണ്ടല്ലോ. അവർ പ്രവാചകർ(സ)യുടെ സന്നിധിയിൽ പോയി. അപ്പോഴാണ് ''നബിയേ, അങ്ങ് വിധി നടത്തുമ്പോൾ നീതിപൂർവ്വം അവർക്കിടയിൽ വിധി നടപ്പാക്കുക'' (മാഇദ: 42) എന്ന സൂക്തം അവതരിക്കുന്നത്. ശരീരത്തിന് പകരം ശരീരം എന്നതാണ് നീതിയുക്തമായ വിധി. പിന്നീട് ഈ സൂക്തം ഇറങ്ങി: ''ജാഹിലിയ്യത്തിലെ വിധിയാണോ അവർ ആഗ്രഹിക്കുന്നത്.'' (മാഇദ: 50) (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], 'المائدة: ٥٠', null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ قَيْسِ بْنِ عُبَادٍ الْقَيْسِيِّ قَالَ: انْطَلَقْتُ أَنَا وَالأَشْتَرُ إِلَى عَلِيٍّ رَضِيَ اللهُ عَنْهُ فَقُلْنَا: هَلْ عَهِدَ إِلَيْكَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَيْئًا لَمْ يَعْهَدْهُ إِلَى النَّاسِ عَامَّةً؟ قَالَ: لَا، إِلَّا مَا كَانَ فِي كِتَابِي هَذَا. فَأَخْرَجَ كِتَابًا مِنْ قِرَابِ سَيْفِهِ فَإِذَا فِيهِ: "الْمُؤْمِنُونَ تَكَافَأُ دِمَاؤُهُمْ، وَهُمْ يَدٌ عَلَى مَنْ سِوَاهُمْ، وَيَسْعَى بِذِمَّتِهِمْ أَدْنَاهُمْ. أَلَا، لَا يُقْتَلُ مُؤْمِنٌ بِكَافِرٍ، وَلَا ذُو عَهْدٍ بِعَهْدِهِ. مَنْ أَحْدَثَ حَدَثًا فَعَلَى نَفْسِهِ، أَوْ آوَى مُحْدِثًا فَعَلَيْهِ لَعْنَةُ اللهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ". (د,ن)', 'ഖൈസുബ്നു ഉബാദുൽ ഖൈസി(റ): ഞാനും അശ്തറും അലി(റ)വിന്റെ അടുത്തേക്ക് പോയി. ഞങ്ങൾ അലി(റ)വിനോട് ചോദിച്ചു: നബി(സ) ജനങ്ങൾക്ക് പൊതുവായി നൽകാത്തത് നിങ്ങൾക്ക് നൽകിയിട്ടുണ്ടോ? അലി(റ) പറഞ്ഞു: ഇല്ല, എന്റെ ഈ ഗ്രന്ഥത്തിലുള്ളതൊഴികെ. അദ്ദേഹം തന്റെ വാളുറയിൽ നിന്ന് ഒരു ഗ്രന്ഥം പുറത്തെടുത്തു. അതിൽ ഇപ്രകാരം ഉണ്ടായിരുന്നു: "വിശ്വാസികളുടെ രക്തം തുല്യമാണ്. അവരല്ലാത്തവർക്കെതിരെ അവർ ഒറ്റക്കെട്ടായിരിക്കും. അവരിലെ ഏറ്റവും താഴ്ന്നനിലയിലുള്ളവന്നും സംരക്ഷണം നൽകാനാവും. അിറയുക, സത്യനിഷേധിയെ വധിച്ചതിന് വിശ്വാസി വധിക്കപ്പെടുകയില്ല. ഉടമ്പടി നിലനിൽക്കെ, ഉടമ്പടി ചെയ്തവനേയും വധിക്കരുത്. ആരെങ്കിലും പുതുതായി വല്ലതും ഉണ്ടാക്കിയാൽ അവൻ അതിന് ഉത്തരവാദിയായിരിക്കും. പുതുതായി പടച്ചുണ്ടാക്കുന്നവന് ആരെങ്കിലും അഭയം നൽകിയാൽ അവന്റെമേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടേയും മുഴുജനങ്ങളുടേയും ശാപമുണ്ടാവും." (ദ,ന)', 'قَيْسِ بْنِ عُبَادٍ الْقَيْسِيِّ قَالَ', 'ഖൈസുബ്നു ഉബാദുൽ ഖൈസി(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 534, 534, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَدُ الْمُسْلِمِينَ عَلَى مَنْ سِوَاهُمْ، تَتَكَافَأُ دِمَاؤُهُمْ وَأَمْوَالُهُمْ، وَيُجِيرُ عَلَى الْمُسْلِمِينَ أَدْنَاهُمْ، وَيَرُدُّ عَلَى الْمُسْلِمِينَ أَقْصَاهُمْ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിംകൾ മറ്റുള്ളവർക്കെതിരെ ഐക്യത്തിലാണ്. അവരുടെ രക്തവും സമ്പത്തും തുല്ല്യ പരിഗണനയുള്ളതാണ്. അവരിൽ ഏറ്റവും താഴ്ന്നവനും അവരുടെ പേരിൽ സംരക്ഷണം നൽകും, അവരിൽ ഏറ്റവും അകലെയുള്ളവർപോലും അവർക്ക് (യുദ്ധമുതൽ) നൽകും." (തു,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَتَلَ عَبْدَهُ قَتَلْنَاهُ، وَمَنْ جَدَعَ عَبْدَهُ جَدَعْنَاهُ". قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ. (د,ت,ن,جه)', 'സമുറ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ അടിമയെ കൊന്നാൽ നാം അദ്ദേഹത്തെ കൊല്ലുന്നതാണ്. ആരെങ്കിലും അടിമയെ അംഗഛേദനം നടത്തിയാൽ നാമവനെ അംഗഛേദനം നടത്തുന്നതാണ്. (ദ,തു,ന,ജ)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَتَلَ قَتِيلًا مِنْ أَهْلِ الذِّمَّةِ لَمْ يَجِدْ رِيحَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ أَرْبَعِينَ عَامًا". (ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ആരെങ്കിലും കരാറുചെയ്തവനെ (ദിമ്മിയ്യ്) വധിച്ചാൽ സ്വർഗ്ഗത്തിന്റെ പരിമളം അവന് ലഭിക്കുകയില്ല. സ്വർഗ്ഗത്തിന്റെ സുഗന്ധം നാൽപത് വർഷത്തെ വഴിദൂരമകലെ നിന്ന് അനുഭവിക്കാൻ സാധിക്കും." (തു,ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "دِيَةُ الْمُعَاهَدِ نِصْفُ دِيَةِ الْحُرِّ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "കരാർ ചെയ്യപ്പെട്ടവന്റെ നഷ്ടപരിഹാരം സ്വതന്ത്രന്റെ പകുതിയാണ്." (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَتَلَ مُعَاهِدًا فِي غَيْرِ كُنْهِهِ حَرَّمَ اللهُ عَلَيْهِ الْجَنَّةَ". وَفِي رِوَايَةٍ: "مَنْ قَتَلَ نَفْسًا مُعَاهَدَةً بِغَيْرِ حِلِّهَا حَرَّمَ اللهُ عَلَيْهِ الْجَنَّةَ أَنْ يَشُمَّ رِيحَهَا". (ن)', 'അബൂബക്റ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും മുസ്ലിംകളുമായി കരാർചെയ്ത് ജീവിക്കുന്നവനെ അനധികൃതമായി കൊന്നാൽ അവന് അല്ലാഹു സ്വർഗ്ഗം നിഷിദ്ധമാക്കിയിരിക്കുന്നു." മറ്റൊരു നിവേദനത്തിൽ: "ആരെങ്കിലും അനുവദനീയമല്ലാത്ത രീതിയിൽ, കരാർചെയ്ത് ജീവിക്കുന്നവനെ കൊന്നാൽ സ്വർഗവാസന അവന്ന് അല്ലാഹു നിഷിദ്ധമാക്കിയിരിക്കുന്നു." (ന)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 535, 535, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=27), 1, 'وَفِي رِوَايَةٍ: "مَنْ قَتَلَ نَفْسًا مُعَاهَدَةً بِغَيْرِ حِلِّهَا حَرَّمَ اللهُ عَلَيْهِ الْجَنَّةَ أَنْ يَشُمَّ رِيحَهَا". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "ആരെങ്കിലും അനുവദനീയമല്ലാത്ത രീതിയിൽ, കരാർചെയ്ത് ജീവിക്കുന്നവനെ കൊന്നാൽ സ്വർഗവാസന അവന്ന് അല്ലാഹു നിഷിദ്ധമാക്കിയിരിക്കുന്നു." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنِ الْقَاسِمِ بْنِ مُخَيْمِرَةَ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَتَلَ رَجُلًا مِنْ أَهْلِ الذِّمَّةِ لَمْ يَجِدْ رِيحَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ عَامًا". (ن)', 'ഖാസിമുബ്നു മുഖൈമിറ(റ): ഒരു സ്വഹാബിയിൽ നിന്ന് നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും സന്ധിയിലിരിക്കുന്നവനെ കൊന്നാൽ അവന് സ്വർഗ്ഗത്തിന്റെ വാസന എത്തുകയില്ല. എഴുപത് വർഷത്തെ ഒട്ടകദൂരം വരെ സ്വർഗവാസന എത്തും." (ന)', 'الْقَاسِمِ بْنِ مُخَيْمِرَةَ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'ഖാസിമുബ്നു മുഖൈമിറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 535, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا وَقَعَ فِي أَبٍ كَانَ لَهُ فِي الْجَاهِلِيَّةِ، فَلَطَمَهُ الْعَبَّاسُ، فَجَاءَ قَوْمُهُ فَقَالُوا: لَيَلْطِمَنَّهُ كَمَا لَطَمَهُ. فَلَبِسُوا السِّلَاحَ، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَصَعِدَ الْمِنْبَرَ فَقَالَ: "أَيُّهَا النَّاسُ، أَيُّ أَهْلِ الأَرْضِ تَعْلَمُونَ أَكْرَمُ عَلَى اللهِ عَزَّ وَجَلَّ". فَقَالُوا: أَنْتَ. فَقَالَ: "إِنَّ الْعَبَّاسَ مِنِّي وَأَنَا مِنْهُ، لَا تَسُبُّوا مَوْتَانَا فَتُؤْذُوا أَحْيَاءَنَا". فَجَاءَ الْقَوْمُ فَقَالُوا: يَا رَسُولَ اللهِ، نَعُوذُ بِاللهِ مِنْ غَضَبِكَ، اسْتَغْفِرْ لَنَا. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ ജാഹിലിയ്യാ കാലത്തുണ്ടായിരുന്ന തന്റെ പിതാവിനെ ശക്തമായി ആക്ഷേപിച്ചു. അബ്ബാസ്(റ) അദ്ദേഹത്തെ അടിച്ചു. അദ്ദേത്തിന്റെ കുടുംബക്കാർ വന്നുകൊണ്ട് പറഞ്ഞു: അവനെ അടിച്ചതുപോലെ അബ്ബാസിനെയും അടിക്കണം. അവർ ആയുധ ധാരികളായി. ഈ സംഭവം നബി(സ)യുടെ അടുത്തെത്തി. നബി(സ) മിമ്പറിൽ കയറി ഇങ്ങനെ ചോദിച്ചു: "ജനങ്ങളേ, ദുനിയാവിൽ നിങ്ങളറിയുന്ന അല്ലാഹുവിന്റെ അടുക്കൽ ഉന്നതനായ വ്യക്തി ആരാണ്?" അവർ പറഞ്ഞു: അങ്ങു തന്നെ. നബി(സ) പറഞ്ഞു: "അബ്ബാസ് എന്നിൽ നിന്നും ഞാൻ അബ്ബാസിൽ നിന്നുമാണ്. നമ്മിൽനിന്ന് മരിച്ചുപോയവരെ നിങ്ങൾ അധിക്ഷേപിക്കരുത്. അപ്പോൾ നിങ്ങൾ ജീവിക്കുന്നവരെയാണ് ബുദ്ധിമുട്ടാക്കുന്നത്. അപ്പോൾ അവർ നബി(സ)യുടെ അടുത്തു വന്നുകൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയുടെ കോപത്തിൽ നിന്ന് ഞങ്ങൾ അല്ലാഹുവിനോട് കാവൽ ചോദിക്കുന്നു. അങ്ങ് ഞങ്ങൾക്കു വേണ്ടി പൊറുക്കലിനെ തേടിയാലും. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 536, 536, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَقْعُدُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، فَإِذَا قَامَ قُمْنَا، فَقَامَ يَوْمًا وَقُمْنَا مَعَهُ، حَتَّى لَمَّا بَلَغَ وَسَطَ الْمَسْجِدِ أَدْرَكَهُ رَجُلٌ فَجَبَذَ بِرِدَائِهِ مِنْ وَرَائِهِ، وَكَانَ رِدَاؤُهُ خَشِنًا، فَحَمَّرَ رَقَبَتَهُ، فَقَالَ: يَا مُحَمَّدُ، احْمِلْ لِي عَلَى بَعِيرَيَّ هَذَيْنِ، فَإِنَّكَ لَا تَحْمِلُ مِنْ مَالِكَ وَلَا مِنْ مَالِ أَبِيكَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا، وَأَسْتَغْفِرُ اللهَ، لَا أَحْمِلُ لَكَ حَتَّى تُقِيدَنِي مِمَّا جَبَذْتَ بِرَقَبَتِي". فَقَالَ الأَعْرَابِيُّ: لَا وَاللهِ، لَا أُقِيدُكَ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَلِكَ ثَلَاثَ مَرَّاتٍ، كُلُّ ذَلِكَ يَقُولُ: لَا وَاللهِ لَا أُقِيدُكَ. فَلَمَّا سَمِعْنَا قَوْلَ الأَعْرَابِيِّ أَقْبَلْنَا إِلَيْهِ سِرَاعًا، فَالْتَفَتَ إِلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "عَزَمْتُ عَلَى مَنْ سَمِعَ كَلَامِي أَنْ لَا يَبْرَحَ مَقَامَهُ حَتَّى آذَنَ لَهُ". فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِرَجُلٍ مِنَ الْقَوْمِ: "يَا فُلَانُ، احْمِلْ لَهُ عَلَى بَعِيرٍ شَعِيرًا وَعَلَى بَعِيرٍ تَمْرًا". ثُمَّ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "انْصَرِفُوا". (ن)', 'അബൂഹുറൈറ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം പള്ളിയിലിരിക്കുമായിരുന്നു. നബി(സ) എഴുന്നേറ്റാൽ ഉടനെ ഞങ്ങളും എഴുന്നേൽക്കും. ഒരു ദിവസം നബി(സ) എഴുന്നേറ്റു നടന്നു. ഞങ്ങളും കൂടെ പോയി. നബി(സ) പള്ളിയുടെ നടുവിലെത്തിയപ്പോൾ ഒരാൾ വന്നുകൊണ്ട് പിറകിൽ നിന്ന് നബി(സ)യുടെ മേൽവസ്ത്രം വലിച്ചു. റസൂലുല്ലാഹി(സ)യുടെ പുതപ്പ് ഉരമുള്ളതായിരുന്നു. അവിടുത്തെ പിരടി ചുവന്നു. അയാൾ പറഞ്ഞു: മുഹമ്മദേ, എന്റെ ഈ രണ്ട് ഒട്ടകത്തിനും വഹിക്കാനുള്ളത് എനിക്ക് നൽകുക. താങ്കൾ നൽകുന്നത് താങ്കളുടേയോ താങ്കളുടെ പിതാവിന്റെയോ സ്വത്തല്ല. തിരുമേനി(സ) പ്രതിവചിച്ചു: "ഇല്ല, ഞാൻ അല്ലാഹുവിനോട് പൊറുക്കലിനെ ചോദിക്കുന്നു. നീ എന്റെ പിരടിയിൽ പുതപ്പ് വലിച്ചതിന് പ്രതികാരം ചെയ്യുന്നതു വരെ ഞാനവ നിനക്ക് നൽകുകയില്ല." അഅ്റാബി പറഞ്ഞു: ഇല്ല, അല്ലാഹുവാണ് സത്യം, പ്രതിക്രിയ ചെയ്യാൻ ഞാൻ സമ്മതിക്കുകയില്ല. നബി(സ) ഇത് മൂന്നുപ്രാവശ്യം ആവർത്തിച്ചപ്പോഴൊക്കെ അയാൾ പറഞ്ഞത് ഇല്ല, അല്ലാഹുവാണ് സത്യം, പ്രതിക്രിയ ചെയ്യാൻ ഞാൻ സമ്മതിക്കുകയില്ല എന്നായിരുന്നു. അഅ്റാബിയുടെ സംസാരം കേട്ടപ്പോൾ ഞങ്ങൾ അയാളുടെയടുത്തേക്ക് കുതിച്ചു. അപ്പോൾ നബി(സ) ഞങ്ങളിലേക്ക് തിരിഞ്ഞുകൊണ്ട് പറഞ്ഞു: "ഞാനവന് സമ്മതം കൊടുക്കുന്നത് വരെ അവൻ ഇവിടെ നിന്ന് അനങ്ങരുതെന്ന് ഞാൻ അല്ലാഹുവിന്റെ മേൽ ദൃഢപ്രതിജ്ഞയെടുത്തിരിക്കുന്നു." കൂട്ടത്തിലെ ഒരാളോട് നബി(സ) പറഞ്ഞു: "ഏ മനുഷ്യാ, അദ്ദേഹത്തിന്റെ ഒരട്ടൊകപ്പുറത്ത് ബാർലിയും മറ്റേ ഒട്ടകപ്പുറത്ത് കാരക്കയും കയറ്റിക്കൊടുക്കുക." പിന്നെ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പിരിഞ്ഞുപോയ്ക്കൊള്ളുക." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 536, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: اقْتَتَلَتِ امْرَأَتَانِ مِنْ هُذَيْلٍ، فَرَمَتْ إِحْدَاهُمَا الأُخْرَى بِحَجَرٍ، فَقَتَلَتْهَا وَمَا فِي بَطْنِهَا، فَاخْتَصَمُوا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّ دِيَةَ جَنِينِهَا غُرَّةٌ: عَبْدٌ أَوْ وَلِيدَةٌ، وَقَضَى بِدِيَةِ الْمَرْأَةِ عَلَى عَاقِلَتِهَا وَوَرَّثَهَا وَلَدَهَا وَمَنْ مَعَهُمْ، فَقَالَ حَمَلُ بْنُ النَّابِغَةِ الْهُذَلِيُّ: يَا رَسُولَ اللهِ، كَيْفَ أَغْرَمُ مَنْ لَا شَرِبَ وَلَا أَكَلَ، وَلَا نَطَقَ وَلَا اسْتَهَلَّ، فَمِثْلُ ذَلِكَ يُطَلُّ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا هَذَا مِنْ إِخْوَانِ الْكُهَّانِ" مِنْ أَجْلِ سَجْعِهِ الَّذِي سَجَعَ. (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): ഹുദൈൽ ഗോത്രത്തിലെ രണ്ട് സ്ത്രീകൾ തർക്കത്തിലേർപ്പെട്ടു. ഒരു സ്ത്രീ മറ്റവളെ കല്ലെടുത്തെറിഞ്ഞു. സ്ത്രീയെയും ഗർഭസ്ഥ ശിശുവിനെയും അവൾ കൊന്നു. പരാതിയുമായി അവർ തിരു സന്നിധിയിലെത്തി. ഗർഭസ്ഥശിശുവിനെ കൊന്നതിന് നഷ്ടപരിഹാരമായി ഒരു അടിമയേയോ അടിമസ്ത്രീയേയോ നൽകണമെന്ന് റസൂൽ(സ) വിധിച്ചു. സ്ത്രീയുടെ (ഘാതകയുടെ) നഷ്ടപരിഹാരം നൽകേണ്ടത് അവളുടെ പിതാവ് വഴിക്കുള്ള കുടുംബക്കാരാണെന്നും എന്നാൽ, അവളുടെ അനന്തരാവകാശം അവളുടെ മക്കൾക്കും കൂട്ടർക്കുമായിരിക്കുമെന്നും റസൂൽ(സ) വിധിച്ചു. അപ്പോൾ ഹമലുബ്നു നാബിഅതുൽ ഹുദലി(റ) പറഞ്ഞു: ഭക്ഷിക്കുയോ കുടിക്കുകയോ സംസാരിക്കുകയോ കരയുകയോ ചെയ്യാത്തവന് ഞാൻ എങ്ങെനെയാണ് നഷ്ടപരിഹാരം നൽകുക, ഇത്തരം കേസുകളിൽ നഷ്ടപരിഹാരം നൽകേണ്ടതില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, ഇവൻ ജോത്സ്യരുടെ സഹോദരനാണ്." പ്രാസമൊപ്പിച്ചുള്ള അയാളുടെ സംസാരം കാരണമാണ് റസൂൽ(സ) അങ്ങനെ പറഞ്ഞത്. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 537, 537, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَتِ امْرَأَتَانِ جَارَتَانِ، كَانَ بَيْنَهُمَا صَخَبٌ، فَرَمَتْ إِحْدَاهُمَا الأُخْرَى بِحَجَرٍ فَأَسْقَطَتْ غُلَامًا قَدْ نَبَتَ شَعْرُهُ مَيِّتًا، وَمَاتَتِ الْمَرْأَةُ، فَقَضَى عَلَى الْعَاقِلَةِ الدِّيَةَ، فَقَالَ عَمُّهَا: إِنَّهَا قَدْ أَسْقَطَتْ يَا رَسُولَ اللهِ غُلَامًا قَدْ نَبَتَ شَعْرُهُ؟ فَقَالَ أَبُو الْقَاتِلَةِ: إِنَّهُ كَاذِبٌ، إِنَّهُ وَاللهِ مَا اسْتَهَلَّ وَلَا شَرِبَ وَلَا أَكَلَ، فَمِثْلُهُ يُطَلُّ. قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَسَجْعٌ كَسَجْعِ الْجَاهِلِيَّةِ وَكَهَانَتِهَا؟ إِنَّ فِي الصَّبِيِّ غُرَّةً". قَالَ ابْنُ عَبَّاسٍ: كَانَتْ إِحْدَاهُمَا مُلَيْكَةَ وَالأُخْرَى أُمَّ غَطِيفٍ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അയൽവാസികളായ രണ്ട് സ്ത്രീകൾക്കിടയിൽ തർക്കമുണ്ടായി. ഒരു സ്ത്രീ മറ്റേ സ്ത്രീയെ കല്ലെടുത്തെറിഞ്ഞു. വയറ്റിലുള്ള മുടി മുളച്ച കുട്ടി മരിച്ച നിലയിൽ നിലത്ത് വീണു. സ്ത്രീ മരിക്കുകയും ചെയ്തു. കുടുംബക്കാരുടെ മേൽ നഷ്ടപരിഹാരം വിധിക്കപ്പെട്ടു. സ്ത്രീയുടെ എളാപ്പ പറഞ്ഞു: മുടി മുളച്ച കുട്ടിയെ അവൾ എറിഞ്ഞു വീഴ്ത്തിയിരിക്കുന്നു, റസൂലേ. ഘാതകയുടെ ഉപ്പ പറഞ്ഞു: അവൻ കളവ് പറയുകയാണ്. അല്ലാഹുവാണ് സത്യം. കുട്ടി കരയുകയോ തിന്നുകയോ കുടിക്കുകയോ ചെയ്തിട്ടില്ല. അതുപോലോത്തത് വെറുതെയാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ജാഹിലിയ്യത്തിലെ ജ്യോതിഷവും സജ്ളം (വാക്കുകളടെ അന്ത്യം കോർവ്വയിലാക്കിപ്പറയൽ) പോലെ സജ്അ് പറയുകയാണോ? കുട്ടിയുടെ നഷ്ടപരിഹാരം അടിമയുടേതു പോലെയാണ്." ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അവരിൽ ഒരാൾ മുലൈകയും മറ്റവൾ ഉമ്മുഗഥീഫുമായിരുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 537, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللهُ عَنْهُمَا قَالَ: اسْتَشَارَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ النَّاسَ فِي إِمْلَاصِ الْمَرْأَةِ، يَعْنِي سِقْطَهَا. فَقَالَ الْمُغِيرَةُ بْنُ شُعْبَةَ: شَهِدْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى فِيهِ بِغُرَّةٍ: عَبْدٍ أَوْ أَمَةٍ. فَقَالَ عُمَرُ رَضِيَ اللهُ عَنْهُ: ائْتِنِي بِمَنْ يَشْهَدُ مَعَكَ. فَشَهِدَ مَعَهُ مُحَمَّدُ بْنُ مَسْلَمَةَ. (م,د,ن,جه)', 'മിസ്വറുബ്നു മഖ്റമ(റ): സ്ത്രീയെ മർദ്ദിച്ച് ഗർഭസ്ഥ ശിശുവിനെ വധിച്ചാലുള്ള വിധിയെക്കുറിച്ച് ഉമർ(റ) ജനങ്ങളുമായി ചർച്ചചെയ്തു. അപ്പോൾ മുഗീറതുബ്നു ശുഅ്ബ(റ) പറഞ്ഞു: ആണോ പെണ്ണോ ആയ ഒരടിമയെ നഷ്ടപരിഹാരമായി നൽകണമെന്ന് നബി(സ) വിധിക്കുന്നതിന് ഞാൻ സാക്ഷിയായിട്ടുണ്ട്. ഉമർ(റ) മുഗീറയോട് അതിന് സാക്ഷിയെ കൊണ്ടുവരാൻ ആവശ്യപ്പെട്ടു. അപ്പോൾ മുഹമ്മദുബ്നു മസ്ലമ മുഗീറക്കൊപ്പം സാക്ഷിയായി നിന്നു. (മു,ദ,ന,ജ)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മിസ്വറുബ്നു മഖ്റമ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً خَذَفَتِ امْرَأَةً فَأَسْقَطَتْ، فَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي وَلَدِهَا خَمْسِينَ شَاةً، وَفِي رِوَايَةٍ: فَرُفِعَ ذَلِكَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَ عَقْلَ وَلَدِهَا خَمْسَمِائَةٍ مِنَ الْغُرِّ، وَنَهَى يَوْمَئِذٍ عَنِ الْخَذْفِ. (ن)', 'ബുറൈദ(റ): ഒരു സ്ത്രീ മറ്റൊരു സ്ത്രീയെ എറിയുകയും ചാപ്പിള്ളയെ പുറത്തുചാടിക്കുകയും ചെയ്തു. ആ സ്ത്രീയുടെ കുട്ടിക്ക് പകരം അമ്പത് ആടുകളെ നൽകാൻ റസൂൽ(സ) വിധിച്ചു. മറ്റൊരു നിവേദനത്തിൽ: ആ പ്രശ്നം നബി(സ)യുടെ അടുത്ത് ഉന്നയിക്കപ്പെട്ടു. അവളുടെ കുട്ടിയുടെ നഷ്ടപരിഹാരം അഞ്ഞൂറ് വെള്ളിനാണയമാണെന്ന് നബി(സ) വിധിക്കുകയും അന്നുതന്നെ എറിയുന്നത് നിരോധിക്കുകയും ചെയ്തു. (ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=34), 1, 'وَفِي رِوَايَةٍ: فَرُفِعَ ذَلِكَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَ عَقْلَ وَلَدِهَا خَمْسَمِائَةٍ مِنَ الْغُرِّ، وَنَهَى يَوْمَئِذٍ عَنِ الْخَذْفِ. (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: ആ പ്രശ്നം നബി(സ)യുടെ അടുത്ത് ഉന്നയിക്കപ്പെട്ടു. അവളുടെ കുട്ടിയുടെ നഷ്ടപരിഹാരം അഞ്ഞൂറ് വെള്ളിനാണയമാണെന്ന് നബി(സ) വിധിക്കുകയും അന്നുതന്നെ എറിയുന്നത് നിരോധിക്കുകയും ചെയ്തു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "الْبِئْرُ جَرْحُهَا جُبَارٌ، وَالْمَعْدِنُ جَرْحُهُ جُبَارٌ، وَالْعَجْمَاءُ جَرْحُهَا جُبَارٌ، وَفِي الرِّكَازِ الْخُمْسُ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "കിണറ്റിൽ വീണുണ്ടായ മുറിവിന് പ്രതിക്രിയയോ നഷ്ടപരിഹാരമോ ഉണ്ടാവുകയില്ല. ഖനിയിൽ വീണുണ്ടായ മുറിവിനും പ്രതിക്രിയയോ നഷ്ടപരിഹാരമോ ഉണ്ടാവുകയില്ല. മൃഗമേൽപിച്ച മുറിവിനും പ്രതിക്രിയയോ നഷ്ടപരിഹാരമോ ഉണ്ടാവുകയില്ല. നിധിയുടെ അഞ്ചിലൊന്ന് സകാത്ത് കൊടുക്കണം." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 538, 538, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنِ ابْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قُتِلَ خَطَأً فَدِيَتُهُ مِائَةٌ مِنَ الْإِبِلِ: ثَلَاثُونَ بِنْتَ مَخَاضٍ، وَثَلَاثُونَ بِنْتَ لَبُونٍ، وَثَلَاثُونَ حِقَّةً، وَعَشَرَةُ بَنِي لَبُونٍ ذُكُورٍ". قَالَ: وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَوِّمُهَا عَلَى أَهْلِ الْقُرَى أَرْبَعَ مِائَةِ دِينَارٍ أَوْ عِدْلَهَا مِنَ الْوَرِقِ، وَيُقَوِّمُهَا عَلَى أَهْلِ الْإِبِلِ: إِذَا غَلَتْ رُفِعَ فِي قِيمَتِهَا، وَإِذَا هَانَتْ نَقَصَ مِنْ قِيمَتِهَا عَلَى نَحْوِ الزَّمَانِ مَا كَانَ، فَبَلَغَ قِيمَتُهَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا بَيْنَ الْأَرْبَعِ مِائَةِ دِينَارٍ إِلَى ثَمَانِ مِائَةِ دِينَارٍ أَوْ عِدْلِهَا مِنَ الْوَرِقِ. قَالَ: وَقَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ مَنْ كَانَ عَقْلُهُ فِي الْبَقَرِ عَلَى أَهْلِ الْبَقَرِ مِائَتَيْ بَقَرَةٍ، وَمَنْ كَانَ عَقْلُهُ فِي الشَّاةِ أَلْفَيْ شَاةٍ. وَقَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ الْعَقْلَ مِيرَاثٌ بَيْنَ وَرَثَةِ الْقَتِيلِ عَلَى فَرَائِضِهِمْ، فَمَا فَضَلَ فَلِلْعَصَبَةِ. وَقَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَعْقِلَ عَلَى الْمَرْأَةِ عَصَبَتُهَا مَنْ كَانُوا، وَلَا يَرِثُونَ مِنْهُ شَيْئًا إِلَّا مَا فَضَلَ عَنْ وَرَثَتِهَا، وَإِنْ قُتِلَتْ فَعَقْلُهَا بَيْنَ وَرَثَتِهَا وَهُمْ يَقْتُلُونَ قَاتِلَهَا. (ت,ن,جه)', 'ഇബ്നുഅംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അബദ്ധത്തിൽ വധിക്കപ്പെട്ടാൽ അവന്റെ നഷ്ടപരിഹാരം നൂറ് ഒട്ടകമാണ്. ഒരു വയസ്സുള്ള മുപ്പത് പെൺഒട്ടകം, രണ്ടു വയസ്സുള്ള മുപ്പത് പെൺഒട്ടകം, മൂന്ന് വയസ്സുള്ള മുപ്പത് പെൺഒട്ടകം, രണ്ടു വയസ്സുള്ള പത്ത് ആൺഒട്ടകം." ഗ്രാമീണരിൽ അതിന് നാനൂറ് ദീനാറായിരുന്നു നബി(സ) കണക്കാക്കിയിരുന്നത്, അതല്ലെങ്കിൽ അതിന് തുല്യമായ വെള്ളി. ഒട്ടക സീസൺ അനുസരിച്ചായിരുന്നു അത് കണക്കാക്കിയിരുന്നത്. ഒട്ടകത്തിന് വില ഉയരുമ്പോൾ നഷ്ടപരിഹാര തുക ഉയർത്തും. കുറയുമ്പോൾ തുക കുറയുകയും ചെയ്യും. റസൂൽ(സ)യുടെ കാലത്ത് നാനൂറ് മുതൽ എണ്ണൂറ് ദീനാർ വരെയായിരുന്നു, അല്ലെങ്കിൽ തത്തുല്യമായ വെള്ളിയായിരുന്നു ഒട്ടകത്തിന്റെ വില. നിവേദകൻ: പശുവാണ് നഷ്ടപരിഹാരായി നൽകുന്നതെങ്കിൽ പശു ഉടമകൾ ഇരുന്നൂറ് പശുക്കളെ നൽകണമെന്നും ആടാണ് നൽകുന്നതെങ്കിൽ രണ്ടായിരം ആടുകളെ നൽകണമെന്നും റസൂൽ(സ) വിധിച്ചു. നഷ്ടപരിഹാരം കൊല്ലപ്പെട്ടവന്റെ അനന്തരാവകാശികൾക്കിടയിൽ വീതിക്കപ്പെടുകയും, മിച്ചമായത് വിഹിതം നിശ്ചയിക്കപ്പെട്ടിട്ടില്ലാത്ത അവകാശികൾക്കുള്ളതാണെന്നും റസൂൽ(സ) വിധിച്ചിരിക്കുന്നു. സ്ത്രീയുടെ നഷ്ടപരിഹാരം നൽകേണ്ട ബാധ്യത അവളുടെ പിതാവ് വഴിക്കുള്ള കുടുംബത്തിലെ പുരുഷന്മാർക്കാണെന്നും, എന്നാൽ അവളുടെ അനന്തരാവകാശികൾ വിഹിതം വെച്ചതിൽ മിച്ചം വന്നതല്ലാതെ ഒന്നും അവളുടെ സ്വത്തിൽ നിന്ന് അവർക്ക് അനന്തരമായി ലഭിക്കുകയില്ല എന്നും അവിടുന്ന് വിധിച്ചിരിക്കുന്നു. സ്ത്രീ വധിക്കപ്പെട്ടാൽ അവൾക്ക് ലഭിക്കേണ്ട നഷ്ടപരിഹാരം അവളുടെ അനന്തരാവകാശികൾക്കിടയിൽ വീതിക്കണം. അവരാണ് അവളുടെ ഘാതകനെ വധിക്കേണ്ടത്. (തു,ന,ജ)', 'ابْنِ عَمْرٍو', 'ഇബ്നുഅംറ്(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 539, 539, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ أَبَا جَهْمِ بْنِ حُذَيْفَةَ مُصَدِّقًا، فَلَاحَهُ رَجُلٌ فِي صَدَقَتِهِ، فَضَرَبَهُ أَبُو جَهْمٍ، فَأَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: الْقَوَدَ يَا رَسُولَ اللَّهِ، فَقَالَ: "لَكُمْ كَذَا وَكَذَا". فَلَمْ يَرْضَوْا بِهِ، فَقَالَ: "لَكُمْ كَذَا وَكَذَا". فَرَضُوا بِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "إِنِّي خَاطِبٌ عَلَى النَّاسِ وَمُخْبِرُهُمْ بِرِضَاكُمْ". قَالُوا: نَعَمْ. فَخَطَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّ هَؤُلَاءِ أَتَوْنِي يُرِيدُونَ الْقَوَدَ، فَعَرَضْتُ عَلَيْهِمْ كَذَا وَكَذَا فَرَضُوا". قَالُوا: لَا. فَهَمَّ الْمُهَاجِرُونَ بِهِمْ، فَأَمَرَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكُفُّوا فَكَفُّوا، ثُمَّ دَعَاهُمْ، قَالَ: "أَرَضِيتُمْ". قَالُوا: نَعَمْ. قَالَ: "فَإِنِّي خَاطِبٌ عَلَى النَّاسِ وَمُخْبِرُهُمْ بِرِضَاكُمْ". قَالُوا: نَعَمْ. فَخَطَبَ النَّاسَ ثُمَّ قَالَ: "أَرَضِيتُمْ" قَالُوا نَعَمْ. (د,ن,جه)', 'ആഇശ(റ): അബൂജഹ്മ്(റ)വിനെ സകാത്ത് പിരിക്കാനായി നബി(സ) പറഞ്ഞയച്ചു. സകാത്തിന്റെ വിഷയത്തിൽ ഒരാൾ അദ്ദേഹത്തോട് തർക്കിച്ചു. അപ്പോൾ അബൂഹജഹ്മ്(റ) അയാളെ അടിച്ചു. അവർ നബി(സ)യെ സമീപിച്ച് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങൾക്ക് പ്രതികാരം ചെയ്യണം. നബി(സ) പറഞ്ഞു: "ഇന്നതൊക്കെ നിങ്ങൾക്ക് നഷ്ടപരിഹാമായി തരാം." പക്ഷേ, അവരതുകൊണ്ട് തൃപ്തിപ്പെട്ടില്ല. നബി(സ) വീണ്ടും പറഞ്ഞു: "നിങ്ങൾക്ക് ഇന്നാലിന്നതൊക്കെ തരാം." അപ്പോൾ അവർ അതുകൊണ്ട് തൃപ്തിപ്പെട്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഞാൻ ജനങ്ങളെ അഭിസംബോധന ചെയ്ത് നിങ്ങളുടെ തൃപ്തി അവരെ അറിയിക്കും." അവർ പറഞ്ഞു: അതെ. അങ്ങനെ ജനങ്ങളെ അഭിസംബോധന ചെയ്തു കൊണ്ട് നബി(സ) പറഞ്ഞു: "ഇവർ പ്രതികാരം ചെയ്യണമെന്നാഗ്രഹിച്ചു കൊണ്ട് എന്റെ അടുത്തുവന്നു. ഞാൻ ഇന്നതൊക്കെ മുന്നോട്ടു വെച്ചു. അവർ അതുകൊണ്ട് തൃപ്തിപ്പെട്ടിരിക്കുന്നു." അപ്പോൾ അവർ പറഞ്ഞു: ഇല്ല. ഉടനെ മുഹാജിറുകൾ അവരെ കൈകാര്യം ചെയ്യാൻ തുനിഞ്ഞു. റസൂൽ(സ) അവരോട് അടങ്ങിനിൽക്കാൻ ആവശ്യപ്പെട്ടു. അവർ അടങ്ങിയിരിക്കുകയും ചെയ്തു. ശേഷം നബി(സ) പ്രതികാരം ചോദിച്ചുകൊണ്ട് വന്നവരെ വിളിച്ചു. അവിടുന്ന് ചോദിച്ചു: "നിങ്ങൾക്ക് തൃപ്തിയായോ?" അവർ പറഞ്ഞു: "ജനങ്ങളെ അഭിസംബോധന ചെയ്ത് നിങ്ങളുടെ തൃപ്തി ഞാനവരെ അറിയിക്കും." അവർ പറഞ്ഞു: അതെ. നബി(സ) ജനങ്ങളോട് പ്രസംഗിച്ചു. എന്നിട്ട് ചോദിച്ചു: "നിങ്ങൾക്ക് തൃപ്തിയായോ?" അവർ പറഞ്ഞു: അതെ. (ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 539, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أُخْتَ الرُّبَيِّعِ أُمَّ حَارِثَةَ جَرَحَتْ إِنْسَانًا، فَاخْتَصَمُوا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْقِصَاصَ الْقِصَاصَ". فَقَالَتْ أُمُّ الرَّبِيعِ: يَا رَسُولَ اللَّهِ، أَيُقْتَصُّ مِنْ فُلَانَةَ؟ وَاللَّهِ لَا يُقْتَصُّ مِنْهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سُبْحَانَ اللَّهِ! يَا أُمَّ الرَّبِيعِ، الْقِصَاصُ كِتَابُ اللَّهِ". قَالَتْ: لَا وَاللَّهِ لَا يُقْتَصُّ مِنْهَا أَبَدًا. قَالَ: فَمَا زَالَتْ حَتَّى قَبِلُوا الدِّيَةَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ عِبَادِ اللَّهِ مَنْ لَوْ أَقْسَمَ عَلَى اللَّهِ لَأَبَرَّهُ". (م,د,ن,جه)', 'അനസ്(റ): റുബയ്യിഇന്റെ സഹോദരി ഉമ്മുഹാരിസ ഒരാളെ മുറിവേൽപ്പിച്ചു. അവർ തർക്കം നബി(സ)യിലെത്തിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "പ്രതികാരം ചെയ്യണം." ഉമ്മുറബീഅ്(റ) പറഞ്ഞു: റസൂലേ, ഇന്നവളോട് പ്രതികാരം ചെയ്യുമോ? അല്ലാഹു തന്നെ സത്യം, അവളോട് പ്രതികാരം ചെയ്യാൻ പാടില്ല. റസൂൽ(സ) പറഞ്ഞു: "സുബ്ഹാനല്ലാ, ഉമ്മുറബീഅ്, നീയെന്താണ് പറയുന്നത്. ഖിസാസ് അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ പറഞ്ഞ വിധിയാണ്." ഉമ്മുറബീഅ് പറഞ്ഞു: ഇല്ല, അല്ലാഹുവാണ് സത്യം, അവളോട് ഒരിക്കലും പ്രതികാരം ചെയ്യരുത്. അവർ നഷ്ടപരിഹാരം സ്വീകരിക്കുന്നതു വരെ ഉമ്മുറബീഅ്(റ) ഇപ്രകാരം തുടർന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് ചില അടിമകളുണ്ട്. അവർ വല്ല കാര്യവും സത്യംചെയ്ത് പറഞ്ഞാൽ അത് അല്ലാഹു സത്യമാക്കും." (മു,ദ,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 540, 540, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَلْقَمَةَ بْنِ وَائِلٍ: أَنَّ أَبَاهُ رَضِيَ اللَّهُ عَنْهُ حَدَّثَهُ قَالَ: إِنِّي لَقَاعِدٌ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَ رَجُلٌ يَقُودُ آخَرَ بِنِسْعَةٍ، فَقَالَ: يَا رَسُولَ اللَّهِ، هَذَا قَتَلَ أَخِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَقَتَلْتَهُ". فَقَالَ: إِنَّهُ لَوْ لَمْ يَعْتَرِفْ أَقَمْتُ عَلَيْهِ الْبَيِّنَةَ. قَالَ: نَعَمْ، قَتَلْتُهُ. قَالَ: "كَيْفَ قَتَلْتَهُ". قَالَ: كُنْتُ أَنَا وَهُوَ نَخْتَبِطُ مِنْ شَجَرَةٍ، فَسَبَّنِي فَأَغْضَبَنِي، فَضَرَبْتُهُ بِالْفَأْسِ عَلَى قَرْنِهِ فَقَتَلْتُهُ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ لَكَ مِنْ شَيْءٍ تُؤَدِّيهِ عَنْ نَفْسِكَ". قَالَ: مَا لِي مَالٌ إِلَّا كِسَائِي وَفَأْسِي، قَالَ: "فَتَرَى قَوْمَكَ يَشْتَرُونَكَ". قَالَ: أَنَا أَهْوَنُ عَلَى قَوْمِي مِنْ ذَاكَ. فَرَمَى إِلَيْهِ بِنِسْعَتِهِ وَقَالَ: "دُونَكَ صَاحِبَكَ". فَانْطَلَقَ بِهِ الرَّجُلُ، فَلَمَّا وَلَّى قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنْ قَتَلَهُ فَهُوَ مِثْلُهُ". فَرَجَعَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّهُ بَلَغَنِي أَنَّكَ قُلْتَ: "إِنْ قَتَلَهُ فَهُوَ مِثْلُهُ". وَأَخَذْتُهُ بِأَمْرِكَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَا تُرِيدُ أَنْ يَبُوءَ بِإِثْمِكَ وَإِثْمِ صَاحِبِكَ". قَالَ: يَا نَبِيَّ اللَّهِ - لَعَلَّهُ قَالَ - بَلَى. قَالَ: "فَإِنَّ ذَاكَ كَذَاكَ". قَالَ: فَرَمَى بِنِسْعَتِهِ وَخَلَّى سَبِيلَهُ. (م,ن)', 'അൽഖമബ്നു വാഇൽ(റ): അദ്ദേഹത്തിന്റെ പിതാവ് അദ്ദേഹത്തിന് പറഞ്ഞുകൊടുത്തു. ഞാൻ റസൂൽ(സ)യോടൊത്ത് ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ മറ്റൊരാളെ കയറിൽ ബന്ധിച്ച് കൊണ്ടുവന്നു. അയാൾ പറഞ്ഞു: റസൂലേ, ഇയാൾ എന്റെ സഹോദരനെ കൊന്നു. റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങളയാളെ വധിച്ചോ?" ഘാതകനെ കൊണ്ടുവന്നയാൾ പറഞ്ഞു: അദ്ദേഹം സമ്മതിച്ചില്ലെങ്കിൽ ഞാൻ തെളിവ് കൊണ്ടുവരും. ഘാതകൻ പറഞ്ഞു: അതെ, ഞാനദ്ദേഹത്തെ കൊന്നിട്ടുണ്ട്. നബി(സ) ചോദിച്ചു: "നിങ്ങളെങ്ങനെയാണ് അദ്ദേഹത്തെ കൊന്നത്?" അദ്ദേഹം പറഞ്ഞു: ഞാനും അയാളും ഒരു മരത്തിൽ നിന്ന് ഇല കൊഴിക്കുകയായിരുന്നു. അപ്പോൾ അയാൾ എന്നെ ചീത്തവിളിച്ചു. അതെന്നെ ചൊടിപ്പിച്ചു. ഞാൻ മഴു കൊണ്ട് അവന്റെ തലക്കടിച്ചു. അങ്ങനെ ഞാനയാളെ കൊന്നു. നബി(സ) അവനോട് പറഞ്ഞു: "നിന്റെ കയ്യിൽ നഷ്ടപരിഹാരമായി കൊടുക്കാൻ എന്തെങ്കിലുമുണ്ടോ?" അയാൾ പറഞ്ഞു: എന്റെയടുത്ത് എന്റെ മഴുവും വസ്ത്രവുമല്ലാതെ ഒരു സ്വത്തുമില്ല. നബി(സ) ചോദിച്ചു: "നിന്റെ സമൂഹം നഷ്ടപരിഹാരം നൽകുമെന്ന് നീ വിചാരിക്കുന്നുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ എന്റെ സമൂഹത്തിൽ വളരെ വില കുറഞ്ഞവനാണ്. നബി(സ) കയർ അദ്ദേഹത്തിലേക്കെറിഞ്ഞുകൊണ്ട് പറഞ്ഞു: "നിന്റെ കൂട്ടാളിയെ പിടിച്ചോ." അയാളെയും കൂട്ടി ആഗതൻ നീങ്ങി. അയാൾ തിരിഞ്ഞുപോയപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇവൻ അയാളെ വധിക്കുകയാണെങ്കിൽ ഇവനും അയാളെപ്പോലെയാകും." അയാൾ തിരിച്ചുവന്നുകൊണ്ട് നബി(സ)യോട് പറഞ്ഞു: റസൂലേ, "ഇവൻ അയാളെ വധിക്കുകയാണെങ്കിൽ ഇവനും അയാളെപ്പോലെയാകും" എന്ന് അങ്ങ് പറഞ്ഞത് ഞാനറിഞ്ഞു. അങ്ങ് പറഞ്ഞിട്ടല്ലെയോ ഞാനവനെ കൊണ്ടുപോയത്? അപ്പോൾ നബി(സ) ചോദിച്ചു: "നിന്റെയും നിന്റെ സഹോദരന്റെയും പാപം അവൻ ചുമക്കുന്നത് നീ ഇഷ്ടപ്പെടുന്നില്ലേ?" അദ്ദേഹം പറഞ്ഞു: അതെ, അല്ലാഹുവിന്റെ റസൂലേ. നബി(സ) പറഞ്ഞു: "അതങ്ങനെത്തന്നെയാണ്." നിവേദകൻ പറയുന്നു: അപ്പോൾ അദ്ദേഹം കയർ വലിച്ചെറിഞ്ഞ് അയാളെ വെറുതെവിട്ടു. (മു,ന)', 'عَلْقَمَةَ بْنِ وَائِلٍ', 'അൽഖമബ്നു വാഇൽ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 541, 541, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْتَقَى هُوَ وَالْمُشْرِكُونَ فَاقْتَتَلُوا، فَلَمَّا مَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عَسْكَرِهِ، وَمَالَ الْآخَرُونَ إِلَى عَسْكَرِهِمْ، وَفِي أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ لَا يَدَعُ لَهُمْ شَاذَّةً إِلَّا اتَّبَعَهَا يَضْرِبُهَا بِسَيْفِهِ، فَقَالُوا: مَا أَجْزَأَ مِنَّا الْيَوْمَ أَحَدٌ كَمَا أَجْزَأَ فُلَانٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَا إِنَّهُ مِنْ أَهْلِ النَّارِ". فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: أَنَا صَاحِبُهُ [أَبَدًا]. قَالَ: فَخَرَجَ مَعَهُ، كُلَّمَا وَقَفَ وَقَفَ مَعَهُ، وَإِذَا أَسْرَعَ أَسْرَعَ مَعَهُ، قَالَ: فَجُرِحَ الرَّجُلُ جُرْحًا شَدِيدًا، فَاسْتَعْجَلَ الْمَوْتَ، فَوَضَعَ نَصْلَ سَيْفِهِ بِالْأَرْضِ وَذُبَابَهُ بَيْنَ ثَدْيَيْهِ، ثُمَّ تَحَامَلَ عَلَى سَيْفِهِ فَقَتَلَ نَفْسَهُ، قَالَ: فَخَرَجَ الرَّجُلُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ، فَقَالَ: "وَمَا ذَاكَ". قَالَ: الرَّجُلُ الَّذِي ذَكَرْتَ آنِفًا أَنَّهُ مِنْ أَهْلِ النَّارِ فَأَعْظَمَ النَّاسُ ذَلِكَ، فَقُلْتُ: أَنَا لَكُمْ بِهِ، فَخَرَجْتُ فِي طَلَبِهِ حَتَّى جُرِحَ جُرْحًا شَدِيدًا، فَاسْتَعْجَلَ الْمَوْتَ، فَوَضَعَ نَصْلَ سَيْفِهِ بِالْأَرْضِ وَذُبَابَهُ بَيْنَ ثَدْيَيْهِ، ثُمَّ تَحَامَلَ عَلَيْهِ فَقَتَلَ نَفْسَهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ: "إِنَّ الرَّجُلَ لَيَعْمَلُ عَمَلَ أَهْلِ الْجَنَّةِ، فِيمَا يَبْدُو لِلنَّاسِ، وَهُوَ مِنْ أَهْلِ النَّارِ، وَإِنَّ الرَّجُلَ لَيَعْمَلُ عَمَلَ أَهْلِ النَّارِ، فِيمَا يَبْدُو لِلنَّاسِ، وَهُوَ مِنْ أَهْلِ الْجَنَّةِ". (ق)', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ): റസൂൽ(സ)യും മുശ്രിക്കുകളും ഏറ്റുമുട്ടി. നബി(സ) തന്റെ സൈനിക ക്യാമ്പിലേക്കും മറ്റുള്ളവർ അവരുടെ ക്യാമ്പിലേക്കും പോയി. നബി(സ)യുടെ അനുചരരിൽപ്പെട്ട ഒരാൾ ഒരു ശത്രുവിനെയും ഒഴിവാക്കാതെ അവരെ പിന്തുടർന്ന് വാളിനിരയാക്കിയിരുന്നു. സ്വഹാബികൾ പറഞ്ഞു: ഇന്നാലിന്നയാൾ ഇന്ന് പൊരുതിയതു പോലെ ആരും പൊരുതിയിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എന്നാലയാൾ നരകാവകാശിയാണ്." കൂട്ടത്തിൽപ്പെട്ട ഒരാൾ പറഞ്ഞു: ഞാനദ്ദേഹത്തെ അനുഗമിക്കുകയാണ്. നിവേദകൻ പറയുന്നു: അങ്ങനെ അദ്ദേഹം അയാളെ അനുഗമിച്ചു. എവിടെ നിൽക്കുന്നുവോ അവിടെ നിൽക്കുകയും എങ്ങോട്ട് പോകുന്നുവോ അങ്ങോട്ട് പോകുകയും ചെയ്യും. അങ്ങനെ അയാൾക്ക് ശക്തമായ മുറിവേറ്റു. അയാൾക്ക് പെട്ടെന്ന് മരിച്ചാൽ മതിയെന്ന് തോന്നി. തന്റെ വാളിന്റെ പിടി ഭൂമിയിൽ വെച്ചു. വാളിന്റെ മൂർച്ചയുള്ള തല തന്റെ മാറിലും വെച്ച് അതിന്മേൽ അമർന്നു. അങ്ങനെ അയാൾ ആത്മഹത്യ ചെയ്തു. അപ്പോൾ പിന്തുടർന്ന വ്യക്തി നബി(സ)യുടെ അടുത്തേക്ക് തിരിച്ചു. എന്നിട്ടദ്ദേഹം പറഞ്ഞു: താങ്കൾ അല്ലാഹുവിന്റെ റസൂലാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. റസൂൽ(സ) ചോദിച്ചു: "എന്താണ് വിഷയം?" അയാൾ പറഞ്ഞു: അങ്ങ് ഇപ്പോൾ ഒരു വ്യക്തിയെക്കുറിച്ച് നരകാവകാശിയാണെന്ന് പറയുകയും ജനങ്ങൾക്കത് വല്ലാത്തൊരു വിഷയമായി തോന്നുകയും ചെയ്തില്ലേ? അപ്പോൾ ഞാൻ പറഞ്ഞു: നിങ്ങൾക്കായി ഞാനിതിന്റെ സത്യാവസ്ഥ കണ്ടുപിടിക്കാം. അങ്ങനെ ഞാനദ്ദേഹത്തെ പിന്തുടർന്നു. അയാൾക്കു ശക്തമായ മുറിവേറ്റു. അയാൾക്ക് പെട്ടെന്ന് മരിച്ചാൽ മതിയെന്നായി. അയാൾ വാളിന്റെ പിടി നിലത്തുവെച്ചു. മൂർച്ചയുള്ള ഭാഗം തന്റെ മാറിടത്തിലും വെച്ചു. ശേഷം അതിന്മേൽ അമർന്നു. അങ്ങനെ അയാൾ ആത്മഹത്യ ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ ജനങ്ങളുടെ ദൃഷ്ടിയിൽ സ്വർഗ്ഗാവകാശിയുടെ കർമ്മങ്ങൾ ചെയ്യും. എന്നാലവൻ നരകാവകാശിയായിരിക്കും. ജനങ്ങളുടെ ദൃഷ്ടിയിൽ ഒരാൾ നരകാവകാശികളുടെ കർമ്മം ചെയ്യും, അവൻ സ്വർഗാവകാശിയുമായിരിക്കും." (ബു,മു)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ലുബ്നു സഅ്ദിസ്സാഇദീ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], 'أَبَدًا', null, 541, 542, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحَبَشِيٍّ، فَقَالَ: إِنَّ هَذَا قَتَلَ ابْنَ أَخِي، قَالَ: "كَيْفَ قَتَلْتَهُ". قَالَ: ضَرَبْتُ رَأْسَهُ بِالْفَأْسِ وَلَمْ أُرِدْ قَتْلَهُ، قَالَ: "هَلْ لَكَ مَالٌ تُؤَدِّي دِيَتَهُ". قَالَ: لَا، قَالَ: "أَفَرَأَيْتَ إِنْ أَرْسَلْتُكَ تَسْأَلُ النَّاسَ تَجْمَعُ دِيَتَهُ". قَالَ: لَا، قَالَ: "فَمَوَالِيكَ يُعْطُونَكَ دِيَتَهُ". قَالَ: لَا، قَالَ لِلرَّجُلِ: "خُذْهُ". فَخَرَجَ بِهِ لِيَقْتُلَهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَا إِنَّهُ إِنْ قَتَلَهُ كَانَ مِثْلَهُ". فَبَلَغَ بِهِ الرَّجُلُ حَيْثُ يَسْمَعُ قَوْلَهُ، فَقَالَ: هُوَ ذَا، فَمُرْ فِيهِ مَا شِئْتَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَرْسِلْهُ - وَقَالَ مَرَّةً: دَعْهُ - يَبُوءُ بِإِثْمِ صَاحِبِهِ وَإِثْمِهِ، فَيَكُونَ مِنْ أَصْحَابِ النَّارِ". قَالَ: فَأَرْسَلَهُ. (م,د,ن)', 'വാഇലുബ്നു ഹജർ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്തേക്ക് ഒരു നീഗ്രോയുമായി വന്നു. അയാൾ പറഞ്ഞു: ഇയാൾ എന്റെ സഹോദരപുത്രനെ വധിച്ചു. നബി(സ) ചോദിച്ചു: "നിങ്ങളെങ്ങനെയാണ് അയാളെ കൊന്നത്?" അയാൾ പറഞ്ഞു: ഞാനയാളുടെ തലയിൽ മഴു കൊണ്ട് വെട്ടി. ഞാനയാളെ കൊല്ലാനുദ്ദേശിച്ചിരുന്നില്ല. നബി(സ) ചോദിച്ചു: "അദ്ദേഹത്തിന് നഷ്ടപരിഹാരം നൽകാൻ നിന്റെ പക്കൽ സമ്പത്തുണ്ടോ?" അയാൾ പറഞ്ഞു: ഇല്ല. നബി(സ) ചോദിച്ചു: "ഞാൻ നിന്നെ അയച്ചാൽ നീ ജനങ്ങളോട് ചോദിച്ച് നഷ്ടപരിഹാരം സ്വരൂപിക്കുമോ?" അയാൾ പറഞ്ഞു: ഇല്ല. നബി(സ) ചോദിച്ചു: "നിന്റെ ഉടമസ്ഥർ ആവശ്യമായി നഷ്ടപരിഹാരം നിന്റെ പക്കൽ നൽകുമോ?" അയാൾ പറഞ്ഞു: ഇല്ല. നബി(സ) ആഗതനോട് പറഞ്ഞു: "അയാളെ പിടിച്ചുകൊള്ളുക." അയാൾ അവനെ കൊല്ലാൻ കൊണ്ടുപോയി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അയാളവനെ കൊല്ലുകയാണെങ്കിൽ ഘാതകനും കൊല്ലപ്പെട്ടവനെപ്പോലെയാണ്." അയാൾ തിരുമേനി(സ)യുടെ സംസാരം കേൾക്കുന്നിടത്തായിരുന്നതിനാൽ അവിടന്ന് പറഞ്ഞത് അയാളറിഞ്ഞു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവനിതാ റസൂലേ, അങ്ങുദ്ദേശിക്കുന്നത് അവന്റെ കാര്യത്തിൽ കൽപിച്ചാലും. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നീ അവനെ വെറുതെ വിടുക. അവന്റെയും കൂട്ടാളിയുടെയും (കൊല്ലപ്പെട്ടവൻ) കുറ്റം അവൻ വഹിക്കും. അങ്ങനെ അവൻ നരകാവകാശിയാകും." അന്നേരം അയാൾ ഘാതകനെ വെറുതെവിട്ടു. (മു,ദ,ന)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹജർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 542, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَجُلًا عَضَّ يَدَ رَجُلٍ، فَانْتَزَعَ يَدَهُ، فَسَقَطَتْ ثَنِيَّتُهُ أَوْ ثَنَايَاهُ، فَاسْتَعْدَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا تَأْمُرُنِي؟ تَأْمُرُنِي أَنْ آمُرَهُ أَنْ يَدَعَ يَدَهُ فِي فِيكَ تَقْضَمُهَا كَمَا يَقْضَمُ الْفَحْلُ؟ اِدْفَعْ يَدَكَ حَتَّى يَعَضَّهَا ثُمَّ انْتَزِعْهَا". (ق,ت,ن)', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ): ഒരു വ്യക്തി മറ്റൊരാളുടെ കൈ കടിച്ചു. അയാൾ കൈ വലിച്ചൂരി. കടിച്ചയാളുടെ മുൻപല്ല്, അല്ലെങ്കിൽ രണ്ടു മുൻപല്ലുകൾ നിലത്തു വീണു. അദ്ദേഹം റസൂൽ(സ)യോട് കാര്യം ബോധിപ്പിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളെന്താണ് എന്നോട് ആവശ്യപ്പെടുന്നത്? ഒട്ടകം കടിച്ചുചവക്കുന്നതു പോലെ കടിച്ചു ചവക്കാൻ, അവന്റെ കൈ നിന്റെ വായിൽ വെച്ചുതരാൻ ഞാനവനോട് കൽപിക്കണമെന്നാണോ നീ ആവശ്യപ്പെടുന്നത്? നിന്റെ കൈ കൊടുക്കൂ, അവൻ കടിക്കട്ടെ. എന്നിട്ട് നീ കൈ വലിച്ചോ." (ബു,മു,തു,ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസ്വൈൻ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ يَعْلَى وَسَلَمَةَ ابْنَيْ أُمَيَّةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَا: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ، وَمَعَنَا صَاحِبٌ لَنَا، فَاقْتَتَلَ هُوَ وَرَجُلٌ آخَرُ وَنَحْنُ بِالطَّرِيقِ، قَالَ: فَعَضَّ الرَّجُلُ يَدَ صَاحِبِهِ، فَجَذَبَ صَاحِبُهُ يَدَهُ مِنْ فِيهِ، فَطَرَحَ ثَنِيَّتَهُ، فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَلْتَمِسُ عَقْلَ ثَنِيَّتِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَعْمِدُ أَحَدُكُمْ إِلَى أَخِيهِ فَيَعَضُّهُ كَعِضَاضِ الْفَحْلِ، ثُمَّ يَأْتِي يَلْتَمِسُ الْعَقْلَ! لَا عَقْلَ لَهَا". قَالَ: فَأَبْطَلَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن,جه)', 'ഉമയ്യത്തിന്റെ മക്കളായ യഅ്ല(റ), സലമ(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ തബൂക്ക് യുദ്ധത്തിന് പുറപ്പെട്ടു. കൂടെ ഞങ്ങളുടെ ഒരു സുഹൃത്തുമുണ്ടായിരുന്നു. വഴിയിൽ വെച്ച് സുഹൃത്തും മറ്റൊരാളും തമ്മിൽ അടിപിടിയായി. അങ്ങനെ അയാൾ സുഹൃത്തിന്റെ കയ്യിൽ കടിച്ചു. അപ്പോൾ സുഹൃത്ത് അവന്റെ വായിൽ നിന്ന് തന്റെ കൈ വലിച്ചു. അപ്പോൾ അയാളുടെ മുൻപല്ലുകൾ കൊഴിഞ്ഞ് വീണു. അദ്ദേഹം തന്റെ മുൻപല്ലിന് നഷ്ടപരിഹാരം തേടി റസൂൽ(സ)യെ സമീപിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ നിന്ന് ഒരാൾ തന്റെ സഹോദരനെ ഒട്ടകം കടിക്കുന്നത് പോലെ കടിക്കുന്നു. എന്നിട്ട് നഷ്ടപരിഹാരവും തേടിവരുന്നു! അതിന് നഷ്ടപരിഹാരമില്ല." നിവേദകൻ തുടരുന്നു: അതിനുള്ള നഷ്ടപരിഹാരം നബി(സ) ഒഴിവാക്കി. (ന,ജ)', 'يَعْلَى وَسَلَمَةَ ابْنَيْ أُمَيَّةَ', 'ഉമയ്യത്തിന്റെ മക്കളായ യഅ്ല(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 543, 543, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَمْرِو بْنِ حَزْمٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَتَبَ إِلَى أَهْلِ الْيَمَنِ كِتَابًا فِيهِ الْفَرَائِضُ وَالسُّنَنُ وَالدِّيَاتُ، وَبَعَثَ بِهِ مَعَ عَمْرِو بْنِ حَزْمٍ فَقُرِئَتْ عَلَى أَهْلِ الْيَمَنِ، هَذِهِ نُسْخَتُهَا: "مِنْ مُحَمَّدٍ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى شُرَحْبِيلَ بْنِ عَبْدِ كُلَالٍ وَنُعَيْمِ بْنِ عَبْدِ كُلَالٍ، وَالْحَارِثِ بْنِ عَبْدِ كُلَالٍ قَيْلِ ذِي رُعَيْنٍ وَمُعَافِرَ وَهَمْدَانَ، أَمَّا بَعْدُ..." وَكَانَ فِي كِتَابِهِ: "أَنَّ مَنِ اعْتَبَطَ مُؤْمِنًا قَتْلًا عَنْ بَيِّنَةٍ فَإِنَّهُ قَوَدٌ، إِلَّا أَنْ يَرْضَى أَوْلِيَاءُ الْمَقْتُولِ. وَأَنَّ فِي النَّفْسِ الدِّيَةَ مِائَةً مِنَ الْإِبِلِ، وَفِي الْأَنْفِ إِذَا أُوعِبَ جَدْعُهُ الدِّيَةُ، وَفِي اللِّسَانِ الدِّيَةُ، وَفِي الشَّفَتَيْنِ الدِّيَةُ، وَفِي الْبَيْضَتَيْنِ الدِّيَةُ، وَفِي الذَّكَرِ الدِّيَةُ، وَفِي الصُّلْبِ الدِّيَةُ، وَفِي الْعَيْنَيْنِ الدِّيَةُ، وَفِي الرِّجْلِ الْوَاحِدَةِ نِصْفُ الدِّيَةِ، وَفِي الْمَأْمُومَةِ ثُلُثُ الدِّيَةِ، وَفِي الْجَائِفَةِ ثُلُثُ الدِّيَةِ، وَفِي الْمُنَقِّلَةِ خَمْسَ عَشْرَةَ مِنَ الْإِبِلِ، وَفِي كُلِّ أُصْبُعٍ مِنْ أَصَابِعِ الْيَدِ وَالرِّجْلِ عَشْرٌ مِنَ الْإِبِلِ، وَفِي السِّنِّ خَمْسٌ مِنَ الْإِبِلِ، وَفِي الْمُوضِحَةِ خَمْسٌ مِنَ الْإِبِلِ، وَأَنَّ الرَّجُلَ يُقْتَلُ بِالْمَرْأَةِ، وَعَلَى أَهْلِ الذَّهَبِ أَلْفُ دِينَارٍ". وَفِي رِوَايَةٍ: "وَفِي الْعَيْنِ الْوَاحِدَةِ نِصْفُ الدِّيَةِ، وَفِي الْيَدِ الْوَاحِدَةِ نِصْفُ الدِّيَةِ". (ن)', 'അംറുബ്നു ഹസ്മ്(റ): യമൻ ദേശക്കാരിലേക്ക് റസൂൽ(സ) ഒരു കത്തെഴുതി. അതിൽ അനന്തരാവകാശികൾക്കുള്ള വിഹിതം, പ്രവാചകർ(സ)യുടെ ചര്യകൾ, നഷ്ടപരിഹാരങ്ങൾ തുടങ്ങിയവയാണ് പ്രതിപാദിച്ചിരുന്നത്. അംറുബ്നു ഹസ്മിനെ നബി(സ) കത്തുമായി പറഞ്ഞയച്ചു. അത് യമൻ ദേശക്കാർക്ക് വായിച്ചുകേൾപിച്ചു. ഇതാണ് കത്തിന്റെ പകർപ്പ്: "മുഹമ്മദ് നബി(സ)യിൽ നിന്ന് ശുറഹ്ബീലുബ്നു അബ്ദുകുലാൽ, നുഐമുബ്നു അബ്ദുകുലാൽ, ഹാരിസുബ്നു അബ്ദുകുലാൽ, ഖൈൽ ദീറുഐൻ, മുആഫിർ, ഹമദാൻ എന്നിവരിലേക്ക്..." ആ കത്തിൽ ഇങ്ങനെയുണ്ടായിരുന്നു: "വധിക്കപ്പെട്ടവന്റെ രക്ഷിതാക്കൾ (നഷ്ടപരിഹാരം കൊണ്ട്) തൃപ്തിപ്പെട്ടിട്ടില്ലെങ്കിൽ സത്യവിശ്വാസിയെ അകാരണമായി തെളിവു സഹിതം വധിച്ചവനെ വധിക്കണം. ഒരാളെ കൊന്നാൽ പൂർണ്ണ നഷ്ടപരിഹാരം നൽകണം. അത് നൂറ് ഒട്ടകമാണ്. മൂക്ക് കുറ്റിയടക്കം മുറിച്ചാൽ ഒരു പൂർണ്ണ നഷ്ടപരിഹാരം നൽകണം. നാവിനും പൂർണ്ണ നഷ്ടപരിഹാരം നൽകണം. രണ്ട് ചുണ്ടുകൾക്കും പൂർണ്ണ നഷ്ടപരിഹാരത്തിന്റെ മൂന്നിലൊന്ന് നൽകണം. ജനനേന്ദ്രിയം മുറിച്ചാൽ പൂർണ്ണ നഷ്ടപരിഹാരം നൽകണം. ലിംഗത്തിനും പൂർണ്ണ നഷ്ടപരിഹാരം നൽകണം. മുതുകിനും പൂർണ്ണ നഷ്ടപരിഹാരം നൽകണം. ഇരു കണ്ണുകൾക്കും പൂർണ്ണ നഷ്ടപരിഹാരം നൽകണം. ഒരു കാലിന് പൂർണ്ണ നഷ്ടപരിഹാരത്തിന്റെ പകുതി നൽകണം. മസ്തിഷ്കാവരണത്തിലേക്ക് എത്തുന്ന മുറിവിന് പൂർണ്ണ നഷ്ടപരിഹാരത്തിന്റെ മൂന്നിലൊന്ന് നൽകണം. തലക്കകത്തെ, അല്ലെങ്കിൽ വയറ്റിനകത്തെ, മുറിവിനും പൂർണ്ണ നഷ്ടപരിഹാരം നൽകണം. എല്ലിനെ ബാധിക്കുന്ന മുറിവിന് 15 ഒട്ടകം നഷ്ടപരിഹാരമായി നൽകണം. കൈകാലുകളിലെ എല്ലാ വിരലുകൾക്കും 10 ഒട്ടകം നഷ്ടപരിഹാരമായി നൽകണം. പല്ലിന് 5 ഒട്ടകമാണ് നഷ്ടപരിഹാരം. എല്ല് വെളിവാകുന്ന മുറിവിന് 5 ഒട്ടകവും നൽകണം. സ്ത്രീയെ വധിച്ചതിന് പുരുഷൻ വധിക്കപ്പെടും. സ്വർണ്ണം ഉപയോഗിക്കുന്നവർ നഷ്ടപരിഹാരമായി നൽകേണ്ടത് 1000 ദീനാറാണ്." മറ്റൊരു നിവേദനത്തിൽ: "ഒറ്റക്കണ്ണിൽ പൂർണ്ണ നഷ്ടപരിഹാരത്തിന്റെ പകുതിയാണ്. ഒരു കൈ മാത്രം മുറിച്ചതിന് പൂർണ്ണ നഷ്ടപരിഹാരത്തിന്റെ പകുതിയാണ്." (ന)', 'عَمْرِو بْنِ حَزْمٍ', 'അംറുബ്നു ഹസ്മ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 544, 544, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=44), 1, 'وَفِي رِوَايَةٍ: "وَفِي الْعَيْنِ الْوَاحِدَةِ نِصْفُ الدِّيَةِ، وَفِي الْيَدِ الْوَاحِدَةِ نِصْفُ الدِّيَةِ". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "ഒറ്റക്കണ്ണിൽ പൂർണ്ണ നഷ്ടപരിഹാരത്തിന്റെ പകുതിയാണ്. ഒരു കൈ മാത്രം മുറിച്ചതിന് പൂർണ്ണ നഷ്ടപരിഹാരത്തിന്റെ പകുതിയാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَبِي رِمْثَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: انْطَلَقْتُ مَعَ أَبِي نَحْوَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِأَبِي: "ابْنُكَ هَذَا". قَالَ: إِي وَرَبِّ الْكَعْبَةِ، قَالَ: "حَقًّا". قَالَ: أَشْهَدُ بِهِ، قَالَ: فَتَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَاحِكًا مِنْ ثَبْتِ شَبَهِي فِي أَبِي، وَمِنْ حَلِفِ أَبِي عَلَيَّ، ثُمَّ قَالَ: "أَمَا إِنَّهُ لَا يَجْنِي عَلَيْكَ وَلَا تَجْنِي عَلَيْهِ". وَقَرَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: {وَلَا تزرُ وَازِرَةٌ وِزْرَ أُخْرَى} [الأنعام: ١٦]. (د,ت,ن,جه)', 'അബൂരിംസ(റ): ഞാനെന്റെ പിതാവിന്റെ കൂടെ നബി(സ)യുടെ അടുത്തേക്ക് പോയി. നബി(സ) പിതാവിനോട് ചോദിച്ചു: "ഇത് നിങ്ങളുടെ മകനാണോ?" എന്റെ പിതാവ് പറഞ്ഞു: അതെ, കഅ്ബയുടെ നാഥൻ തന്നെ സത്യം. നബി(സ) ചോദിച്ചു: "സത്യം തന്നെ?" പിതാവ് പറഞ്ഞു: ഞാനതിന് സാക്ഷി നിൽക്കുന്നു. എന്റെ പിതാവിന്റെ എന്റെ വിഷയത്തിലുള്ള സത്യവും പിതാവിനോടുള്ള എന്റെ സാദൃശ്യവും കണ്ട് നബി(സ) പുഞ്ചിരിച്ചു. പിന്നെ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അവന് ദോഷം ചെയ്യില്ല. അവൻ നിങ്ങൾക്കും ദോഷം ചെയ്യില്ല." റസൂൽ(സ) ഓതിക്കേൾപിച്ചു: ''ഒരു കുറ്റം ചുമക്കുന്നവനും മറ്റൊരാളുടെ കുറ്റം ചുമക്കുന്നതല്ല." (അൻആം: 164) (ദ,തു,ന,ജ)', 'أَبِي رِمْثَةَ', 'അബൂരിംസ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], 'الأنعام: ١٦', null, 544, 545, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَلَا أُخْبِرُكُمْ بِمَا سَمِعْتُ مِنْ فِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ سَمِعَتْهُ أُذُنَايَ؟ وَوَعَاهُ قَلْبِي: "إِنَّ عَبْدًا قَتَلَ تِسْعَةً وَتِسْعِينَ نَفْسًا، ثُمَّ عُرِضَتْ لَهُ التَّوْبَةُ، فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ، فَدُلَّ عَلَى رَجُلٍ، فَأَتَاهُ فَقَالَ: إِنِّي قَتَلْتُ تِسْعَةً وَتِسْعِينَ نَفْسًا، فَهَلْ لِي مِنْ تَوْبَةٍ؟ قَالَ: بَعْدَ تِسْعَةٍ وَتِسْعِينَ نَفْسًا! قَالَ: فَانْتَضَى سَيْفَهُ فَقَتَلَهُ، فَأَكْمَلَ بِهِ الْمِائَةَ. ثُمَّ عُرِضَتْ لَهُ التَّوْبَةُ، فَسَأَلَ عَنْ أَعْلَمِ أَهْلِ الْأَرْضِ، فَدُلَّ عَلَى رَجُلٍ، فَأَتَاهُ فَقَالَ: إِنِّي قَتَلْتُ مِائَةَ نَفْسٍ، فَهَلْ لِي مِنْ تَوْبَةٍ؟ فَقَالَ: وَيْحَكَ، وَمَنْ يَحُولُ بَيْنَكَ وَبَيْنَ التَّوْبَةِ؟ اخْرُجْ مِنَ الْقَرْيَةِ الْخَبِيثَةِ الَّتِي أَنْتَ فِيهَا إِلَى الْقَرْيَةِ الصَّالِحَةِ، قَرْيَةِ كَذَا وَكَذَا، فَاعْبُدْ رَبَّكَ فِيهَا. فَخَرَجَ يُرِيدُ الْقَرْيَةَ الصَّالِحَةَ، فَعَرَضَ لَهُ أَجَلُهُ فِي الطَّرِيقِ، فَاخْتَصَمَتْ فِيهِ مَلَائِكَةُ الرَّحْمَةِ وَمَلَائِكَةُ الْعَذَابِ. قَالَ إِبْلِيسُ: أَنَا أَوْلَى بِهِ، إِنَّهُ لَمْ يَعْصِنِي سَاعَةً قَطُّ. قَالَ: فَقَالَتْ مَلَائِكَةُ الرَّحْمَةِ: إِنَّهُ خَرَجَ تَائِبًا" وَفِي رِوَايَةٍ: قَالَ: "فَبَعَثَ اللَّهُ عَزَّ وَجَلَّ مَلَكًا، فَاخْتَصَمُوا إِلَيْهِ ثُمَّ رَجَعُوا. فَقَالَ: انْظُرُوا أَيَّ الْقَرْيَتَيْنِ كَانَتْ أَقْرَبَ، فَأَلْحِقُوهُ بِأَهْلِهَا". وَفِي رِوَايَةٍ قَالَ: "لَمَّا حَضَرَهُ الْمَوْتُ احْتَفَزَ بِنَفْسِهِ فَقَرُبَ مِنَ الْقَرْيَةِ الصَّالِحَةِ، وَبَاعَدَ مِنْهُ الْقَرْيَةَ الْخَبِيثَةَ، فَأَلْحِقُوهُ بِأَهْلِ الْقَرْيَةِ الصَّالِحَةِ". (ق,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ)യുടെ തിരുവായിൽ നിന്ന് കേട്ടത് ഞാൻ നിങ്ങളെ കേൾപ്പിക്കട്ടെയോ? അതെന്റെ കാതുകൾ കേൾക്കുകയും ഹൃദയം സൂക്ഷിക്കുകയും ചെയ്തിരിക്കുന്നു: "ഒരാൾ തൊണ്ണൂറ്റി ഒമ്പത് പേരെ കൊന്നു. പിന്നെ അയാൾക്ക് തൗബ ചെയ്യണമെന്ന് തോന്നി. ഭൂമിയിലെ ഏറ്റവും വലിയ ജ്ഞാനിയെ അയാൾ അന്വേഷിച്ചു. അങ്ങനെ ഒരാളെക്കുറിച്ച് അദ്ദേഹത്തോട് പറയപ്പെട്ടു. അയാൾ അദ്ദേഹത്തെ സമീപിച്ചു ചോദിച്ചു: ഞാൻ തൊണ്ണൂറ്റിയൊമ്പത് പേരെ കൊന്നിട്ടുണ്ട്. എനിക്ക് തൗബയുണ്ടോ? അദ്ദേഹം ചോദിച്ചു: തൊണ്ണൂറ്റിയൊമ്പത് പേരെ കൊന്നതിന് ശേഷമോ! അപ്പോൾ തന്നെ അയാൾ വാള് വലിച്ചൂരി അദ്ദേഹത്തെയും കൊന്നു. അതോടെ അയാൾ നൂറ് പൂർത്തിയാക്കി. പിന്നെയും അയാൾക്ക് തൗബ ചെയ്യണമെന്ന് തോന്നി. ഭൂമിയിലെ ഏറ്റവും ഉന്നതനായ ജ്ഞാനിയെ അയാൾ അന്വേഷിച്ചു. അങ്ങനെ ഒരാളെക്കുറിച്ച് അദ്ദേഹത്തോട് പറയപ്പെട്ടു. അയാൾ അദ്ദേഹത്തിന്റെയടുത്തു ചെന്ന് ചോദിച്ചു: ഞാൻ നൂറ് പേരെ കൊന്നിട്ടുണ്ട്. എനിക്ക് തൗബയുണ്ടോ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിനക്കെന്താണ്? തൗബയുടെയും നിന്റെയുമിടയിൽ മറ സൃഷ്ടിക്കുന്നത് ആരാണ്? നീ താമസിക്കുന്ന ദുഷിച്ച നാട്ടിൽ നിന്ന് നല്ല ഇന്നാലിന്ന നാട്ടിലേക്ക് പുറപ്പെടുക. നീ അവിടെ വെച്ച് നിന്റെ നാഥന് വേണ്ടി ആരാധിക്കുക. അങ്ങനെ നല്ല നാടുദ്ദേശിച്ച് അയാൾ പുറപ്പെട്ടു. വഴിയിൽ വെച്ച് അയാളുടെ അന്ത്യമെത്തി. അദ്ദേഹത്തിന്റെ വിഷയത്തിൽ അനുഗ്രഹത്തിന്റെ മാലാഖമാരും ശിക്ഷയുടെ മാലാഖമാരും തർക്കിച്ചു. ഇബ്ലീസ് പറഞ്ഞു: ഞാനാണ് അവനോട് ഏറ്റവും ബന്ധപ്പെട്ടവൻ, ഒരു സമയവും അവൻ എനിക്ക് എതിര് ചെയ്തിട്ടില്ല. അനുഗ്രഹത്തിന്റെ മാലാഖ പറഞ്ഞു: അദ്ദേഹം പാപമോചനം തേടിയാണ് പുറപ്പെട്ടത്." മറ്റൊരു നിവേദനത്തിൽ: "അപ്പോൾ അല്ലാഹു ഒരു മാലാഖയെ അയച്ചു. ഇരുകൂട്ടരും തൽക്കിക്കുകയും വിഷയം ഈ മാലാഖയെ അറിയിക്കുകയും ചെയ്തു. അപ്പോൾ മാലാഖ പറഞ്ഞു: അവൻ ഏത് ദേശത്തോടാണ് അടുത്ത് കിടക്കുന്നതെന്ന് നിങ്ങൾ പരിശോധിക്കുക. എന്നിട്ട് അവനെ ആ ദേശക്കാരുടെ ഗണത്തിൽ പെടുത്തുക." മറ്റൊരു നിവേദനം: "മരണം അടുത്തപ്പോൾ അയാള് ഒന്നു ചാടി. അപ്പോൾ അയാള് നല്ല ദേശത്തോട് അടുക്കുകയും മോശമായ നാട്ടിൽ നിന്ന് അത്രദൂരം അകലുകയും ചെയ്തു. അങ്ങനെ അദ്ദേഹത്തെ അവർ നല്ല നാട്ടുകാരുടെ കൂട്ടത്തിൽ ഉൾപ്പെടുത്തി." (ബു,മു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 545, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=46), 1, 'وَفِي رِوَايَةٍ: قَالَ: "فَبَعَثَ اللَّهُ عَزَّ وَجَلَّ مَلَكًا، فَاخْتَصَمُوا إِلَيْهِ ثُمَّ رَجَعُوا. فَقَالَ: انْظُرُوا أَيَّ الْقَرْيَتَيْنِ كَانَتْ أَقْرَبَ، فَأَلْحِقُوهُ بِأَهْلِهَا".', 'മറ്റൊരു നിവേദനത്തിൽ: "അപ്പോൾ അല്ലാഹു ഒരു മാലാഖയെ അയച്ചു. ഇരുകൂട്ടരും തൽക്കിക്കുകയും വിഷയം ഈ മാലാഖയെ അറിയിക്കുകയും ചെയ്തു. അപ്പോൾ മാലാഖ പറഞ്ഞു: അവൻ ഏത് ദേശത്തോടാണ് അടുത്ത് കിടക്കുന്നതെന്ന് നിങ്ങൾ പരിശോധിക്കുക. എന്നിട്ട് അവനെ ആ ദേശക്കാരുടെ ഗണത്തിൽ പെടുത്തുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=46), 2, 'وَفِي رِوَايَةٍ قَالَ: "لَمَّا حَضَرَهُ الْمَوْتُ احْتَفَزَ بِنَفْسِهِ فَقَرُبَ مِنَ الْقَرْيَةِ الصَّالِحَةِ، وَبَاعَدَ مِنْهُ الْقَرْيَةَ الْخَبِيثَةَ، فَأَلْحِقُوهُ بِأَهْلِ الْقَرْيَةِ الصَّالِحَةِ". (ق,جه)', 'മറ്റൊരു നിവേദനം: "മരണം അടുത്തപ്പോൾ അയാള് ഒന്നു ചാടി. അപ്പോൾ അയാള് നല്ല ദേശത്തോട് അടുക്കുകയും മോശമായ നാട്ടിൽ നിന്ന് അത്രദൂരം അകലുകയും ചെയ്തു. അങ്ങനെ അദ്ദേഹത്തെ അവർ നല്ല നാട്ടുകാരുടെ കൂട്ടത്തിൽ ഉൾപ്പെടുത്തി." (ബു,മു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْأَصَابِعُ سَوَاءٌ، عَشْرٌ مِنَ الْإِبِلِ". (د,ن,جه)', 'അബൂമൂസൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ വിരലുകളും തുല്യമാണ്. എല്ലാറ്റിനും നഷ്ടപരിഹാരം പത്തൊട്ടകമാണ്." (ദ,ന,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 546, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَذِهِ وَهَذِهِ سَوَاءٌ" يَعْنِي الْإِبْهَامَ وَالْخِنْصَرَ. (خ,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇതും ഇതും സമമാണ്." അതായത് തള്ളവിരലും ചെറുവിരലും. (ബു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 546, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْأَصَابِعُ سَوَاءٌ، وَالْأَسْنَانُ سَوَاءٌ، الثَّنِيَّةُ وَالضِّرْسُ سَوَاءٌ، هَذِهِ وَهَذِهِ سَوَاءٌ". وَفِي رِوَايَةٍ: "الْأَسْنَانُ سَوَاءٌ، وَالْأَصَابِعُ سَوَاءٌ". وَفِي رِوَايَةٍ: جَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَصَابِعَ الْيَدَيْنِ وَالرِّجْلَيْنِ سَوَاءً. (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വിരലുകൾ സമമാണ്. പല്ലുകൾ സമമാണ്. കോൺപല്ലും മുൻപല്ലും സമമാണ്. ഇതും ഇതും സമമാണ്." മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "പല്ലുകളും വിരലുകളും സമമാണ്." മറ്റൊരു നിവേദനം: കൈ വിരലുകളും കാൽ വിരലുകളും നബി(സ) തുല്യമാക്കി. (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 546, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=49), 1, 'وَفِي رِوَايَةٍ: "الْأَسْنَانُ سَوَاءٌ، وَالْأَصَابِعُ سَوَاءٌ".', 'മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "പല്ലുകളും വിരലുകളും സമമാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=49), 2, 'وَفِي رِوَايَةٍ: جَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَصَابِعَ الْيَدَيْنِ وَالرِّجْلَيْنِ سَوَاءً. (د,ت,جه)', 'മറ്റൊരു നിവേദനം: കൈ വിരലുകളും കാൽ വിരലുകളും നബി(സ) തുല്യമാക്കി. (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فِي دِيَةِ الْخَطَإِ: عِشْرُونَ حِقَّةً، وَعِشْرُونَ جَذَعَةً، وَعِشْرُونَ بِنْتَ مَخَاضٍ، وَعِشْرُونَ بِنْتَ لَبُونٍ، وَعِشْرُونَ بَنِي مَخَاضٍ ذُكُورٍ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അവിചാരിതമായി വധം സംഭവിച്ചാൽ നഷ്ടപരിഹാരമായി നൽകേണ്ടത് ഇതാണ്: മൂന്ന് വയസ്സുള്ള ഇരുപത് പെണ്ണൊട്ടകം. നാല് വയസ്സുള്ള ഇരുപത് പെണ്ണൊട്ടകം, ഒരു വയസ്സുള്ള ഇരുപത് പെണ്ണൊട്ടകം, രണ്ട് വയസ്സുള്ള ഇരുപത് പെണ്ണൊട്ടകം, രണ്ട് വയസ്സുള്ള ഇരുപത് ആണൊട്ടകം." (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 546, 546, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَتَلَ عَمْدًا دُفِعَ إِلَى أَوْلِيَاءِ الْقَتِيلِ: فَإِنْ شَاءُوا قَتَلُوا، وَإِنْ شَاءُوا أَخَذُوا الدِّيَةَ. وَذَلِكَ: ثَلَاثُونَ حِقَّةً، وَثَلَاثُونَ جَذَعَةً، وَأَرْبَعُونَ خَلِفَةً. وَذَلِكَ عَقْلُ الْعَمْدِ، مَا صُولِحُوا عَلَيْهِ فَهُوَ لَهُمْ، وَذَلِكَ تَشْدِيدُ الْعَقْلِ". (د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "മനഃപൂർവ്വം ആരെങ്കിലും വധിച്ചാൽ അവനെ കൊല്ലപ്പെട്ടവന്റെ സംരക്ഷകർക്ക് കൈമാറണം. അവർ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അവർക്കവനെ കൊല്ലാം. അവർ ഉദ്ദേശിച്ചാൽ അവർക്ക് നഷ്ടപരിഹാരം സ്വീകരിക്കാം. നഷ്ടപരിഹാരം മൂന്ന് വയസ്സുള്ള മുപ്പത് പെണ്ണൊട്ടകവും നാല് വയസ്സുള്ള മുപ്പത് പെണ്ണൊട്ടകവും ഗർഭമുള്ള നാൽപത് പെണ്ണൊട്ടകവുമാണ്. ഇതാണ് മനഃപൂർവ്വം ചെയ്ത കൊലയുടെ നഷ്ടപരിഹാരം. സന്ധി പ്രകാരം അതിനോട് വല്ലതും ചേർക്കപ്പെട്ടാൽ അതും അവർക്കുള്ളതു തന്നെ. ഇത് നഷ്ടപരിഹാരത്തെ ശക്തിപ്പെടുത്തലാണ്." (ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 546, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى فِي الْعَيْنِ الْعَوْرَاءِ السَّادَّةِ لِمَكَانِهَا إِذَا طُمِسَتْ بِثُلُثِ دِيَتِهَا، وَفِي الْيَدِ الشَّلَّاءِ إِذَا قُطِعَتْ بِثُلُثِ دِيَتِهَا، وَفِي السِّنِّ السَّوْدَاءِ إِذَا نُزِعَتْ بِثُلُثِ دِيَتِهَا. (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): കേടുവന്ന കണ്ണിൽ മാന്തിയാൽ അത് കണ്ണിന്റെ വട്ടത്തുനിന്ന് പുറത്ത് പോന്നിട്ടില്ലെങ്കിൽ മൂന്നിലൊന്ന് നഷ്ടപരിഹാരം നൽകാൻ റസൂൽ(സ) ഉത്തരവിട്ടു. ക്ഷയിച്ച കൈ മുറിക്കപ്പെട്ടാലും മൂന്നിലൊന്ന് നഷ്ടപരിഹാരം നൽകണം. കറുത്ത പല്ല് പറിഞ്ഞുപോന്നാലും മൂന്നിലൊന്ന് നഷ്ടപരിഹാരം നൽകണം. (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 547, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي شُرَيْحٍ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أُصِيبَ بِدَمٍ أَوْ خَبْلٍ – وَالْخَبْلُ الْجُرْحُ – فَهُوَ بِالْخِيَارِ بَيْنَ إِحْدَى ثَلَاثٍ، فَإِنْ أَرَادَ الرَّابِعَةَ فَخُذُوا عَلَى يَدَيْهِ: أَنْ يَقْتُلَ أَوْ يَعْفُوَ أَوْ يَأْخُذَ الدِّيَةَ. فَمَنْ فَعَلَ شَيْئًا مِنْ ذَلِكَ فَعَادَ فَإِنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا". (خ,د,ت,ن)', 'അബൂശുറൈഹിൽ ഖുസാഇൗ: റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും വധിക്കപ്പെടുകയോ മുറിവേൽപ്പിക്കപ്പെടുകയോ ചെയ്താൽ അവന് മൂന്നാലൊരു കാര്യം ഇഷ്ടാനുസരണം ചെയ്യാം. അവൻ നാലാമതൊന്ന് ഉദ്ദേശിച്ചാൽ അവന്റെ കരം നിങ്ങൾ പിടിച്ചുകൊള്ളുക: വധിക്കുക, മാപ്പ് നൽകുക, നഷ്ടപരിഹാരം സ്വീകരിക്കുക. ഇതിൽ ഏതെങ്കിലുമൊന്ന് ചെയ്ത് വീണ്ടും ഒന്നുകൂടി ചെയ്താൽ അവൻ ശാശ്വതനായി നരകത്തിൽ പ്രവേശിക്കും." (ബു,ദ,തു,ന)', 'أَبِي شُرَيْحٍ الْخُزَاعِيِّ', 'അബൂശുറൈഹിൽ ഖുസാഇൗ', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 547, 547, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ سَالِمِ بْنِ أَبِي الْجَعْدِ قَالَ: سُئِلَ ابْنُ عَبَّاسٍ – رَضِيَ اللهُ عَنْهُمَا – عَمَّنْ قَتَلَ مُؤْمِنًا مُتَعَمِّدًا، ثُمَّ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى؟ قَالَ: وَيْحَهُ! وَأَنَّى لَهُ الْهُدَى؟ سَمِعْتُ نَبِيَّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَجِيءُ الْقَاتِلُ وَالْمَقْتُولُ – يَوْمَ الْقِيَامَةِ – مُتَعَلِّقٌ بِرَأْسِ صَاحِبِهِ، يَقُولُ: رَبِّ! سَلْ هَذَا، لِمَ قَتَلَنِي". وَاللهِ، لَقَدْ أَنْزَلَهَا اللهُ عَزَّ وَجَلَّ عَلَى نَبِيِّكُمْ، ثُمَّ مَا نَسَخَهَا بَعْدَمَا أَنْزَلَهَا. (ن,جه)', 'സാലിമുബ്നു അബീജഅ്ദ(റ): മനഃപൂർവ്വം ഒരു വിശ്വാസിയെ വധിക്കുകയും പിന്നീട് തൗബ ചെയ്യുകയും, വിശ്വസിക്കുകയും, സൽകർമ്മം അനുഷ്ഠിക്കുകയും, സന്മാർഗ്ഗം സിദ്ധിക്കുകയും ചെയ്ത ഒരു വ്യക്തിയെക്കുറിച്ച് ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: അവന് നാശം! എങ്ങനെയാണ് അവന് സന്മാർഗ്ഗം ലഭിക്കുക. നിങ്ങളുടെ പ്രവാചകൻ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ഘാതകനും വധിക്കപ്പെട്ടവനും അന്ത്യദിനത്തിൽ പരസ്പരം തല ബന്ധിച്ച നിലയിൽ വരും. വധിക്കപ്പെട്ടവൻ പറയും: രക്ഷിതാവേ, ഇയാളോട് ചോദിക്കൂ, ഇവൻ എന്തിനാണ് എന്നെ വധിച്ചതെന്ന്." അല്ലാഹു സത്യം, നിശ്ചയം അല്ലാഹു നിങ്ങളുട പ്രവാചകന് ഈ സന്ദേശമിറക്കിയിരിക്കുന്നു. അതിനു ശേഷം അവനതിനെ നസ്ഖ് ചെയ്തിട്ടുമില്ല. (ന,ജ)', 'سَالِمِ بْنِ أَبِي الْجَعْدِ قَالَ', 'സാലിമുബ്നു അബീജഅ്ദ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 547, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ فِي بَنِي إِسْرَائِيلَ الْقِصَاصُ وَلَمْ تَكُنْ فِيهِمُ الدِّيَةُ، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنْثَى بِالْأُنْثَى} إِلَى قَوْلِهِ: {فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ فَاتِّبَاعٌ بِالْمَعْرُوفِ وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ}. فَالْعَفْوُ: أَنْ يَقْبَلَ الدِّيَةَ فِي الْعَمْدِ. وَاتِّبَاعٌ بِمَعْرُوفٍ: يَقُولُ: يَتَّبِعُ هَذَا بِالْمَعْرُوفِ. وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ: وَيُؤَدِّي هَذَا بِإِحْسَانٍ. ذَلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌ: مِمَّا كُتِبَ عَلَى مَنْ كَانَ قَبْلَكُمْ، إِنَّمَا هُوَ الْقِصَاصُ لَيْسَ الدِّيَةَ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ബനൂഇസ്റാഇൗലിൽ പ്രതിക്രയയുണ്ടായിരുന്നു. നഷ്ടപരിഹരം നൽകുക എന്ന രീതിയുണ്ടായിരുന്നില്ല. അപ്പോൾ അല്ലാഹു ആയത്തിറക്കി: ''വധിക്കപ്പെടുന്നവരുടെ കാര്യത്തിൽ പ്രതിക്രിയ നടപ്പാക്കൽ നിങ്ങളുടെ മേൽ നിർബന്ധമാണ്. സ്വതന്ത്രനു പകരം സ്വതന്ത്രനും അടിമക്ക് പകരം അടിമയും സ്ത്രീക്ക് പകരം സ്ത്രീയും (കൊല്ലപ്പെടേണ്ടതാണ്)'' എന്നതുമതൽ ''അവന് (കൊലയാളിക്ക്) തന്റെ സഹോദരനിൽ നിന്ന് വല്ല ഇളവും ലഭിക്കുകയാണെങ്കിൽ, മര്യാദ പാലിച്ച് അവൻ നന്മ പിൻപറ്റുകയും നല്ല നിലയിൽ (നഷ്ടപരിഹാരം) കൊടുത്തുവീട്ടുകയും ചെയ്യേണ്ടതാണ്'' എന്നതുവരെ. ഇളവ് എന്നാൽ: മനഃപൂർവ്വമുള്ള കൊലയിൽ നഷ്ടപരിഹാരം സ്വീകരിക്കലാണ്. നല്ലരീതിയിൽ പിന്തുടരുക എന്നാൽ: വാദി പ്രതിയെ നല്ലരീതിയിൽ പിന്തുടരലാണ്. നല്ലരീതിയിൽ കൊടുത്തുവീട്ടുക എന്നാൽ: പ്രതി വാദിക്ക് നല്ലരീതിയിൽ കൊടുത്തുവീട്ടലാണ്. അത് നിങ്ങളുടെ നാഥനിൽ നിന്നുള്ള ഇളവും അനുഗ്രഹവുമാണ് എന്നാൽ: നിങ്ങളുടെ മുൻഗാമികളുടെ മേൽ നിർബന്ധമാക്കപ്പെട്ടിരുന്ന, നഷ്ടപരിഹാരമില്ലാത്ത പ്രതിക്രിയമാത്രമുള്ള നിയമത്തിൽ നിന്നുള്ള ഇളവ് എന്നാണർത്ഥം. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 548, 548, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَفَرًا مِنْ عُكْلٍ ثَمَانِيَةً قَدِمُوا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَبَايَعُوهُ عَلَى الْإِسْلَامِ، فَاسْتَوْخَمُوا الْأَرْضَ وَسَقِمَتْ أَجْسَامُهُمْ، فَشَكَوْا ذَلِكَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "أَلَا تَخْرُجُونَ مَعَ رَاعِينَا فِي إِبِلِهِ، فَتُصِيبُونَ مِنْ أَبْوَالِهَا وَأَلْبَانِهَا". فَقَالُوا: بَلَى، فَخَرَجُوا فَشَرِبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا، فَصَحُّوا، فَقَتَلُوا الرَّاعِيَ وَطَرَدُوا الْإِبِلَ، فَبَلَغَ ذَلِكَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَبَعَثَ فِي آثَارِهِمْ فَأُدْرِكُوا، فَجِيءَ بِهِمْ، فَأَمَرَ بِهِمْ فَقُطِعَتْ أَيْدِيهِمْ وَأَرْجُلُهُمْ، وَسُمِرَ أَعْيُنُهُمْ، ثُمَّ نُبِذُوا فِي الشَّمْسِ حَتَّى مَاتُوا. (م)', 'അനസുബ്നു മാലിക്(റ): ഉക്ൽ ഗോത്രത്തിൽ പെട്ട എട്ടുപേർ റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് ഇസ്ലാമിൽ ബൈഅത്ത് ചെയ്തു. അവർക്ക് ഭൂമിയുടെ അന്തരീക്ഷം പിടിച്ചില്ല. അവർക്ക് രോഗമായി. അവർ റസൂൽ(സ)യോട് വേവലാതി പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ ഒട്ടകം മേക്കുന്ന ഞങ്ങളുടെ ഇടയൻമാരുടെ കൂടെ ചെന്ന് അതിന്റെ പാലും മൂത്രവും കുടിക്കുക." അവർ പറഞ്ഞു: അതെ. അവർ പുറപ്പെട്ടു. അങ്ങനെ ഒട്ടകത്തിന്റെ പാലും മൂത്രവും അവർ കുടിച്ചു. അവരുടെ രോഗം മാറി. അവർ ഇടയനെ കൊന്നു. ഒട്ടകങ്ങളെ മോഷ്ടിച്ചുകൊണ്ടുപോയി. വിവരം റസൂൽ(സ)യുടെ അടുത്തെത്തി. അവരുടെ കാൽപാടുകളെ പിന്തുടർന്ന് അവരെ പിടിച്ചുകൊണ്ടുവരാൻ തിരുമേനി(സ) ആളെ അയച്ചു. അവർ പിടിക്കപ്പെട്ടു. അവരെ നബി(സ)യുടെ സന്നിധിയിൽ കൊണ്ടുവന്നു. നബി(സ) അവരുടെ കൈകാലുകൾ ഛേദിക്കാനും കണ്ണുകൾ ചൂഴ്ന്നെടുക്കാനും പറഞ്ഞു. പിന്നെ അവരെ മരിക്കുന്നതു വരെ വെയിലത്ത് നിർത്തി. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 548, 549, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا كَانَ يَوْمُ فَتْحِ مَكَّةَ أَمَّنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ النَّاسَ إِلَّا أَرْبَعَةَ نَفَرٍ وَامْرَأَتَيْنِ، وَقَالَ: "اُقْتُلُوهُمْ وَإِنْ وَجَدْتُمُوهُمْ مُتَعَلِّقِينَ بِأَسْتَارِ الْكَعْبَةِ": عِكْرِمَةُ بْنُ أَبِي جَهْلٍ، وَعَبْدُ اللهِ بْنُ خَطَلٍ، وَمِقْيَسُ بْنُ صُبَابَةَ، وَعَبْدُ اللهِ بْنُ سَعْدِ بْنِ أَبِي السَّرْحِ. فَأَمَّا عَبْدُ اللهِ بْنُ خَطَلٍ: فَأُدْرِكَ وَهُوَ مُتَعَلِّقٌ بِأَسْتَارِ الْكَعْبَةِ، فَاسْتَبَقَ إِلَيْهِ سَعِيدُ بْنُ حُرَيْثٍ وَعَمَّارُ بْنُ يَاسِرٍ، فَسَبَقَ سَعِيدٌ عَمَّارًا، وَكَانَ أَشَبَّ الرَّجُلَيْنِ، فَقَتَلَهُ. وَأَمَّا مِقْيَسُ بْنُ صُبَابَةَ: فَأَدْرَكَهُ النَّاسُ فِي السُّوقِ فَقَتَلُوهُ. وَأَمَّا عِكْرِمَةُ: فَرَكِبَ الْبَحْرَ، فَأَصَابَتْهُمْ عَاصِفٌ، فَقَالَ أَصْحَابُ السَّفِينَةِ: أَخْلِصُوا، فَإِنَّ آلِهَتَكُمْ لَا تُغْنِي عَنْكُمْ شَيْئًا هَاهُنَا. فَقَالَ عِكْرِمَةُ: وَاللهِ لَئِنْ لَمْ يُنَجِّنِي مِنَ الْبَحْرِ إِلَّا الْإِخْلَاصُ لَا يُنَجِّينِي فِي الْبَرِّ غَيْرُهُ، اللَّهُمَّ إِنَّ لَكَ عَلَيَّ عَهْدًا إِنْ أَنْتَ عَافَيْتَنِي مِمَّا أَنَا فِيهِ أَنْ آتِيَ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَضَعَ يَدِي فِي يَدِهِ، فَلَأَجِدَنَّهُ عَفُوًّا كَرِيمًا، فَجَاءَ فَأَسْلَمَ. وَأَمَّا عَبْدُ اللهِ بْنُ سَعْدِ بْنِ أَبِي السَّرْحِ: فَإِنَّهُ اخْتَبَأَ عِنْدَ عُثْمَانَ بْنِ عَفَّانَ، فَلَمَّا دَعَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ النَّاسَ إِلَى الْبَيْعَةِ جَاءَ بِهِ حَتَّى أَوْقَفَهُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: يَا رَسُولَ اللهِ، بَايِعْ عَبْدَ اللهِ. قَالَ: فَرَفَعَ رَأْسَهُ فَنَظَرَ إِلَيْهِ، ثَلَاثًا، كُلَّ ذَلِكَ يَأْبَى، فَبَايَعَهُ بَعْدَ ثَلَاثٍ، ثُمَّ أَقْبَلَ عَلَى أَصْحَابِهِ فَقَالَ: "أَمَا كَانَ فِيكُمْ رَجُلٌ رَشِيدٌ، يَقُومُ إِلَى هَذَا حَيْثُ رَآنِي كَفَفْتُ يَدِي عَنْ بَيْعَتِهِ فَيَقْتُلُهُ". فَقَالُوا: وَمَا يُدْرِينَا يَا رَسُولَ اللهِ مَا فِي نَفْسِكَ، هَلَّا أَوْمَأْتَ إِلَيْنَا بِعَيْنِكَ؟ قَالَ: "إِنَّهُ لَا يَنْبَغِي لِنَبِيٍّ أَنْ يَكُونَ لَهُ خَائِنَةُ أَعْيُنٍ". (ن)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): മക്കാ വിജയത്തിന്റെ ദിനത്തിൽ നബി(സ) നാല് പുരുഷൻമാരും രണ്ട് സ്ത്രീകളും ഒഴികെ എല്ലാവർക്കും അഭയം നൽകി. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അവരെ വധിക്കുക, കഅ്ബയുടെ വിരിയിൽ പിടിച്ചവരായി നിങ്ങൾ അവരെ കണ്ടാലും ശരി." ഇക്രിമതുബ്നു അബീജഹൽ, അബ്ദുല്ലാഹിബ്നു ഖത്വൽ, മഖീസുബ്നു സ്വുബാബ, അബ്ദുല്ലാഹിബ്നു സഅ്ദുബ്നു അബീസർഹ് എന്നിരാണ് ആ നാല് പുരുഷൻമാർ. അബ്ദുല്ലാഹിബ്നു ഖത്വലിനെ കഅ്ബയുടെ വിരിയിൽ പിടിച്ചവനായി കാണപ്പെട്ടു. സഈദുബ്നു ഹുറൈസ്(റ)വും അമ്മാറുബ്നു യാസിർ(റ)വും അദ്ദേഹത്തിനടുത്തേക്ക് കുതിച്ചു. സഈദ്(റ) അമ്മാർ(റ)വിനെ പിന്നിലാക്കി. സഈദ്(റ)വായിരുന്നു അവരിരുവരിൽ പ്രായം കുറഞ്ഞവൻ. സഈദ്(റ) അദ്ദേഹത്തെ വധിച്ചു. മഖീസുബ്നു സ്വുബാബയെ ജനങ്ങൾ അങ്ങാടിയിൽ വെച്ച് കണ്ടുമുട്ടി. അവർ അദ്ദേഹത്തെ വധിച്ചു. ഇക്രിമ കപ്പലിൽ കയറി. അവർ കൊടുങ്കാറ്റിൽ പെട്ടു. കപ്പലിന്റെ ഉടമകൾ പറഞ്ഞു: നിങ്ങൾ ഏകദൈവവിശ്വാസികളാകൂ. ഇവിടെ നിങ്ങൾക്കുവേണ്ടി നിങ്ങളുടെ ദൈവങ്ങൾക്ക് ഒന്നും ചെയ്യാൻ കഴിയില്ല. അപ്പോൾ ഇക്രിമ(റ) പറഞ്ഞു: എന്നെ കടലിൽ നിന്ന് ഏകദൈവവിശ്വാസം മാത്രമേ രക്ഷപ്പെടുത്തുവെങ്കിൽ കരയിലും എന്നെ അതല്ലാതെ രക്ഷിക്കുകയില്ല. അല്ലാഹുവേ, ഞാൻ അകപ്പെട്ടതിൽ നിന്ന് നീ എനിക്ക് മോചനം നൽകിയാൽ ഞാൻ മുഹമ്മദ് നബി(സ)യുടെ അടുത്ത് പോയി എന്റെ കരം അവിടത്തെ കരത്തിൽ വെക്കുമെന്ന് ഞാനിതാ നിനക്ക് കരാർ നൽകുന്നു. മുഹമ്മദ് നബി(സ)യെ ഞാൻ മാപ്പ് നൽകുന്നവനായും മാന്യനായും എത്തിക്കുക തന്നെ ചെയ്യും. അങ്ങനെ അദ്ദേഹം വന്ന് മുസ്ലിമായി. അബ്ദുല്ലാഹിബ്നു സഅ്ദുബ്നു അബീസർഹ് ഉസ്മാൻ(റ)വിന്റെ അരികിൽ മറഞ്ഞിരുന്നു. നബി(സ) ജനങ്ങളെ ബൈഅത്തിന് വേണ്ടി ക്ഷണിച്ചപ്പോൾ ഉസ്മാൻ(റ) അദ്ദേഹത്തെ നബി(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നു നിർത്തി. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് അബ്ദുല്ലക്ക് ബൈഅത്ത് നൽകിയാലും. നബി(സ) തലയുയർത്തി. അദ്ദേഹത്തെ മൂന്ന് പ്രാവശ്യം നോക്കി. ഈ സമയത്തെല്ലാം നബി(സ) വിലങ്ങുകയായിരുന്നു. മൂന്നാമത്തെ നോട്ടത്തിന് ശേഷം നബി(സ) ബൈഅത്ത് നൽകി. പിന്നെ സ്വഹാബികളിലേക്ക് തിരിഞ്ഞ് നബി(സ) ഇങ്ങനെ പറഞ്ഞു: "അയാളുടെ ബൈഅത്തിൽ നിന്ന് ഞാൻ പിന്മാറുന്നത് കണ്ട് അയാളെ വന്നു കൊല്ലാൻ തന്റേടമുള്ള ആരും നിങ്ങളിൽ ഉണ്ടായിരുന്നില്ലേ." സ്വഹാബികൾ പറഞ്ഞു: നബിയേ, അങ്ങയുടെ മനസ്സിലുള്ളത് ഞങ്ങൾക്ക് അറിയുമായിരുന്നില്ല. അങ്ങ് ഞങ്ങളോട് കണ്ണ് കൊണ്ട് ആംഗ്യം കാണിച്ചിരുന്നുവെങ്കിൽ? നബി(സ) പറഞ്ഞു: "വഞ്ചനയുടെ നോട്ടം ഒരു പ്രവാചകനും യോജിച്ചതല്ല." (ന)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 549, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أُمِرْتُ أَنْ أُقَاتِلَ الْمُشْرِكِينَ – وَفِي رِوَايَةٍ: النَّاسَ – حَتَّى يَشْهَدُوا: أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا – رَسُولُ اللهِ – عَبْدُهُ وَرَسُولُهُ. فَإِذَا شَهِدُوا أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا – رَسُولُ اللهِ – عَبْدُهُ وَرَسُولُهُ، وَصَلُّوا صَلَاتَنَا وَاسْتَقْبَلُوا قِبْلَتَنَا وَأَكَلُوا ذَبِيحَتَنَا، فَقَدْ حَرُمَتْ عَلَيْنَا دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا". وَفِي رِوَايَةٍ: "لَهُمْ مَا لِلْمُسْلِمِينَ وَعَلَيْهِمْ مَا عَلَيْهِمْ". (ن)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും മുഹമ്മദുർറസൂലുല്ലാഹി(റ) അവന്റെ ദൂതനുമാണ് എന്നതിന് സാക്ഷിയാകുന്നതു വരെ ബഹുദൈവാരാധകരോട് യുദ്ധം ചെയ്യാൻ ഞാൻ കൽപ്പിക്കപ്പെട്ടിരിക്കുന്നു. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, മുഹമ്മദുർറസൂലുല്ലാഹി(സ) അവന്റെ അടിമയും റസൂലുമാണ് എന്നതിന് അവർ സാക്ഷിയാവുകയും നമസ്കാരം നിർവ്വഹിക്കുകയും നമ്മുടെ ഖിബ്ലക്ക് മുന്നിടുകയും നാം അറുത്തത് ഭക്ഷിക്കുകയും ചെയ്താൽ, അവരുടെ രക്തവും സമ്പത്തും അതിന്റെ അവകാശത്തോട് കൂടെയല്ലാതെ നിഷിദ്ധമാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "മുസ്ലിംകൾക്കുള്ളത് അവർക്കുണ്ട്. മുസ്ലിംകളുടെ മേൽ ബാധ്യതയുള്ളത് അവർക്കും ബാധ്യതയാണ്." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 550, 550, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=58), 1, 'وَفِي رِوَايَةٍ: النَّاسَ – حَتَّى يَشْهَدُوا: أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا – رَسُولُ اللهِ – عَبْدُهُ وَرَسُولُهُ. فَإِذَا شَهِدُوا أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا – رَسُولُ اللهِ – عَبْدُهُ وَرَسُولُهُ، وَصَلُّوا صَلَاتَنَا وَاسْتَقْبَلُوا قِبْلَتَنَا وَأَكَلُوا ذَبِيحَتَنَا، فَقَدْ حَرُمَتْ عَلَيْنَا دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا".', 'മറ്റൊരു നിവേദനിൽ: "മുസ്ലിംകൾക്കുള്ളത് അവർക്കുണ്ട്. മുസ്ലിംകളുടെ മേൽ ബാധ്യതയുള്ളത് അവർക്കും ബാധ്യതയാണ്." (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=58), 2, 'وَفِي رِوَايَةٍ: "لَهُمْ مَا لِلْمُسْلِمِينَ وَعَلَيْهِمْ مَا عَلَيْهِمْ". (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاسْتُخْلِفَ أَبُو بَكْرٍ، وَكَفَرَ مَنْ كَفَرَ مِنَ الْعَرَبِ، قَالَ عُمَرُ لِأَبِي بَكْرٍ: كَيْفَ تُقَاتِلُ النَّاسَ وَقَدْ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لَا إِلَهَ إِلَّا اللهُ، فَمَنْ قَالَ: لَا إِلَهَ إِلَّا اللهُ، عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ إِلَّا بِحَقِّهِ، وَحِسَابُهُ عَلَى اللهِ". قَالَ أَبُو بَكْرٍ: وَاللهِ لَأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلَاةِ وَالزَّكَاةِ، فَإِنَّ الزَّكَاةَ حَقُّ الْمَالِ، وَاللهِ لَوْ مَنَعُونِي – عِنَاقًا – عِقَالًا كَانُوا يُؤَدُّونَهُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَقَاتَلْتُهُمْ عَلَى مَنْعِهِ. قَالَ عُمَرُ: فَوَاللهِ مَا هُوَ إِلَّا أَنِّي رَأَيْتُ اللهَ شَرَحَ صَدْرَ أَبِي بَكْرٍ لِلْقِتَالِ فَعَرَفْتُ أَنَّهُ الْحَقُّ. (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) വഫാത്താകുകയും അബൂബക്കർ(റ) ഖലീഫയാകുകയും അറബികളിൽ ചിലർ സത്യനിഷേധികളാകുകയും ചെയ്തപ്പോൾ ഉമർ(റ) അബൂബക്കർ(റ)വിനോട് ചോദിച്ചു: റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞിട്ടില്ലെയോ: "ജനങ്ങൾ ലാഇലാഹ ഇല്ലല്ലാഹു (അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല) എന്ന് പറയുംവരെ അവരോട് യുദ്ധംചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടു. ആരെങ്കിലും ലാഇലാഹഇല്ലല്ലാഹു എന്ന് പറഞ്ഞാൽ തന്റെ മുതലും ശരീരവും എന്നിൽ നിന്നും അവൻ സുക്ഷിച്ചിരിക്കുന്നു, അവനെ വിചാരണ ചെയ്യേണ്ടത് അല്ലാഹുവാണ്." അതുകൊണ്ട് താങ്കൾ എങ്ങനെയാണ് ജനങ്ങളോട് യുദ്ധം ചെയ്യുക. അബൂബക്കർ(റ) പറഞ്ഞു: നിസ്കാരത്തിനും സകാത്തിനുമിടയിൽ വ്യത്യാസം കാണുന്നവരോട് ഞാൻ യുദ്ധം ചെയ്യുക തന്നെ ചെയ്യും. സകാത്ത് മുതലിലെ അവകാശമാണ്. അല്ലാഹുവാണ് സത്യം, റസൂൽ(സ)ക്ക് അവർ നൽകാറുണ്ടായിരുന്ന ഒട്ടകക്കയർ എനിക്ക് നൽകാതിരുന്നാൽ അതിന്റെ പേരിൽ ഞാനവരോട് യുദ്ധം ചെയ്യുക തന്നെ ചെയ്യും. ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, യുദ്ധം ചെയ്യാനുള്ള അബൂബക്കർ(റ)വിന്റെ തീരുമാനം അല്ലാഹു അദ്ധേഹത്തിന് മനസ്സിൽ ഉണർത്തിക്കൊടുത്തതാണ്. അതാണ് സത്യമെന്ന് ഞാൻ മനസ്സിലാക്കുകയും ചെയ്തു. (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 550, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ فِي قُبَّةٍ فِي مَسْجِدِ الْمَدِينَةِ، وَقَالَ فِيهِ: "إِنَّهُ أُوحِيَ إِلَيَّ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لَا إِلَهَ إِلَّا اللهُ" نَحْوَهُ. وَفِي رِوَايَةٍ قَالَ: أَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي وَفْدِ ثَقِيفٍ، فَكُنْتُ مَعَهُ فِي قُبَّةٍ، فَنَامَ مَنْ كَانَ فِي الْقُبَّةِ غَيْرِي وَغَيْرُهُ، فَجَاءَ رَجُلٌ فَسَارَّهُ، فَقَالَ: "اذْهَبْ فَاقْتُلْهُ". فَقَالَ: "أَلَيْسَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنِّي رَسُولُ اللهِ". قَالَ: يَشْهَدُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ذَرْهُ". ثُمَّ قَالَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لَا إِلَهَ إِلَّا اللهُ، فَإِذَا قَالُوهَا حَرُمَتْ دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا". وَفِي رِوَايَةٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللهُ، ثُمَّ تَحْرُمُ دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا". (ن)', 'ഔസ്(റ): ഞങ്ങൾ മദീനാ പള്ളിയിലെ ഖുബ്ബയിലിരിക്കുമ്പോൾ റസൂൽ(സ) കടന്നുവന്നു. അവിടെ വെച്ച് നബി(സ) പറഞ്ഞു: "ജനങ്ങൾ അല്ലാഹു അല്ലാതെ ഒരാരാധ്യനില്ലെന്ന് പറയുന്നത് വരെ അവരോട് യുദ്ധം ചെയ്യണമെന്ന് എനിക്ക് വഹ്യ് ലഭിച്ചിരിക്കുന്നു." ഇതിനു സമാനമായ ഹദീസ് പറഞ്ഞു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഔസ്(റ) പറഞ്ഞു: സഖീഫ് നിവേദക സംഘത്തിൽ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് വന്നു. ഞാൻ നബി(സ)യുടെ കൂടെ ഖുബ്ബയിലായിരുന്നു. ഞാനും നബി(സ)യുമല്ലാത്ത ഖുബ്ബയിലുള്ള എല്ലാവരും ഉറങ്ങി. അപ്പോൾ ഒരാൾ വന്ന് നബി(സ)യോടെന്തോ രഹസ്യം പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അയാളെ കൊല്ലുക." പിന്നെ നബി(സ) ചോദിച്ചു: "അല്ലാഹുവല്ലാതെ ഒരാരാധ്യനുമില്ലെന്നും ഞാനവന്റെ പ്രവാചകനാണെന്നും അയാൾ സാക്ഷ്യം വഹിക്കുന്നുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അയാൾ സാക്ഷ്യം വഹിക്കുന്നുണ്ട്. അപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "അയാളെ വെറുതെവിടുക." ശേഷം അവിടന്ന് പറഞ്ഞു: "ജനങ്ങൾ അല്ലാഹു അല്ലാതെ ഒരാരാധ്യനില്ലെന്ന് പറയുന്നതു വരെ അവരോട് യുദ്ധം ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു. അവർ അത് പറഞ്ഞാൽ അവരുടെ സമ്പത്തും രക്തവും അതിന്റെ അവകാശത്തിലൂടെയല്ലാതെ നിഷിദ്ധമായിരിക്കുന്നു." മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "ജനങ്ങൾ അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്ന് സാക്ഷ്യം വഹിക്കാത്ത കാലത്തോളം അവരോട് സമരം ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു. സാക്ഷ്യം വഹിച്ചു കഴിഞ്ഞാൽ അവരുടെ സ്വത്ത്, രക്തം എന്നിവ അതിന്റെ അവകാശത്തിലൂടെയല്ലാതെ നിശിദ്ധമാണ്." (ന)', 'أَوْسٍ', 'ഔസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 551, 551, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=60), 1, 'وَفِي رِوَايَةٍ قَالَ: أَتَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي وَفْدِ ثَقِيفٍ، فَكُنْتُ مَعَهُ فِي قُبَّةٍ، فَنَامَ مَنْ كَانَ فِي الْقُبَّةِ غَيْرِي وَغَيْرُهُ، فَجَاءَ رَجُلٌ فَسَارَّهُ، فَقَالَ: "اذْهَبْ فَاقْتُلْهُ". فَقَالَ: "أَلَيْسَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنِّي رَسُولُ اللهِ". قَالَ: يَشْهَدُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ذَرْهُ". ثُمَّ قَالَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لَا إِلَهَ إِلَّا اللهُ، فَإِذَا قَالُوهَا حَرُمَتْ دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا".', 'മറ്റൊരു നിവേദനിൽ: ഔസ്(റ) പറഞ്ഞു: സഖീഫ് നിവേദക സംഘത്തിൽ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് വന്നു. ഞാൻ നബി(സ)യുടെ കൂടെ ഖുബ്ബയിലായിരുന്നു. ഞാനും നബി(സ)യുമല്ലാത്ത ഖുബ്ബയിലുള്ള എല്ലാവരും ഉറങ്ങി. അപ്പോൾ ഒരാൾ വന്ന് നബി(സ)യോടെന്തോ രഹസ്യം പറഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അയാളെ കൊല്ലുക." പിന്നെ നബി(സ) ചോദിച്ചു: "അല്ലാഹുവല്ലാതെ ഒരാരാധ്യനുമില്ലെന്നും ഞാനവന്റെ പ്രവാചകനാണെന്നും അയാൾ സാക്ഷ്യം വഹിക്കുന്നുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അയാൾ സാക്ഷ്യം വഹിക്കുന്നുണ്ട്. അപ്പോൾ അല്ലാഹുവിന്റെ റസൂൽ(സ) പറഞ്ഞു: "അയാളെ വെറുതെവിടുക." ശേഷം അവിടന്ന് പറഞ്ഞു: "ജനങ്ങൾ അല്ലാഹു അല്ലാതെ ഒരാരാധ്യനില്ലെന്ന് പറയുന്നതു വരെ അവരോട് യുദ്ധം ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു. അവർ അത് പറഞ്ഞാൽ അവരുടെ സമ്പത്തും രക്തവും അതിന്റെ അവകാശത്തിലൂടെയല്ലാതെ നിഷിദ്ധമായിരിക്കുന്നു."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=60), 2, 'وَفِي رِوَايَةٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللهُ، ثُمَّ تَحْرُمُ دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا". (ن)', 'മറ്റൊരു നിവേദനം: നബി(സ) പറഞ്ഞു: "ജനങ്ങൾ അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്ന് സാക്ഷ്യം വഹിക്കാത്ത കാലത്തോളം അവരോട് സമരം ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു. സാക്ഷ്യം വഹിച്ചു കഴിഞ്ഞാൽ അവരുടെ സ്വത്ത്, രക്തം എന്നിവ അതിന്റെ അവകാശത്തിലൂടെയല്ലാതെ നിശിദ്ധമാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ رَجُلٌ فَسَارَّهُ، فَقَالَ: "اقْتُلُوهُ". ثُمَّ قَالَ: "أَيَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ". قَالَ: نَعَمْ، وَلَكِنَّمَا يَقُولُهَا تَعَوُّذًا. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقْتُلُوهُ، فَإِنَّمَا أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا: لَا إِلَهَ إِلَّا اللهُ، فَإِذَا قَالُوهَا عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّهَا، وَحِسَابُهُمْ عَلَى اللهِ". (ن)', 'നുഅ്മാനുബ്നു ബഷീർ(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെ നിൽക്കവെ ഒരാൾ വന്ന് അവിടത്തോട് രഹസ്യം പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അവനെ വധിക്കുക." ശേഷം അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്ന് അവൻ സാക്ഷ്യം വഹിക്കുന്നുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അതെ, പക്ഷെ രക്ഷപ്പെടാനാണ് അയാളത് പറയുന്നത്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങളവനെ വധിക്കരുത്. ലാഇലാഹ ഇല്ലല്ലാഹു എന്ന് പറയുന്നത് വരെ ജനങ്ങളോട് യുദ്ധം ചെയ്യാനാണ് ഞാൻ കൽപ്പക്കപ്പെട്ടത്. അവരത് പറഞ്ഞാൽ, അവരടുടെ സമ്പത്തും രക്തവും അതിന്റെ അവകാശത്തിലൂടെയല്ലാതെ എന്നിൽ നിന്നും അവർ സംരക്ഷിച്ചിരിക്കുന്നു. അവരെ വിചാരണ ചെയ്യേണ്ടത് അല്ലാഹുവാണ്." (ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബഷീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 551, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ، لَقَتْلُ مُؤْمِنٍ أَعْظَمُ عِنْدَ اللهِ مِنْ زَوَالِ الدُّنْيَا". وَفِي رِوَايَةٍ قَالَ: "لَزَوَالُ الدُّنْيَا أَهْوَنُ عِنْدَ اللهِ مِنْ قَتْلِ رَجُلٍ مُسْلِمٍ". وَفِي رِوَايَةٍ: "قَتْلُ الْمُؤْمِنِ أَعْظَمُ عِنْدَ اللهِ مِنْ زَوَالِ الدُّنْيَا". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ശരീരം ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, ഒരു വിശ്വാസിയെ വധിക്കൽ ദുനിയാവ് നശിക്കുന്നതിനെക്കാൾ അല്ലാഹുവിന്റെ അടുത്ത് ഗുരുതരമാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "ദുനിയാവ് നശിക്കുന്നത് അല്ലാഹുവിങ്കൽ ഒരു മുസ്ലിമായ വ്യക്തിയെ കൊല്ലുന്നതിനെക്കാൾ നിസ്സാരമാണ്." മറ്റൊരു നിവേദനത്തിൽ: "വിശ്വാസിയെ വധിക്കൽ അല്ലാഹുവിന്റെയടുത്ത് ദുൻയാവ് നശിക്കുന്നതിനെക്കാൾ ഗുരുതരമാണ്." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=62), 1, 'وَفِي رِوَايَةٍ قَالَ: "لَزَوَالُ الدُّنْيَا أَهْوَنُ عِنْدَ اللهِ مِنْ قَتْلِ رَجُلٍ مُسْلِمٍ".', 'മറ്റൊരു നിവേദനിൽ: "ദുനിയാവ് നശിക്കുന്നത് അല്ലാഹുവിങ്കൽ ഒരു മുസ്ലിമായ വ്യക്തിയെ കൊല്ലുന്നതിനെക്കാൾ നിസ്സാരമാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=62), 2, 'وَفِي رِوَايَةٍ: "قَتْلُ الْمُؤْمِنِ أَعْظَمُ عِنْدَ اللهِ مِنْ زَوَالِ الدُّنْيَا". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: "വിശ്വാസിയെ വധിക്കൽ അല്ലാഹുവിന്റെയടുത്ത് ദുൻയാവ് നശിക്കുന്നതിനെക്കാൾ ഗുരുതരമാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ الصَّلَاةُ، وَأَوَّلُ مَا يُقْضَى بَيْنَ النَّاسِ فِي الدِّمَاءِ". وَفِي رِوَايَةٍ: "أَوَّلُ مَا يُحْكَمُ بَيْنَ النَّاسِ فِي الدِّمَاءِ". وَفِي رِوَايَةٍ: "أَوَّلُ مَا يُقْضَى بَيْنَ النَّاسِ يَوْمَ الْقِيَامَةِ فِي الدِّمَاءِ". (م,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആദ്യമായി അടിമ വിചാരണ ചെയ്യപ്പെടുന്നത് നിസ്കാരത്തെക്കുറിച്ചാണ്. ആദ്യമായി ജനങ്ങൾക്കിടയിൽ വിധി നടപ്പാക്കുന്നത് വധത്തിലാണ്." മറ്റൊരു നിവേദനത്തിൽ: "ജനങ്ങൾക്കിടയിൽ ആദ്യമായി വിധിക്കപ്പെടുന്നത് വധത്തിലാണ്." മറ്റൊരു റിപ്പോർട്ടിൽ: "അന്ത്യദിനത്തിൽ ആദ്യമായി വിധി നടപ്പാക്കപ്പെടുന്നത് വധ സംബന്ധമായ വിഷയത്തിലണ്." (മു,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=63), 1, 'وَفِي رِوَايَةٍ: "أَوَّلُ مَا يُحْكَمُ بَيْنَ النَّاسِ فِي الدِّمَاءِ".', 'മറ്റൊരു നിവേദനത്തിൽ: "ജനങ്ങൾക്കിടയിൽ ആദ്യമായി വിധിക്കപ്പെടുന്നത് വധത്തിലാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=63), 2, 'وَفِي رِوَايَةٍ: "أَوَّلُ مَا يُقْضَى بَيْنَ النَّاسِ يَوْمَ الْقِيَامَةِ فِي الدِّمَاءِ". (م,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: "അന്ത്യദിനത്തിൽ ആദ്യമായി വിധി നടപ്പാക്കപ്പെടുന്നത് വധ സംബന്ധമായ വിഷയത്തിലണ്." (മു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَجِيءُ الرَّجُلُ آخِذًا بِيَدِ الرَّجُلِ فَيَقُولُ: يَا رَبِّ، هَذَا قَتَلَنِي. فَيَقُولُ اللهُ لَهُ: لِمَ قَتَلْتَهُ؟ فَيَقُولُ: قَتَلْتُهُ لِتَكُونَ الْعِزَّةُ لَكَ. فَيَقُولُ: فَإِنَّهَا لِي. وَيَجِيءُ الرَّجُلُ آخِذًا بِيَدِ الرَّجُلِ فَيَقُولُ: هَذَا قَتَلَنِي. فَيَقُولُ اللهُ لَهُ: لِمَ قَتَلْتَهُ. فَيَقُولُ: لِتَكُونَ الْعِزَّةُ لِفُلَانٍ. فَيَقُولُ: إِنَّهَا لَيْسَتْ لِفُلَانٍ. فَيَبُوءُ بِإِثْمِهِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ മറ്റൊരാളുടെ കൈ പിടിച്ചുകൊണ്ട് വരും. എന്നിട്ട് പറയും: രക്ഷിതാവേ, ഇയാളാണ് എന്നെ കൊന്നത്. അല്ലാഹു അവനോട് ചോദിക്കും: നീ എന്തിനാണ് അവനെ കൊന്നത്? അപ്പോൾ അവൻ പറയും: ഞാനവനെ കൊന്നത് അഭിമാനം നിനക്കാകാൻ വേണ്ടിയാണ്. അപ്പോൾ അല്ലാഹു പറയും: അതെനിക്ക് തന്നെയാണ്. ശേഷം ഒരാൾ മറ്റൊരാളുടെ കരം പിടിച്ചുകൊണ്ട് ഇങ്ങനെ പറയും: ഇയാൾ എന്നെ കൊന്നു. അപ്പോൾ അല്ലാഹു പറയും: നിങ്ങളെന്തിനാണ് അയാളെ കൊന്നത്? അയാൾ പറയും: അഭിമാനം ഇന്നവനാവാൻ വേണ്ടി. അല്ലാഹു പറയും: അത് ഇന്നവനല്ല. അങ്ങനെ അവൻ കുറ്റത്തിന് വിധേയനാകും." (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 552, 552, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ هَذَا الرَّجُلَ قَتَلَ أَخِي. قَالَ: "اذْهَبْ فَاقْتُلْهُ كَمَا قَتَلَ أَخَاكَ". فَقَالَ لَهُ الرَّجُلُ: اتَّقِ اللهَ وَاعْفُ عَنِّي، فَإِنَّهُ أَعْظَمُ لِأَجْرِكَ وَخَيْرٌ لَكَ وَلِأَخِيكَ يَوْمَ الْقِيَامَةِ. قَالَ: فَخَلَّى عَنْهُ. قَالَ: فَأُخْبِرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ فَأَخْبَرَهُ بِمَا قَالَ لَهُ، قَالَ: فَأَعْنَفَهُ: "أَمَا إِنَّهُ كَانَ خَيْرًا مِمَّا هُوَ صَانِعٌ بِكَ يَوْمَ الْقِيَامَةِ، يَقُولُ: يَا رَبِّ، سَلْ هَذَا فِيمَ قَتَلَنِي". (ن)', 'ബുറൈദ(റ): ഒരു വ്യക്തി നബി(സ)യുടെ സന്നിധിയിൽ വന്ന് പറഞ്ഞു: റസൂലേ, ഇയാൾ എന്റെ സഹോദരനെ വധിച്ചു. നബി(സ) പറഞ്ഞു: "നീ പോകുക. അവൻ നിന്റെ സഹോദരനെ വധിച്ചതുപോലെ അദ്ദേഹത്തെയും നീ വധിക്കുക." അപ്പോൾ ഘാതകൻ അയാളോട് പറഞ്ഞു: നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക, എനിക്ക് മാപ്പ് നൽകിയാൽ അത് നിനക്ക് അങ്ങേയറ്റം പ്രതിഫലമേകുന്നതാണ്. ഖിയാമത് നാളിൽ നിനക്കും നിന്റെ സഹോദരനും ഉത്തമം അതായിരിക്കും. അദ്ദേഹം ഘാതകനെ വെറുതെ വിട്ടു. വിവരം നബി(സ)യോട് അറിയിക്കപ്പെട്ടു. നബി(സ) അദ്ദേഹത്തോട് വിഷയം തിരക്കി. ഘാതകൻ പറഞ്ഞത് അയാൾ നബി(സ)യോട് പറഞ്ഞു. നബി(സ) ഗൗരവസ്വരത്തിൽ പറഞ്ഞു: "അയാൾ അന്ത്യനാളിൽ നിന്നോട് ചെയ്യുന്നതിനേക്കാൾ ഉത്തമം അതായിരുന്നു. അന്നദ്ദേഹം പറയും: രക്ഷിതാവേ, എന്നെ എന്തിനു വേണ്ടിയാണ് കൊന്നതെന്ന് നീ അദ്ദേഹത്തോട് ചോദിക്കുക." (ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 552, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي إِدْرِيسَ قَالَ: سَمِعْتُ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ يَخْطُبُ، وَكَانَ قَلِيلَ الْحَدِيثِ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: سَمِعْتُهُ يَخْطُبُ يَقُولُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كُلُّ ذَنْبٍ عَسَى اللهُ أَنْ يَغْفِرَهُ، إِلَّا الرَّجُلُ يَقْتُلُ الْمُؤْمِنَ مُتَعَمِّدًا، أَوِ الرَّجُلُ يَمُوتُ كَافِرًا". (د,ن)', 'അബൂഇദ്രീസ്(റ): മുആവിയ(റ) പ്രസംഗിക്കുന്നത് ഞാൻ കേട്ടു. റസൂൽ(സ)യിൽ നിന്ന് കുറച്ച് ഹദീസ് നിവേദനം ചെയ്തയാളാണദ്ദേഹം. അദ്ദേഹം പ്രസംഗിക്കവെ പറയുന്നത് ഞാൻ കേട്ടു. ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടു: "എല്ലാ ദോഷവും അല്ലാഹു പൊറുത്തുതരും. ഒരു വിശ്വാസിയെ മനഃപൂർവ്വം വധിച്ചവനൊഴികെ, സത്യനിഷേധിയായി മരണപ്പെട്ടവനുമൊഴികെ." (ദ,ന)', 'أَبِي إِدْرِيسَ قَالَ', 'അബൂഇദ്രീസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، أَيُّ الذَّنْبِ أَعْظَمُ؟ قَالَ: "أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهُوَ خَلَقَكَ". قُلْتُ: ثُمَّ مَاذَا؟ قَالَ: "أَنْ تَقْتُلَ وَلَدَكَ خَشْيَةَ – مِنْ أَجْلِ – أَنْ يَطْعَمَ مَعَكَ". وَفِي رِوَايَةٍ: "مَخَافَةَ الْفَقْرِ أَنْ يَأْكُلَ مَعَكَ". قُلْتُ: ثُمَّ مَاذَا؟ قَالَ: "أَنْ تُزَانِيَ بِحَلِيلَةِ جَارِكَ". ثُمَّ قَرَأَ عَبْدُ اللهِ: {وَالَّذِينَ لَا يَدْعُونَ مَعَ اللهِ إِلَهًا آخَرَ} [الفرقان: ٦٨] (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഏത് ദോഷമാണ് ഏറ്റവും ഗുരുതരമായത്? റസൂൽ(സ) പറഞ്ഞു: "നീ അല്ലാഹുവിന് പങ്കുകാരനെ ചേർക്കുക, അവനാണ് നിന്നെ പടച്ചത്." ഞാൻ ചോദിച്ചു: പിന്നെ ഏതാണ്? റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ കൂടെ ഭക്ഷിക്കുമെന്ന് പേടിച്ച് നിന്റെ കുട്ടിയെ നീ വധിക്കുക." മറ്റൊരു റിപ്പോർട്ടിൽ: "നിന്റെ കൂടെ അവൻ ഭക്ഷിച്ചാലുള്ള ദാരിദ്ര്യത്തെ ഭയന്ന്." ഞാൻ ചോദിച്ചു: പിന്നെ ഏതാണ്? അവിടന്ന് പറഞ്ഞു: "നിന്റെ അയൽവാസിയുടെ ഭാര്യയെ നീ വ്യഭിചരിക്കൽ." പിന്നെ അബ്ദുല്ല(റ) ഓതിക്കേൾപിച്ചു: ''അല്ലാഹുവിന്റെ കൂടെ മറ്റൊരു ദൈവത്തെ വിളിക്കാത്തവർ.'' (ഫുർഖാൻ: 68) (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الفرقان: ٦٨', null, 553, 553, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=67), 1, 'وَفِي رِوَايَةٍ: "مَخَافَةَ الْفَقْرِ أَنْ يَأْكُلَ مَعَكَ". قُلْتُ: ثُمَّ مَاذَا؟ قَالَ: "أَنْ تُزَانِيَ بِحَلِيلَةِ جَارِكَ". ثُمَّ قَرَأَ عَبْدُ اللهِ: {وَالَّذِينَ لَا يَدْعُونَ مَعَ اللهِ إِلَهًا آخَرَ} [الفرقان: ٦٨] (ن)', 'മറ്റൊരു നിവേദനിൽ: "നിന്റെ കൂടെ അവൻ ഭക്ഷിച്ചാലുള്ള ദാരിദ്ര്യത്തെ ഭയന്ന്." ഞാൻ ചോദിച്ചു: പിന്നെ ഏതാണ്? അവിടന്ന് പറഞ്ഞു: "നിന്റെ അയൽവാസിയുടെ ഭാര്യയെ നീ വ്യഭിചരിക്കൽ." പിന്നെ അബ്ദുല്ല(റ) ഓതിക്കേൾപിച്ചു: ''അല്ലാഹുവിന്റെ കൂടെ മറ്റൊരു ദൈവത്തെ വിളിക്കാത്തവർ.'' (ഫുർഖാൻ: 68) (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ: أَمَرَنِي عَبْدُ الرَّحْمَنِ بْنُ أَبْزَى رَضِيَ اللهُ عَنْهُ أَنْ أَسْأَلَ ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا عَنْ هَاتَيْنِ الْآيَتَيْنِ: {وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ} فَسَأَلْتُهُ، فَقَالَ: لَمْ يَنْسَخْهَا شَيْءٌ. وَعَنْ هَذِهِ الْآيَةِ: {وَالَّذِينَ لَا يَدْعُونَ مَعَ اللهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللهُ إِلَّا بِالْحَقِّ} قَالَ: نَزَلَتْ فِي أَهْلِ الشِّرْكِ. (ن)', 'സഈദുബ്നു ജുബൈർ(റ): രണ്ട് സൂക്തങ്ങളെക്കുറിച്ച് ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിക്കാൻ അബ്ദുർറഹ്മാനുബ്നു അബ്സ(റ) എന്നോടാവശ്യപ്പെട്ടു. ''ആരെങ്കിലും ഒരു വിശ്വാസിയെ കരുതിക്കൂട്ടി കൊന്നാൽ അവനുള്ള പ്രതിഫലം നരകമാണ്.'' ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ഞാനിതിനെക്കുറിച്ച് ചോദിച്ചു. അവർ പറഞ്ഞു: ഈ സൂക്തത്തെ ഒന്നും അസാധു(നസ്ഖ്) ആക്കിയിട്ടില്ല. ''അല്ലാഹുവിന് ഒപ്പം മറ്റൊരു ദൈവത്തെ വിളിക്കാത്തവർ, അല്ലാഹു പവിത്രമാക്കിയ ശരീരത്തെ അവകാശത്തോടുകൂടെയല്ലാതെവധിക്കാത്തവർ'' എന്ന സൂക്തത്തെക്കുറിച്ചും ചോദിച്ചു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഇത് ബഹുദൈവാരാധകരെക്കുറിച്ച് ഇറങ്ങിയതാണ്. (ന)', 'سَعِيدِ بْنِ جُبَيْرٍ قَالَ', 'സഈദുബ്നു ജുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 553, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ: اخْتَلَفَ أَهْلُ الْكُوفَةِ فِي هَذِهِ الْآيَةِ: {وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا} فَرَحَلْتُ إِلَى ابْنِ عَبَّاسٍ فَسَأَلْتُهُ فَقَالَ: نَزَلَتْ فِي آخِرِ مَا أُنْزِلَتْ، وَمَا نَسَخَهَا شَيْءٌ. (ن)', 'സഈദുബ്നു ജുബൈർ(റ): കൂഫക്കാർ ഈ സൂക്തത്തിൽ തർക്കിച്ചു, ''കരുതിക്കൂട്ടി ആരെങ്കിലും വിശ്വാസിയെ വധിച്ചാൽ''. അപ്പോൾ ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ അടുക്കലേക്ക് വാഹനം കയറി. ഞാൻ അവരോട് ചോദിച്ചു. അവർ പറഞ്ഞു: അത് അവസാനം ഇറക്കപ്പെട്ടവയിൽ പെട്ടതാണത്. അതിനെ ഒന്നും അസാധുവാക്കിയിട്ടില്ല. (ന)', 'سَعِيدِ بْنِ جُبَيْرٍ قَالَ', 'സഈദുബ്നു ജുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ قَالَ: قُلْتُ لِابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: هَلْ لِمَنْ قَتَلَ مُؤْمِنًا مُتَعَمِّدًا مِنْ تَوْبَةٍ؟ قَالَ: لَا. وَقَرَأْتُ عَلَيْهِ الْآيَةَ الَّتِي فِي الْفُرْقَانِ: {وَالَّذِينَ لَا يَدْعُونَ مَعَ اللهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللهُ إِلَّا بِالْحَقِّ} قَالَ: هَذِهِ آيَةٌ مَكِّيَّةٌ، نَسَخَتْهَا آيَةٌ مَدَنِيَّةٌ: {وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ}. (ن)', 'സഈദുബ്നു ജുബൈർ(റ): ഞാൻ ഇബ്നുഅബ്ബാസ്(റ)വിനോട് ചോദിച്ചു: വിശ്വാസിയെ മനഃപൂർവ്വം കൊന്നവന് പശ്ചാത്താപമുണ്ടോ? ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഇല്ല. ഞാനവർക്ക് ഖുർആനിലെ ഈ സൂക്തം ഓതിക്കൊടുത്തു. ''അല്ലാഹുവിന്റെ കൂടെ മറ്റു ദൈവങ്ങളെ വിളിക്കാത്തവർ, അല്ലാഹു പരിശുദ്ധമാക്കിയ ശരീരത്തെ അവകാശത്തോടുകൂടെയല്ലാതെ വധിക്കാത്തവർ''. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: ഈ സൂക്തം മക്കയിൽ വെച്ചിറങ്ങിയതാണ്. ഈ സൂക്തത്തെ മദീനയിൽ വെച്ചിറങ്ങിയ സൂക്തം അസാധുവാക്കിയിട്ടുണ്ട്. ''ആരെങ്കിലും ഒരു വിശ്വാസിയെ മനപ്പൂർവ്വം കൊലചെയ്താൽ അവനുള്ള പ്രതിഫലം നരകമാണ്.'' (ന)', 'سَعِيدِ بْنِ جُبَيْرٍ قَالَ', 'സഈദുബ്നു ജുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزْنِي الْعَبْدُ حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ، وَلَا يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ، وَلَا يَسْرِقُ وَهُوَ مُؤْمِنٌ، وَلَا يَقْتُلُ وَهُوَ مُؤْمِنٌ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അടിമ വ്യഭിചരിക്കുമ്പോൾ വിശ്വാസിയായി വ്യഭിചരിക്കുകയില്ല. മദ്യം കുടിക്കുമ്പോൾ വിശ്വാസിയായി മദ്യപിക്കുകയില്ല. വിശ്വാസിയായിരിക്കെ അവൻ മോഷ്ടിക്കുകയില്ല. വിശ്വാസിയായിരിക്കെ അവൻ കൊല നടത്തുകയുമില്ല." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي أَيُّوبَ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ جَاءَ يَعْبُدُ اللهَ وَلَا يُشْرِكُ بِهِ شَيْئًا، وَيُقِيمُ الصَّلَاةَ وَيُؤْتِي الزَّكَاةَ، وَيَجْتَنِبُ الْكَبَائِرَ، كَانَ لَهُ الْجَنَّةُ". فَسَأَلُوهُ عَنِ الْكَبَائِرِ، فَقَالَ: "الْإِشْرَاكُ بِاللهِ، وَقَتْلُ النَّفْسِ الْمُسْلِمَةِ، وَالْفِرَارُ يَوْمَ الزَّحْفِ". (ن)', 'അബൂഅയ്യൂബുൽ അൻസാരി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ ആരാധിച്ച് അവനോട് ആരെയും പങ്ക് ചേർക്കാതെ, നിസ്കാരം നിലനിർത്തി, സകാത്ത് വീട്ടി, വൻകുറ്റങ്ങൾ വെടിഞ്ഞ് ആരെങ്കിലും വന്നാൽ അവന് സ്വർഗമുണ്ട്." അപ്പോൾ അവർ വൻകുറ്റങ്ങളെക്കുറിച്ച് തിരുമേനി(സ)യോട് ചോദിച്ചു: അവിടന്ന് പറഞ്ഞു: "അല്ലാഹുവിൽ പങ്ക് ചേർക്കുക, മുസ്ലിമായ വ്യക്തിയെ വധിക്കുക, യുദ്ധദിവസം പിന്തിരിയുക." (ന)', 'أَبِي أَيُّوبَ الْأَنْصَارِيِّ', 'അബൂഅയ്യൂബുൽ അൻസാരി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 554, 554, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْكَبَائِرُ: الْإِشْرَاكُ بِاللهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَقَتْلُ النَّفْسِ، وَالْيَمِينُ الْغَمُوسُ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വൻകുറ്റങ്ങൾ അല്ലാഹുവിനോട് പങ്ക്ചേർക്കലും മാതാപിതാക്കളെ വെറുപ്പിക്കലും ഒരാളെ വധിക്കലും കള്ളസത്യം ചെയ്യലുമാണ്." (ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 554, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عُمَيْرِ بْنِ قَتَادَةَ رَضِيَ اللهُ عَنْهُ، وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللهِ، مَا الْكَبَائِرُ؟ قَالَ: "هُنَّ سَبْعٌ: أَعْظَمُهُنَّ إِشْرَاكٌ بِاللهِ، وَقَتْلُ النَّفْسِ بِغَيْرِ حَقٍّ، وَفِرَارٌ يَوْمَ الزَّحْفِ". (ن)', 'ഉമൈറുബ്നു ഖതാദ(റ): അദ്ദേഹം നബി(സ)യുടെ അനുചരരിൽ പെട്ടയാളായിരുന്നു. ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, വൻകുറ്റങ്ങൾ ഏതൊക്കെയാണ്? റസൂൽ(സ) പറഞ്ഞു: "അത് ഏഴെണ്ണമാണ്. അതിൽ ഏറ്റവും ഗുരുതരമായത് അല്ലാഹുവിൽ പങ്ക്ചേർക്കലാണ്, അനർഹമായി ഒരാളെ വധിക്കലാണ്, യുദ്ധദിവസം പിന്തിരിഞ്ഞോടലാണ്." (ന)', 'عُمَيْرِ بْنِ قَتَادَةَ', 'ഉമൈറുബ്നു ഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ أُتِيَ بِنَاسٍ مِنَ الزُّطِّ يَعْبُدُونَ وَثَنًا، فَأَحْرَقَهُمْ. قَالَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: إِنَّمَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ". (ن)', 'അനസ്(റ): അലി(റ)വിന്റെ അടുത്തേക്ക് ബിംബാരാധകരായ സുഥ് വിഭാഗത്തിൽ പെട്ട കുറച്ചു പേരെ കൊണ്ടുവരപ്പെട്ടു അലി(റ) അവരെ കരിച്ചുകൊന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: "ആരെങ്കിലും മതം മാറിയാൽ അവനെ നിങ്ങൾ കൊല്ലുക" എന്നു മാത്രമാണ് തിരുമേനി(സ) പറഞ്ഞത്. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ أَبِي بَرْزَةَ رَضِيَ اللهُ عَنْهُ قَالَ: تَغَيَّظَ أَبُو بَكْرٍ رَضِيَ اللهُ عَنْهُ عَلَى رَجُلٍ، فَقُلْتُ: مَنْ هُوَ يَا خَلِيفَةَ رَسُولِ اللهِ؟ قَالَ: لِمَ؟ قُلْتُ: لِأَضْرِبَ عُنُقَهُ إِنْ أَمَرْتَنِي بِذَلِكَ. قَالَ: أَفَكُنْتَ فَاعِلًا؟ قُلْتُ: نَعَمْ، قَالَ: فَوَاللهِ لَأَذْهَبَ عِظَمُ كَلِمَتِيَ الَّتِي قُلْتُ غَضَبَهُ. ثُمَّ قَالَ: مَا كَانَ لِأَحَدٍ بَعْدَ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അബൂബുർസ(റ): അബൂബക്കർ(റ) ഒരാളോട് കോപിഷ്ടനായി. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലിന്റെ ഖലീഫയേ, അതാരാണ്? അബൂബക്കർ(റ) പറഞ്ഞു: എന്തിനാണ്? ഞാൻ പറഞ്ഞു: താങ്കൾ കൽപിക്കുകയാണെങ്കിൽ ഞാനയാളുടെ കഴുത്തറുക്കാം. അബൂബക്കർ (റ) ചോദിച്ചു: നിങ്ങളത് ചെയ്യുമോ? ഞാൻ പറഞ്ഞു: അതെ. അബൂബർസ(റ) പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, ഞാൻ പറഞ്ഞ വാക്കിന്റെ കാഠിന്യം അബൂബക്കർ(റ)വിന്റെ ദേഷ്യം ശമിപ്പിച്ചു. പിന്നെ അബൂബക്കർ(റ) പറഞ്ഞു: മുഹമ്മദ് നബി(സ)ക്ക് ശേഷം അതാർക്കും പറ്റുകയില്ല. (ന)', 'أَبِي بَرْزَةَ', 'അബൂബുർസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 555, 555, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ صَفْوَانَ بْنِ عَسَّالٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ يَهُودِيٌّ لِصَاحِبِهِ: اذْهَبْ بِنَا إِلَى هَذَا النَّبِيِّ. قَالَ لَهُ صَاحِبُهُ: لَا تَقُلْ نَبِيٌّ، لَوْ سَمِعَكَ كَانَ لَهُ أَرْبَعَةُ أَعْيُنٍ. فَأَتَيَا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَسَأَلَاهُ عَنْ تِسْعِ آيَاتٍ بَيِّنَاتٍ، فَقَالَ لَهُمْ: "لَا تُشْرِكُوا بِاللهِ شَيْئًا، وَلَا تَسْرِقُوا، وَلَا تَزْنُوا وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللهُ إِلَّا بِالْحَقِّ، وَلَا تَمْشُوا بِبَرِيءٍ إِلَى ذِي سُلْطَانٍ، وَلَا تَسْحَرُوا، وَلَا تَأْكُلُوا الرِّبَا، وَلَا تَقْذِفُوا الْمُحْصَنَةَ، وَلَا تُوَلُّوا يَوْمَ الزَّحْفِ، وَعَلَيْكُمْ خَاصَّةً يَهُودُ: أَنْ لَا تَعْدُوا فِي السَّبْتِ". فَقَبَّلُوا يَدَيْهِ وَرِجْلَيْهِ وَقَالُوا: نَشْهَدُ أَنَّكَ نَبِيٌّ. قَالَ: "فَمَا يَمْنَعُكُمْ أَنْ تَتَّبِعُونِي". قَالُوا: إِنَّ دَاوُدَ دَعَا بِأَنْ لَا يَزَالَ مِنْ ذُرِّيَّتِهِ نَبِيٌّ، وَإِنَّا نَخَافُ إِنِ اتَّبَعْنَاكَ أَنْ تَقْتُلَنَا يَهُودُ. (ن)', 'സ്വഫ്വാനുബ്നു അസ്സ്വാൽ(റ): ഒരു ജൂതൻ തന്റെ കൂട്ടുകാരനോട് പറഞ്ഞു: ഞങ്ങളെ ഈ നബിയുടെ അടുത്തേക്ക് കൊണ്ടുപോകുക. കൂട്ടുകാരൻ പറഞ്ഞു: നബിയെന്ന് നിങ്ങൾ പറയരുത്. നബി(സ) നീ പറയുന്നത് കേൾക്കുകയാണെങ്കിൽ അദ്ദേഹത്തിന് നാല് കണ്ണുകളുണ്ടാകും. അവർ രണ്ടുപേരും റസൂൽ(സ)യുടെ അടുത്തേക്ക് പോയി. നബി(സ)യോട് വ്യക്തമായ ഒമ്പത് ദൃഷ്ടാന്തങ്ങളെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ നബി(സ) അവരോട് പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിൽ ഒന്നും പങ്കുചേർക്കരുത്, മോഷ്ടിക്കരുത്, വ്യഭിചരിക്കരുത്, അല്ലാഹു നിഷിദ്ധമാക്കിയ ഒരു ശരീരത്തെ അനർഹമായി വധിക്കരുത്, നിരപരാധിയെ ഭരണകർത്താവിലേക്ക് കൊണ്ടുപോകരുത്, ആഭിചാരം ചെയ്യരുത്, പലിശ ഭുജിക്കരുത്, പതിവ്രതക്കെതിരെ വ്യഭിചാരാരോപണം നടത്തരുത്, യുദ്ധദിവസം പിന്തിരിയരുത്. ജൂതരോട് പ്രത്യേകിച്ച് നിങ്ങൾ ശനിയാഴ്ച അതിക്രമം കാണിക്കരുത്." അവർ നബി(സ)യുടെ കൈകാലുകൾ ചുംബിച്ചു. എന്നിട്ടവർ പറഞ്ഞു: താങ്കൾ നബിയാണെന്ന് ഞങ്ങൾ സാക്ഷ്യം വഹിക്കുന്നു. നബി(സ) ചോദിച്ചു: "എന്നെ പിൻപറ്റാൻ നിങ്ങളെ തടയുന്നതെന്താണ്?" അവർ പറഞ്ഞു: ദാവൂദ് നബി(അ) തന്റെ കുടുംബത്തിൽ പ്രവാചകൻ ഉണ്ടായിക്കൊണ്ടിരിക്കാൻ പ്രാർത്ഥിച്ചിട്ടുണ്ട്. അങ്ങയെ പിൻപറ്റിയാൽ ഞങ്ങളെ ജൂതർ വധിക്കുമെന്ന് ഞങ്ങൾ ഭയക്കുന്നു. (ന)', 'صَفْوَانَ بْنِ عَسَّالٍ', 'സ്വഫ്വാനുബ്നു അസ്സ്വാൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 555, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ: سَحَرَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ مِنَ الْيَهُودِ، فَاشْتَكَى لِذَلِكَ أَيَّامًا، فَأَتَاهُ جِبْرِيلُ عَلَيْهِ السَّلَامُ فَقَالَ: إِنَّ رَجُلًا مِنَ الْيَهُودِ سَحَرَكَ، عَقَدَ لَكَ عُقَدًا فِي بِئْرِ كَذَا وَكَذَا. فَأَرْسَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاسْتَخْرَجُوهَا، فَجِيءَ بِهَا، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَأَنَّمَا نُشِطَ مِنْ عِقَالٍ، فَمَا ذَكَرَ ذَلِكَ لِذَلِكَ الْيَهُودِيِّ وَلَا رَآهُ فِي وَجْهِهِ قَطُّ. (ن)', 'സൈദുബ്നു അർഖം(റ): നബി(സ)യെ ഒരു ജൂതൻ കൂടോത്രം ചെയ്തു. ഇതുകാരണം നബി(സ) ദിവസങ്ങളോളം അസ്വസ്ഥനായി. അപ്പോൾ നബി(സ)യുടെ അടുത്തേക്ക് ജിബ്രീൽ(അ) വന്നുകൊണ്ട് പറഞ്ഞു: അങ്ങയെ ഒരു ജൂതൻ കൂടോത്രം ചെയ്തിരിക്കുന്നു. ഇന്നാലിന്ന കിണറ്റിൽ അങ്ങേക്ക് വേണ്ടി കെട്ടുകെട്ടിയിരിക്കുന്നു. റസൂൽ(സ) ആളെ അയച്ചു. അവർ അത് പുറത്തെടുത്തു കൊണ്ടുവന്നു. അപ്പോൾ തിരുമേനി(സ) എണീറ്റു. നബി(സ) കെട്ടുകളിൽ നിന്ന് ഉണർന്നതുപോലെ. തിരുമേനി(സ) ഒരിക്കലും ഇക്കാര്യം ആ ജൂതനെ അറിയിക്കുകയോ തങ്ങളുടെ മുഖത്ത് പ്രകടമാക്കുകയോ ചെയ്തില്ല. (ന)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ عَقَدَ عُقْدَةً ثُمَّ نَفَثَ فِيهَا فَقَدْ سَحَرَ، وَمَنْ سَحَرَ فَقَدْ أَشْرَكَ، وَمَنْ تَعَلَّقَ شَيْئًا وُكِلَ إِلَيْهِ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "ആരെങ്കിലും കെട്ടുകെട്ടി അതിൽ ഊതിയാൽ അവൻ കൂടോത്രം ചെയ്തിരിക്കുന്നു. ആരെങ്കിലും കൂടോത്രം ചെയ്താൽ അവൻ ബഹുദൈവാരാധന ചെയ്തിരിക്കുന്നു. ആരങ്കിലും വല്ലതും ബന്ധിപ്പിച്ചാൽ അവൻ അതിലേക്ക് ഏൽപിക്കപ്പെടുന്നതാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ جَعَلَ الدِّيَةَ اثْنَيْ عَشَرَ أَلْفًا. (د,ت,ن,جه)', 'ഇബ്നു അബ്ബാസ്(റ): നബി(സ) നഷ്ടപരിഹാരം പന്ത്രണ്ടായിരം (ദിർഹം) ആക്കി നിശ്ചയിച്ചിരിക്കുന്നു. (ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 556, 556, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ جَعَلَ الدِّيَةَ اثْنَيْ عَشَرَ أَلْفًا. قَالَ: وَذَلِكَ قَوْلُهُ {وَمَا نَقَمُوا إِلَّا أَنْ أَغْنَاهُمُ اللهُ وَرَسُولُهُ مِنْ فَضْلِهِ} [التوبة: ٧٤] قَالَ: بِأَخْذِهِمُ الدِّيَةَ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) നഷ്ടപരിഹാരം പന്ത്രണ്ടായിരം (ദിർഹം) ആക്കി നിശ്ചയിച്ചു. അദ്ദേഹം പറഞ്ഞു: അത് അല്ലാഹുവിന്റെ വാക്കാകുന്നു: ''അല്ലാഹുവിന്റെ അനുഗ്രഹത്താൽ അവനും അവന്റെ ദൂതനും അവർക്ക് ഐശ്വര്യമുണ്ടാക്കിക്കൊടുത്തു എന്നതൊഴിച്ച് അവരുടെ എതിർപ്പിന് ഒരു കാരണവുമില്ല.'' (തൗബ: 74) ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: നഷ്ടപരിഹാരം സ്വീകരിക്കൽ കൊണ്ട് (അവർ ഐശ്വര്യമുള്ളവരായി). (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'التوبة: ٧٤', null, 556, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ سُرَاقَةَ بْنِ مَالِكِ بْنِ جُعْشُمٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَضَرْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُقِيدُ الْأَبَ مِنِ ابْنِهِ وَلَا يُقِيدُ الْإِبْنَ مِنْ أَبِيهِ. (ت)', 'സുറാഖതുബ്നു മാലിക്(റ): പിതാവിനെ കൊന്നതിന് മകനെ റസൂൽ(സ) കൊല്ലുന്നതിനും മകനെ വധിച്ചതിന് പിതാവിനെ വധിക്കാത്തതിനും ഞാൻ സാക്ഷിയായി (തു)', 'سُرَاقَةَ بْنِ مَالِكِ بْنِ جُعْشُمٍ', 'സുറാഖതുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُقَامُ الْحُدُودُ فِي الْمَسَاجِدِ، وَلَا يُقْتَلُ الْوَالِدُ بِالْوَلَدِ". (ت,جه)', 'ഇബ്നു അബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "പള്ളികളിൽ വെച്ച് ശിക്ഷ നടപ്പാക്കപ്പെടുകയില്ല, മകനെ കൊന്നതിന് പകരമായി പിതാവ് കൊല്ലപ്പെടുകയുമില്ല." (തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَدَى الْعَامِرِيَّيْنِ بِدِيَةِ الْمُسْلِمِينَ، وَكَانَ لَهُمَا عَهْدٌ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): ആമിരി ഗോത്രത്തിൽപെട്ട രണ്ടാളുകൾക്ക് മുസ്ലിംകൾക്കുള്ള അതേ നഷ്ടപരിഹാരം നൽകണമെന്ന് നബി(സ) വിധിച്ചു. അവർ രണ്ടുപേരും നബി(സ)യുമായി കരാറിലേർപ്പെട്ടിരുന്നു. (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا فَتَحَ اللهُ عَلَى رَسُولِهِ مَكَّةَ قَامَ فِي النَّاسِ فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ: "وَمَنْ قُتِلَ لَهُ قَتِيلٌ فَهُوَ بِخَيْرِ النَّظَرَيْنِ إِمَّا أَنْ يَعْفُوَ وَإِمَّا أَنْ يَقْتُلَ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)ക്ക് അല്ലാഹു മക്കയെ കീഴ്പ്പെടുത്തിക്കൊടുത്തപ്പോൾ അവിടന്ന് ജനങ്ങൾക്കിടയിൽ എഴുന്നേറ്റുനിന്ന് അല്ലാഹുവിനെ സ്തുതിച്ചു, അവനെ പുകഴ്ത്തി, എന്നിട്ട് പറഞ്ഞു: "ആരെങ്കിലും കൊല്ലപ്പെട്ടാൽ (അവന്റെ കുടുംബത്തിന്) രണ്ടാലൊന്ന് തിരഞ്ഞെടുക്കാം: ഒന്നുകിൽ മാപ്പ് നൽകാം; അല്ലെങ്കിൽ പകരമായി ഘാതകനെ കൊല്ലാം." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 557, 557, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أَبِي شُرَيْحٍ الْكَعْبِيِّ رَضِيَ اللهُ عَنْهُ، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ حَرَّمَ مَكَّةَ وَلَمْ يُحَرِّمْهَا النَّاسُ، مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يَسْفِكَنَّ فِيهَا دَمًا وَلَا يَعْضِدَنَّ فِيهَا شَجَرًا، فَإِنْ تَرَخَّصَ مُتَرَخِّصٌ فَقَالَ: أُحِلَّتْ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَإِنَّ اللهَ أَحَلَّهَا لِي وَلَمْ يُحِلَّهَا لِلنَّاسِ، وَإِنَّمَا أُحِلَّتْ لِي سَاعَةً مِنْ نَهَارٍ، ثُمَّ هِيَ حَرَامٌ إِلَى يَوْمِ الْقِيَامَةِ، ثُمَّ إِنَّكُمْ مَعْشَرَ خُزَاعَةَ قَتَلْتُمْ هَذَا الرَّجُلَ مِنْ هُذَيْلٍ، وَإِنِّي عَاقِلُهُ، فَمَنْ قُتِلَ لَهُ قَتِيلٌ بَعْدَ الْيَوْمِ فَأَهْلُهُ بَيْنَ خِيرَتَيْنِ إِمَّا أَنْ يَقْتُلُوا أَوْ يَأْخُذُوا الْعَقْلَ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'അബൂശുറൈഹിൽ കഅ്ബി(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു മക്കയെ പവിത്രമാക്കി, ജനങ്ങളല്ല അതിനെ പവിത്രമാക്കിയത്. ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യനാളിലും വിശ്വസിക്കുന്നുവെങ്കിൽ മക്കയിൽ രക്തം ചിന്തുകയോ മരം മുറിക്കുകയോ ചെയ്യരുത്, ആരെങ്കിലും അതിൽ ഇളവ് സ്വീകരിക്കുകയും ''റസൂൽ(സ)ക്ക് അത് അനുവദനീയമാക്കപ്പെട്ടിട്ടുണ്ടല്ലോ'' എന്ന് പറയുകയും ചെയ്യുന്നുവെങ്കിൽ, അല്ലാഹു എനിക്ക് മാത്രമാണത് അനുവദനീയമാക്കിയത്. ജനങ്ങൾക്കത് അനുവദനീയമാക്കിയിട്ടില്ല. പകലിലെ ഒരു നേരം മാത്രമാണ് എനിക്കിത് അനുവദിക്കപ്പെട്ടത്. ഇനി അന്ത്യനാൾ വരെ അത് നിഷിദ്ധമാണ്. പിന്നെ നിങ്ങൾ ഖുസാഅ ഗോത്രക്കാർ ഹുദൈലിൽ നിന്നുള്ള ഒരാളെ വധിച്ചിരിക്കുന്നു. ഞാനതിന് നഷ്ട പരിഹാരം നൽകും. ഇന്നത്തെ ദിവസത്തിന് ശേഷം ആരെങ്കിലും കൊല്ലപ്പെട്ടാൽ അവന്റെ കുടുംബക്കാർക്ക് ഇഷ്ടാനുസരണം ചെയ്യാം: ഒന്നുകിൽ ഘാതകനെ വധിക്കാം, അല്ലെങ്കിൽ നഷ്ടപരിഹാരം സ്വീകരിക്കാം." (ദ,തു,ന)', 'أَبِي شُرَيْحٍ الْكَعْبِيِّ', 'അബൂശുറൈഹിൽ കഅ്ബി(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 557, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ، أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ كَتَبَ الْإِحْسَانَ عَلَى كُلِّ شَيْءٍ، فَإِذَا قَتَلْتُمْ فَأَحْسِنُوا الْقِتْلَةَ، وَإِذَا ذَبَحْتُمْ فَأَحْسِنُوا الذِّبْحَةَ، وَلْيُحِدَّ أَحَدُكُمْ شَفْرَتَهُ وَلْيُرِحْ ذَبِيحَتَهُ". حسن صحيح. (م,ت,ن,جه)', 'ശദ്ദാദുബ്നു ഔസ്(റ): നബി(സ) പറഞ്ഞു: "എല്ലാ കാര്യവും ഭംഗിയായി ചെയ്യണമെന്ന് അല്ലാഹു കൽപിക്കുന്നു. അതുകൊണ്ട് കൊല ചെയ്യുമ്പോൾ നിങ്ങൾ ഭംഗിയായി വധിക്കുക. നിങ്ങൾ അറുക്കുമ്പോൾ ഭംഗിയായി അറുക്കുക. നിങ്ങൾ ഓരോരുത്തരും തന്റെ കത്തിയുടെ തല മൂർച്ചകൂട്ടട്ടെ, അറുക്കപ്പെടുന്ന മൃഗത്തിന് ആശ്വാസം കിട്ടാൻവേണ്ടി." (മു,തു,ന,ജ)', 'شَدَّادِ بْنِ أَوْسٍ', 'ശദ്ദാദുബ്നു ഔസ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ أَنَّهُ كَانَ يَقُولُ: الدِّيَةُ عَلَى الْعَاقِلَةِ، وَلَا تَرِثُ الْمَرْأَةُ مِنْ دِيَةِ زَوْجِهَا شَيْئًا، حَتَّى أَخْبَرَهُ الضَّحَّاكُ بْنُ سُفْيَانَ الْكِلَابِيُّ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَتَبَ إِلَيْهِ: أَنْ وَرِّثْ امْرَأَةَ أَشْيَمَ الضِّبَابِيِّ مِنْ دِيَةِ زَوْجِهَا. حسن صحيح. (د,ت,ن,جه)', 'ഉമർ(റ): ''അശ്യമുള്ളബ്വാബിയുടെ നഷ്ടപരിഹാരത്തിൽ നിന്ന് അദ്ദേഹത്തിന്റ ഭാര്യക്കും നൽകണം'' എന്ന് റസൂൽ(സ) എനിക്ക് കത്തെഴുതിയിരുന്നു എന്ന് ളഹ്ഹാകുബ്നു സുഫ്യാനുൽ കിലാബി(റ) ഉമർ(റ)വിനെ അറിയിക്കുന്നതുവരെ, നഷ്ടപരിഹാരം നൽകേണ്ടത് പിതാവ് വഴിക്കുള്ള അടുത്ത കുടുംബക്കാരാണെന്നും ഭർത്താവിനുള്ള നഷ്ടപരിഹാരത്തിൽ നിന്ന് ഭാര്യക്ക് ഒന്നും ലഭിക്കില്ല എന്നുമായിരുന്നു ഉമർ(റ) പറഞ്ഞിരുന്നത്. (ദ,തു,ന,ജ)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أُتِيَ عِنْدَ مَالِهِ، فَقُوتِلَ، فَقَاتَلَ فَقُتِلَ، فَهُوَ شَهِيدٌ". [ز: فِي إِسْنَادِهِ ضَعِيفٌ] (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "തന്റെ സമ്പത്തിനരികെ മറ്റുള്ളവർ വരികയും അങ്ങനെ ആക്രമിക്കപ്പെടുകയും തിരിച്ചാക്രമിക്കുകയും തുടർന്ന് കൊല്ലപ്പെടുകയും ചെയ്ത വ്യക്തി രക്തസാക്ഷിയാണ്." പരമ്പരയിൽ ബലഹീനനുണ്ട് (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ ضَعِيفٌ', null, 558, 558, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ سَعِيدِ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ، وَمَنْ سَرَقَ مِنَ الْأَرْضِ شِبْرًا طُوِّقَهُ يَوْمَ الْقِيَامَةِ مِنْ سَبْعِ أَرَضِينَ". وَفِي رِوَايَةٍ: "مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ دِينِهِ فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ دَمِهِ فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ أَهْلِهِ فَهُوَ شَهِيدٌ". حسن صحيح. (د,ت,ن,جه)', 'സഈദുബ്നു സൈദ്(റ): നബി(സ) പറഞ്ഞു: "തന്റെ സമ്പത്ത് സംരക്ഷിക്കാനുള്ള പോരാട്ടത്തിൽ വധിക്കപ്പെട്ടവൻ രക്തസാക്ഷിയാണ്. ആരെങ്കിലും ഒരു ചാൺ ഭൂമി മോഷ്ടിച്ചാൽ വിധിനാളിൽ അവന്റെ കഴുത്തിൽ ഏഴ് ഭൂമിയുടെ മാല അണിയിക്കും." മറ്റൊരു നിവേദനം: "തന്റെ സമ്പത്ത് സംരക്ഷിക്കാനുള്ള പോരാട്ടത്തിൽ കൊല്ലപ്പെട്ടവൻ രക്തസാക്ഷിയാണ്. തന്റെ ദീനിനു വേണ്ടിയുള്ള പോരാട്ടത്തിൽ വധിക്കപ്പെട്ടവനും രക്തസാക്ഷിയാണ്. തന്റെ രക്തം സംരക്ഷിക്കാനുള്ള പോരാട്ടത്തിൽ മരിച്ചവനും രക്തസാക്ഷിയാണ്. തന്റെ കുടുംബം സംരക്ഷിക്കാനുള്ള പോരാട്ടത്തിൽ വധിക്കപ്പെട്ടവനും രക്തസാക്ഷിയാണ്." (ദ,തു,ന,ജ)', 'سَعِيدِ بْنِ زَيْدٍ', 'സഈദുബ്നു സൈദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 558, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=90), 1, 'وَفِي رِوَايَةٍ: "مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ دِينِهِ فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ دَمِهِ فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ أَهْلِهِ فَهُوَ شَهِيدٌ". حسن صحيح. (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: "തന്റെ സമ്പത്ത് സംരക്ഷിക്കാനുള്ള പോരാട്ടത്തിൽ കൊല്ലപ്പെട്ടവൻ രക്തസാക്ഷിയാണ്. തന്റെ ദീനിനു വേണ്ടിയുള്ള പോരാട്ടത്തിൽ വധിക്കപ്പെട്ടവനും രക്തസാക്ഷിയാണ്. തന്റെ രക്തം സംരക്ഷിക്കാനുള്ള പോരാട്ടത്തിൽ മരിച്ചവനും രക്തസാക്ഷിയാണ്. തന്റെ കുടുംബം സംരക്ഷിക്കാനുള്ള പോരാട്ടത്തിൽ വധിക്കപ്പെട്ടവനും രക്തസാക്ഷിയാണ്." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَتِيلُ الْخَطَإِ شِبْهُ الْعَمْدِ قَتِيلُ السَّوْطِ وَالْعَصَا، مِائَةٌ مِنَ الْإِبِلِ: أَرْبَعُونَ مِنْهَا خَلِفَةً فِي بُطُونِهَا أَوْلَادُهَا". (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "കരുതിക്കൂട്ടി ചെയ്ത കൊലയോട് സാമ്യതയുള്ള അവിചാരിത കൊല, വടി കൊണ്ടും ചാട്ട കൊണ്ടുമുള്ള കൊലയാണ്. (അതിനുള്ള നഷ്ടപരിഹാരം) നൂറ് ഒട്ടകമാണ്. അതിൽ നാൽപ്പതെണ്ണം വയറ്റിൽ കുട്ടിയുള്ള ഒട്ടകമായിരിക്കണം." (ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ – يَوْمَ فَتْحِ مَكَّةَ – وَهُوَ عَلَى دَرَجِ الْكَعْبَةِ، فَحَمِدَ اللهَ وَأَثْنَى عَلَيْهِ، فَقَالَ: "الْحَمْدُ لِلَّهِ الَّذِي صَدَقَ وَعْدَهُ وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ، أَلَا إِنَّ قَتِيلَ الْخَطَإِ قَتِيلَ السَّوْطِ وَالْعَصَا: فِيهِ مِائَةٌ مِنَ الْإِبِلِ، مِنْهَا أَرْبَعُونَ خَلِفَةً فِي بُطُونِهَا أَوْلَادُهَا. أَلَا إِنَّ كُلَّ مَأْثُرَةٍ كَانَتْ فِي الْجَاهِلِيَّةِ وَدَمٍ تَحْتَ قَدَمَيَّ هَاتَيْنِ، إِلَّا مَا كَانَ مِنْ سِدَانَةِ الْبَيْتِ وَسِقَايَةِ الْحَاجِّ، أَلَا إِنِّي قَدْ أَمْضَيْتُهُمَا لِأَهْلِهِمَا كَمَا كَانَا". (د,ن,جه)', 'ഇബ്നുഉമർ(റ): മക്കാവിജയദിനത്തിൽ കഅ്ബയുടെ പടിയിൽ നിൽക്കെ റസൂൽ(സ) ജനങ്ങളെ അഭിസംബോധനം ചെയ്തു. അല്ലാഹുവിനെ സതുതിച്ചു, അവനെ വാഴ്ത്തി. എന്നിട്ട് പറഞ്ഞു: "തന്റെ വാഗദാനം സത്യമാക്കിയ, തന്റെ ദാസനെ സഹായിച്ച, തനിച്ച് ശത്രുസൈന്യത്തെ പരാജയപ്പെടുത്തിയ, അല്ലാഹുവിന് സ്തുതി. അറിയുക, അവിചാരിതമായി കൊലചെയ്യപ്പെട്ടവൻ ചാട്ടകൊണ്ടും വടികൊണ്ടും കൊലചെയ്യപ്പെട്ടവനാണ്. (അതിനുള്ള നഷ്ടപരിഹാരം) നൂറ് ഒട്ടകമാണ്. നാൽപ്പതെണ്ണം വയറ്റിൽ കുട്ടിയയുള്ള ഒട്ടകമായിരിക്കണം. അറിയുക, ജാഹിലിയ്യാകാലത്തെ നടപടിക്രമങ്ങളും രക്തവും എന്റെ ഈ കാലിനിടയിലാണ്, (ഇസ്ലാമിൽ അതിന് പ്രസക്തിയില്ല) കഅ്ബയുടെ പരിപാലനവും ഹാജിമാർക്ക് വെള്ളം കുടിപ്പിക്കലുമൊഴികെ. അറിയുക, അവരണ്ടും ഇപ്പോഴുള്ളത് പോലെ അതിന്റെ അവകാശികൾക്ക് നൽകുന്നു." (ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 559, 559, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ طَاوُوسٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قُتِلَ فِي عِمِّيَّا فِي رَمْيٍ يَكُونُ بَيْنَهُمْ – بِحِجَارَةٍ أَوْ بِالسِّيَاطِ أَوْ ضَرْبٍ بِعَصًا – فَهُوَ خَطَأٌ، وَعَقْلُهُ عَقْلُ الْخَطَإِ وَمَنْ قُتِلَ عَمْدًا فَهُوَ قَوَدٌ – وَفِي رِوَايَةٍ: قَوَدُ يَدٍ – وَمَنْ حَالَ دُونَهُ فَعَلَيْهِ لَعْنَةُ اللهِ وَغَضَبُهُ، لَا يُقْبَلُ مِنْهُ صَرْفٌ وَلَا عَدْلٌ". (د,ن,جه)', 'ത്വാഊസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അമ്പെയ്ത്തിൽ അശ്രദ്ധ മൂലം ഒരുത്തൻ കൊല്ലപ്പെട്ടാൽ - കല്ലിനാലോ ചാട്ടയാലോ അല്ലെങ്കിൽ വടി കൊണ്ട് അടിക്കൽ കാരണത്താലോ കൊല്ലപ്പെട്ടാൽ - അത് പിഴവ് ആണ്. അതിന്റെ നഷ്ടപരിഹാരം പിഴവിന്റെ നഷ്ടപരിഹാരമാണ്. ഒരുത്തൻ മനഃപൂർവ്വം കൊലചെയ്യപ്പെട്ടാൽ അതിനുള്ളത് ഖിസാസാണ്. - മറ്റൊരു നിവേദനത്തിൽ: അതിന്റെ ഖിസാസ് കൈകൊണ്ടുള്ള ഖിസാസാണ് - ആരെങ്കിലും അതിനിടയിൽ മറയിട്ടാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും ശാപമുണ്ട്. അവന്റെ ഫർളോ സുന്നത്തോ സ്വീകരിക്കപ്പെടുന്നതല്ല." (ദ,ന,ജ)', 'طَاوُوسٍ قَالَ', 'ത്വാഊസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 559, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=93), 1, 'وَفِي رِوَايَةٍ: قَوَدُ يَدٍ – وَمَنْ حَالَ دُونَهُ فَعَلَيْهِ لَعْنَةُ اللهِ وَغَضَبُهُ، لَا يُقْبَلُ مِنْهُ صَرْفٌ وَلَا عَدْلٌ". (د,ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: അതിന്റെ ഖിസാസ് കൈകൊണ്ടുള്ള ഖിസാസാണ് - ആരെങ്കിലും അതിനിടയിൽ മറയിട്ടാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെയും അവന്റെ റസൂലിന്റെയും ശാപമുണ്ട്. അവന്റെ ഫർളോ സുന്നത്തോ സ്വീകരിക്കപ്പെടുന്നതല്ല." (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنِ الْمِقْدَامِ أَبِي كَرِيمَةَ الشَّامِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنَا وَارِثُ مَنْ لَا وَارِثَ لَهُ: أَعْقِلُ عَنْهُ وَأَرِثُهُ. وَالْخَالُ وَارِثُ مَنْ لَا وَارِثَ لَهُ يَعْقِلُ عَنْهُ وَيَرِثُهُ". (د,جه)', 'മിഖ്ദാം അബൂകരീമതുശ്ശാമി(റ): റസൂൽ(സ) പറഞ്ഞു: "അനന്തരാവകാശികൾ ഇല്ലാത്തവരുടെ അനന്തരാവകാശി ഞാനാണ്. അവന് വേണ്ടി നഷ്ടപരിഹാരം ഞാൻ നൽകും, അവന്റെ അനന്തരം ഞാനെടുക്കുകയും ചെയ്യും. അതുപോലെ അമ്മാവൻ അനന്തരാവകാശി ഇല്ലാത്തവരുടെ അനന്തരാവകാശിയാണ്. അവന് വേണ്ടി നഷ്ടപരിഹാരം നൽകുകയും അവന്റെ അനന്തരമെടുക്കുകയും ചെയ്യും." (ദ,ജ)', 'الْمِقْدَامِ أَبِي كَرِيمَةَ الشَّامِيِّ', 'മിഖ്ദാം അബൂകരീമതുശ്ശാമി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا – رَفَعَهُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – قَالَ: "مَنْ قَتَلَ فِي عِمِّيَّةٍ أَوْ عَصَبِيَّةٍ، بِحَجَرٍ أَوْ سَوْطٍ أَوْ عَصًا، فَعَلَيْهِ عَقْلُ الْخَطَإِ. وَمَنْ قَتَلَ عَمْدًا فَهُوَ قَوَدٌ. وَمَنْ حَالَ بَيْنَهُ وَبَيْنَهُ فَعَلَيْهِ لَعْنَةُ اللهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ، لَا يُقْبَلُ مِنْهُ صَرْفٌ وَلَا عَدْلٌ". (د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "കുടുംബത്തെ സംരക്ഷിക്കാനോ, സത്യത്തിനാണോ അസത്യത്തിനാണോ എന്ന് വ്യക്തമല്ലാത്ത നിലയിലോ ഒരാൾ വടി, ചാട്ട, കല്ല് എന്നിവകൊണ്ട് ഒരാളെ കൊന്നാൽ, അവിചാരിത കൊലക്കുള്ള നഷ്ടപരിഹാരം അവന്റെ മേൽ നിർബന്ധമാണ്. മനഃപൂർവ്വം കൊല ചെയ്തവൻ പ്രതിക്രിയ ചെയ്യപ്പെടും. ഘാതകനും പ്രതിക്രിയക്കുമിടയിൽ ആരെങ്കിലും തടസ്സം നിന്നാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെയും മാലാഖമാരുടെയും എല്ലാ ജനങ്ങളുടെയും ശാപമുണ്ടാകും. അവന്റെ ഫർളോ സുന്നത്തോ സ്വീകരിക്കപ്പെടുന്നതല്ല." (ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 560, 560, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ جَارِيَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا ضَرَبَ رَجُلًا عَلَى سَاعِدِهِ بِالسَّيْفِ، فَقَطَعَهَا مِنْ غَيْرِ مَفْصِلٍ. فَاسْتَعْدَى عَلَيْهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَمَرَ لَهُ بِالدِّيَةِ. فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي أُرِيدُ الْقِصَاصَ. قَالَ: "خُذِ الدِّيَةَ، بَارَكَ اللهُ لَكَ فِيهَا". وَلَمْ يَقْضِ لَهُ بِالْقِصَاصِ. [ز: في إسناده ضعيف] (جه)', 'ജാരിയ(റ): ഒരാൾ മറ്റൊരാളുടെ കണങ്കയ്യിൽ വാളുകൊണ്ട് വെട്ടി. കെണിപ്പല്ലാത്ത ഒരു ഭാഗം മുറിഞ്ഞു. മുറിക്കപ്പെട്ടവൻ തിരുമേനി(സ)യുടെ അടുത്ത് പരാതിയുമായി ചെന്നു. നബി(സ) അയാൾക്ക് നഷ്ടപരിഹാരം നൽകാൻ കൽപിച്ചു. അപ്പോൾ അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, പ്രതികാരം ചെയ്യണമെന്ന് ഞാൻ ഉദ്ദേശിക്കുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നഷ്ടപരിഹാരം സ്വീകരിക്കൂ. അല്ലാഹു അതിൽ നിങ്ങൾക്ക് ബറകത് ചെയ്യട്ടെ." നബി(സ) അയാൾക്ക് പ്രതിക്രിയ വിധിച്ചില്ല. ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഭംഗമുള്ള നിവേദകനുണ്ട്. (ജ)', 'جَارِيَةَ', 'ജാരിയ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 560, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا قَوَدَ فِي الْمَأْمُومَةِ وَلَا الْجَائِفَةِ وَلَا الْمُنَقِّلَةِ". [ز: في إسناده ضعيف] (جه)', 'അബ്ബാസുബ്നു അബ്ദുൽമുത്ത്വലിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "തലച്ചോറിലെത്താത്ത മുറിവിനും, വയറ്റിനുള്ളിലെത്താത്ത കുത്തിനും എല്ലിന് സ്ഥാനചലനമുണ്ടാകാത്ത മുറിവിനും പ്രതിക്രിയയില്ല." ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഭംഗമുള്ള നിവേദകനുണ്ട്. (ജ)', 'الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ', 'അബ്ബാസുബ്നു അബ്ദുൽമുത്ത്വലിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى لِحَمَلِ بْنِ مَالِكٍ الْهُذَلِيِّ اللِّحْيَانِيِّ بِمِيرَاثِهِ مِنِ امْرَأَتِهِ الَّتِي قَتَلَتْهَا امْرَأَتُهُ الْأُخْرَى. (جه)', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ): ഹമലുബ്നു മാലികുൽ ഹുദലി(റ)വിന് തന്റെ ഒരു ഭാര്യ കൊന്ന മറ്റൊരു ഭാര്യക്കുള്ള നഷ്ടപരിഹാരത്തിൽ നിന്ന് അനന്തരമെടുക്കാമെന്ന് നബി(സ) വിധിച്ചു. (ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദത്തുബ്നു സ്വാമിത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى: أَنَّ عَقْلَ أَهْلِ الْكِتَابَيْنِ نِصْفُ عَقْلِ الْمُسْلِمِينَ، وَهُمُ الْيَهُودُ وَالنَّصَارَى. (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): രണ്ട് വേദക്കാരുടേയും നഷ്ടപരിഹാരം മുസ്ലിമിന്റെ നഷ്ടപരിഹാരത്തിന്റെ പകുതിയാണെന്ന് റസൂൽ(സ) വിധിച്ചു. വേദക്കാർ ജൂതരും ക്രൈസതവരുമാണ്. (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْقَاتِلُ لَا يَرِثُ". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "കൊലയാളി അനന്തരമെടുക്കില്ല." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ عَمْرِو بْنِ شُعَيْبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أَبَا قَتَادَةَ – رَجُلٌ مِنْ بَنِي مُدْلِجٍ – قَتَلَ ابْنَهُ، فَأَخَذَ مِنْهُ عُمَرُ مِائَةً مِنَ الْإِبِلِ: ثَلَاثِينَ حِقَّةً، وَثَلَاثِينَ جَذَعَةً، وَأَرْبَعِينَ خَلِفَةً. فَقَالَ: أَيْنَ أَخُو الْمَقْتُولِ؟ سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَيْسَ لِقَاتِلٍ مِيرَاثٌ". (جه)', 'അംറുബ്നു ശുഐബ്(റ): മുദ്ലിജ് ഗോത്രക്കാരനായ അബൂഖതാദ തന്റെ മകനെ കൊന്നു. അദ്ദേഹത്തിൽ നിന്ന് (നഷ്ടപരിഹാരമായി) ഉമർ(റ) നൂറ് ഒട്ടകം എടുത്തു, അതിൽ മുപ്പതെണ്ണം മൂന്ന് വയസ്സുള്ള ഒട്ടകങ്ങളും മുപ്പതെണ്ണം നാല് വയസ്സുള്ള ഒട്ടകങ്ങളും, നാൽപ്പതെണ്ണം ഗർഭമുള്ള ഒട്ടകങ്ങളുമായിരുന്നു. എന്നിട്ട് ഉമർ(റ) ചോദിച്ചു: കൊല്ലപ്പെട്ടവന്റെ സഹോദരൻ എവിടെ? "ഘാതകന് അനന്തരമില്ല" എന്ന് തിരുദൂതർ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. (ജ)', 'عَمْرِو بْنِ شُعَيْبٍ', 'അംറുബ്നു ശുഐബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 561, 561, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَعْقِلَ الْمَرْأَةَ عَصَبَتُهَا مَنْ كَانُوا، وَلَا يَرِثُوا مِنْهَا شَيْئًا إِلَّا مَا فَضَلَ عَنْ وَرَثَتِهَا، وَإِنْ قُتِلَتْ فَعَقْلُهَا بَيْنَ وَرَثَتِهَا، فَهُمْ يَقْتُلُونَ قَاتِلَهَا. (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): പെണ്ണിന്റെ നഷ്ടപരിഹാരം അവളുടെ കുടുംബക്കാർ നൽകണമെന്ന് നബി(സ) വിധിച്ചു. അവർക്ക് അവളുടെ നഷ്ടപരിഹാരത്തിൽ നിന്ന് ഒന്നും അനന്തരമായി കിട്ടുകയില്ല, അനന്തരസ്വത്തിൽ നിന്ന് അധികമുള്ളതല്ലാതെ. അവൾ കൊല്ലപ്പെട്ടാൽ അവൾക്കുള്ള നഷ്ടപരിഹാരം അവളുടെ അനന്തരാവകാശികൾക്കുള്ളതാണ്. അവരാണ് അവളുടെ ഘാതകനെ വധിക്കേണ്ടത്. (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا، أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا قَوَدَ إِلَّا بِالسَّيْفِ". [ز: في إسناده متّهم بالكذب] (جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): നബി(സ) പറയുന്നു: "വാള് കൊണ്ടുള്ളതിന് മാത്രമേ പ്രതിക്രിയ ഉള്ളൂ." (ഇതിന്റെ പരമ്പരയിൽ കളവ് പറയുന്നതായി സംശയിക്കപ്പെടുന്നയാളുണ്ട്.) (ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده متّهم بالكذب', 'ഇതിന്റെ പരമ്പരയിൽ കളവ് പറയുന്നതായി സംശയിക്കപ്പെടുന്നയാളുണ്ട്.', 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عَمْرِو بْنِ الْأَحْوَصِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي حَجَّةِ الْوَدَاعِ: "أَلَا لَا يَجْنِي جَانٍ إِلَّا عَلَى نَفْسِهِ، لَا يَجْنِي وَالِدٌ عَلَى وَلَدِهِ، وَلَا مَوْلُودٌ عَلَى وَالِدِهِ". (جه)', 'അംറുബ്നുൽ അഹ്വസ്(റ): വിടവാങ്ങൽ ഹജ്ജിന്റെ സമയത്ത് പ്രവാചകർ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "തെറ്റുചെയ്യുന്നവൻ സ്വന്തത്തോട് തന്നെയാണ് തെറ്റ് ചെയ്യുന്നത്. പിതാവ് മകന് ഒരു ദോഷവും വരുത്തുകയില്ല. മകൻ പിതാവിന് ഒരു ദോഷവും വരുത്തുകയില്ല." (ജ)', 'عَمْرِو بْنِ الْأَحْوَصِ', 'അംറുബ്നുൽ അഹ്വസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ طَارِقٍ الْمُحَارِبِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَرْفَعُ يَدَيْهِ، حَتَّى رَأَيْتُ بَيَاضَ إِبْطَيْهِ، يَقُولُ: "أَلَا لَا تَجْنِي أُمٌّ عَلَى وَلَدٍ، أَلَا لَا تَجْنِي أُمٌّ عَلَى وَلَدٍ". (جه)', 'താരിഖുൽ മുഹാരിബി(റ): ഞാൻ റസൂൽ(സ)യുടെ കക്ഷത്തിന്റെ വെളുപ്പ് കാണുംവിധം തിരുമേനി(സ) അവിടുത്തെ തിരുകരം ഉയർത്തി. അവിടന്ന് പറയുന്നുണ്ടായിരുന്നു: "അറിയുക, ഉമ്മയുടെ തെറ്റിന് മകൻ കുറ്റക്കാരനാവുകയില്ല. അറിയുക, ഉമ്മയുടെ തെറ്റിന് മകൻ കുറ്റക്കാരനാവുകയില്ല." (ജ)', 'طَارِقٍ الْمُحَارِبِيِّ', 'താരിഖുൽ മുഹാരിബി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي رِمْثَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَعَ أَبِي فَقَالَ: "مَنْ هَذَا مَعَكَ". قَالَ: ابْنِي أَشْهَدُ بِهِ. قَالَ: "أَمَا إِنَّكَ لَا تَجْنِي عَلَيْهِ وَ لَا يَجْنِي عَلَيْكَ". (ن)', 'അബൂറംസ(റ): എന്റെ പിതാവിന്റെ കൂടെ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു. അവിടന്ന് ചോദിച്ചു: "നിങ്ങളോടപ്പമുള്ളതാരാണ്?" പിതാവ് പറഞ്ഞു: അവൻ എന്റെ മകനാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എന്നാൽ നിന്റെ തെറ്റിന് അവനോ അവന്റെ തെറ്റിന് നീയോ കുറ്റക്കാരനാവുകയില്ല." (ന)', 'أَبِي رِمْثَةَ', 'അബൂറംസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 562, 562, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنِ الْأَسْوَدِ بْنِ هِلَالٍ، وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَنْ ثَعْلَبَةَ بْنِ زَهْدَمٍ الْيَرْبُوعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ فِي أُنَاسٍ مِنَ الْأَنْصَارِ، فَقَالُوا: يَا رَسُولَ اللهِ، هَؤُلَاءِ بَنُو ثَعْلَبَةَ بْنِ يَرْبُوعٍ قَتَلُوا فُلَانًا فِي الْجَاهِلِيَّةِ؟ فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهَتَفَ بِصَوْتِهِ: "أَلَا لَا تَجْنِي نَفْسٌ عَلَى الْأُخْرَى". وَفِي رِوَايَةٍ: قَالَ: انْتَهَى قَوْمٌ مِنْ بَنِي ثَعْلَبَةَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ – وَهُوَ يَتَكَلَّمُ – فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ، هَؤُلَاءِ بَنُو ثَعْلَبَةَ بْنِ يَرْبُوعٍ قَتَلُوا فُلَانًا، رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا لَا تَجْنِي نَفْسٌ عَلَى الْأُخْرَى". وَفِي رِوَايَةٍ: "عَلَى نَفْسٍ". (ن,جه)', 'നബി(സ)യോട് സഹവസിച്ചിട്ടുള്ള അസ്വദുബ്നുൽ ഹിലാൽ(റ) സഅ്ലബതുബ്നു സഹ്ദമിൽ യർബൂഈ(റ)വിൽ നിന്ന് നിവേദനം: റസൂൽ(സ) ഒരു കൂട്ടം അൻസാരികളോട് പ്രസംഗിക്കുകയായിരുന്നു. അപ്പോളവർ പറഞ്ഞു: റസൂലേ, ഇവർ ബനൂസഅ്ലതുബ്നു യർബൂഅ് ഗോത്രക്കാർ ജാഹിലിയ്യാകാലത്ത് ഒരാളെ കൊന്നിരുന്നു. അപ്പോൾ നബി(സ) ശബ്ദമുയർത്തിപ്പറഞ്ഞു: "അറിയുക, ഒരാളും മറ്റൊരാളുടെ കുറ്റം വഹിക്കുകയില്ല." മറ്റൊരു നിവേദനം: ബനൂസഅ്ലബിൽ പെട്ട ഒരു കൂട്ടമാളുകൾ നബി(സ)യുടെയടുക്കൽ എത്തിച്ചേർന്നു. തദവസരം നബി(സ) സംസാരിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: റസൂലേ, ബനൂസഅ്ലബ് ഗോത്രക്കാർ ഒരാളെ കൊന്നിരുന്നു. നബി(സ)യുടെ അനുചരിരിൽ ഒരാളെയാണ് അദ്ദേഹം ഉദ്ദേശിച്ചത്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അറിയുക, ഒരാളുടെ കുറ്റം മറ്റൊരാളും വഹിക്കുകയില്ല." മറ്റൊരു നിവേദനത്തിൽ: "ഒരു ശരീരത്തിന്റെ" എന്നാണുള്ളത്. (ന,ജ)', 'الْأَسْوَدِ بْنِ هِلَالٍ، وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَنْ ثَعْلَبَةَ بْنِ زَهْدَمٍ الْيَرْبُوعِيِّ', 'നബി(സ)യോട് സഹവസിച്ചിട്ടുള്ള അസ്വദുബ്നുൽ ഹിലാൽ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 562, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=107), 1, 'وَفِي رِوَايَةٍ: قَالَ: انْتَهَى قَوْمٌ مِنْ بَنِي ثَعْلَبَةَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ – وَهُوَ يَتَكَلَّمُ – فَقَالَ رَجُلٌ: يَا رَسُولَ اللهِ، هَؤُلَاءِ بَنُو ثَعْلَبَةَ بْنِ يَرْبُوعٍ قَتَلُوا فُلَانًا، رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا لَا تَجْنِي نَفْسٌ عَلَى الْأُخْرَى".', 'മറ്റൊരു നിവേദനം: ബനൂസഅ്ലബിൽ പെട്ട ഒരു കൂട്ടമാളുകൾ നബി(സ)യുടെയടുക്കൽ എത്തിച്ചേർന്നു. തദവസരം നബി(സ) സംസാരിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: റസൂലേ, ബനൂസഅ്ലബ് ഗോത്രക്കാർ ഒരാളെ കൊന്നിരുന്നു. നബി(സ)യുടെ അനുചരിരിൽ ഒരാളെയാണ് അദ്ദേഹം ഉദ്ദേശിച്ചത്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അറിയുക, ഒരാളുടെ കുറ്റം മറ്റൊരാളും വഹിക്കുകയില്ല."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=107), 2, 'وَفِي رِوَايَةٍ: "عَلَى نَفْسٍ". (ن,جه)', 'മറ്റൊരു നിവേദനത്തിൽ: "ഒരു ശരീരത്തിന്റെ" എന്നാണുള്ളത്. (ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ طَارِقٍ الْمُحَارِبِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللهِ، هَؤُلَاءِ بَنُو ثَعْلَبَةَ الَّذِينَ قَتَلُوا فُلَانًا فِي الْجَاهِلِيَّةِ، فَخُذْ لَنَا بِثَأْرِنَا، فَرَفَعَ يَدَيْهِ حَتَّى رَأَيْتُ بَيَاضَ إِبْطَيْهِ وَهُوَ يَقُولُ: "لَا تَجْنِي أُمٌّ عَلَى وَلَدٍ". مَرَّتَيْنِ. (ن)', 'താരിഖുബ്നുൽ മുഹാരിബി(റ): ഒരാൾ പറഞ്ഞു: റസൂലേ, ഇവർ ബനൂസഅ്ലബ് ഗോത്രക്കാർ ജാഹിലിയ്യാകാലത്ത് ഒരാളെ കൊന്നിരുന്നു. അതുകൊണ്ട് ഞങ്ങൾക്കുള്ള അവകാശം വാങ്ങിത്തരിക. അപ്പോൾ ഞാൻ തിരുമേനി(സ)യുടെ കക്ഷത്തിന്റെ വെളുപ്പ്നിറം ദർശിക്കും വിധം അവിടന്ന് തിരുകരങ്ങൾ ഉയർത്തി. അവിടന്ന് പറയുന്നുണ്ടായിരുന്നു: "മകന്റെ കുറ്റം മാതാവ് വഹിക്കില്ല." അവിടന്ന് ഇപ്രകാരം രണ്ട് പ്രാവശ്യം അരുളി. (ന)', 'طَارِقٍ الْمُحَارِبِيِّ', 'താരിഖുബ്നുൽ മുഹാരിബി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ زِنْبَاعٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَدِمَ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَدْ خَصَى غُلَامًا لَهُ، فَأَعْتَقَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمُثْلَةِ. (جه)', 'സിമ്പാഅ്(റ): തന്റെ ഒരു അടിമയെ ശണ്ഡീകരിച്ച ശേഷം അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വന്നു. അംഗവിഛേദം നടത്തിയതിന്റെ പേരിൽ നബി(സ) ആ അടിമയെ നബി(സ) മോചിപ്പിച്ചു. (ജ)', 'زِنْبَاعٍ', 'സിമ്പാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 563, 563, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَارِخًا، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا لَكَ". قَالَ: سَيِّدِي رَآنِي أُقَبِّلُ جَارِيَةً لَهُ، فَجَبَّ مَذَاكِيرِي. فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَيَّ بِالرَّجُلِ". فَطُلِبَ فَلَمْ يُقْدَرْ عَلَيْهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اذْهَبْ فَأَنْتَ حُرٌّ". قَالَ: عَلَى مَنْ نُصْرَتِي يَا رَسُولَ اللهِ؟ قَالَ: يَقُولُ: أَرَأَيْتَ إِنِ اسْتَرَقَّنِي مَوْلَايَ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "عَلَى كُلِّ مُؤْمِنٍ. أَوْ: مُسْلِمٍ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരാൾ ആർത്തട്ടഹസിച്ചുകൊണ്ട് നബി(സ)യുടെ അടുത്ത് വന്നു. റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾക്കെന്ത് സംഭവിച്ചു?" ആഗതൻ പറഞ്ഞു: എന്റെ യജമാനന്റെ അടിമയെ ഞാൻ ചുംബിക്കുന്നത് അയാൾ കണ്ടു. ഉടനെ അയാൾ എന്റെ ലിംഗം മുറിച്ചുകളഞ്ഞു. നബി(സ) പറഞ്ഞു: "അയാളെ എന്റെ അടുത്തേക്ക് കൊണ്ടുവരിക." അങ്ങനെ അയാളെ തിരഞ്ഞുനോക്കിയെങ്കിലും കണ്ടുകിട്ടിയില്ല. അപ്പോൾ തിരുദൂതർ(സ) പറഞ്ഞു: "നീ പോവുക, നീ സ്വതന്ത്രനാണ്." അയാൾ ചോദിച്ചു: എന്നെ സഹായിക്കൽ ആരുടെ കടമയാണ് റസൂലേ? നിവേദകൻ പറഞ്ഞു: അയാൾ ഇപ്രകാരം ചോദിക്കുന്നുണ്ടായിരുന്നു: എന്റെ യജമാനൻ എന്നെ വീണ്ടും അടിമയാക്കിയാലോ? റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ മുഅ്മിനിന്റെയും, അല്ലെങ്കിൽ മുസ്ലിമിന്റെയും (ബാധ്യതയാണ് നിന്നെ സഹായിക്കൽ)". (ദ,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 563, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَعَفَّ النَّاسِ قِتْلَةً أَهْلُ الْإِيمَانِ". (د,جه)', 'അബ്ദുല്ല(റ): തിരുദൂതർ(സ) പറഞ്ഞു: "ഏറ്റവും മാന്യമായി കൊല്ലുന്നവൻ ഈമാന്റെ അവകാശിയായിരിക്കും." (ദ,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ رِفَاعَةَ بْنِ شَدَّادٍ الْقِتْبَانِيِّ، قَالَ: لَوْلَا كَلِمَةٌ سَمِعْتُهَا مِنْ عَمْرِو بْنِ الْحَمِقِ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُ لَمَشَيْتُ فِيمَا بَيْنَ رَأْسِ الْمُخْتَارِ وَجَسَدِهِ، سَمِعْتُهُ يَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَمِنَ رَجُلًا عَلَى دَمِهِ فَقَتَلَهُ، فَإِنَّهُ يَحْمِلُ لِوَاءَ غَدْرٍ يَوْمَ الْقِيَامَةِ". (جه)', 'രിഫാഅതുബ്നു ശദ്ദാദുൽ ഖിത്ബാനി(റ): അംറുബ്നു ഹമിഖിൽ ഖുസാഈ(റ)വിന്റെ ഒരു വാക്ക് ഞാൻ കേട്ടില്ലായിരുന്നുവെങ്കിൽ മുഖ്താറിന്റെ ഉടലിന്റെയും ശിരസ്സിന്റെയും ഇടയിലൂടെ ഞാൻ നടക്കുമായിരുന്നു. അംറ്(റ) പറയുന്നത് ഞാൻ കേട്ടു. റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരാളുടെ ജീവിതത്തിന് അഭയം നൽകിയ ശേഷം അവനെ കൊന്നാൽ വിധിനാളിൽ വഞ്ചനയുടെ കൊടി അവൻ വഹിക്കേണ്ടിവരും." (ജ)', 'رِفَاعَةَ بْنِ شَدَّادٍ الْقِتْبَانِيِّ، قَالَ', 'രിഫാഅതുബ്നു ശദ്ദാദുൽ ഖിത്ബാനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ رِفَاعَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى الْمُخْتَارِ فِي قَصْرِهِ، فَقَالَ: قَامَ جِبْرَائِيلُ مِنْ عِنْدِي السَّاعَةَ، فَمَا مَنَعَنِي مِنْ ضَرْبِ عُنُقِهِ، إِلَّا حَدِيثٌ سَمِعْتُهُ مِنْ سُلَيْمَانَ بْنِ صُرَدٍ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "إِذَا أَمِنَكَ الرَّجُلُ عَلَى دَمِهِ فَلَا تَقْتُلْهُ". فَذَاكَ الَّذِي مَنَعَنِي مِنْهُ. (جه)', 'രിഫാഅ(റ): ഞാൻ മുഖ്താറിന്റെ കോട്ടയിൽ പോയി. അപ്പോൾ അയാൾ പറഞ്ഞു: ജിബ്രീൽ(അ) എന്റെ അടുത്ത് നിന്ന് ഇപ്പോൾ പോയിട്ടേയുള്ളു. സുലൈമാനുബ്നു സ്വുർദ്(റ)വിൽ നിന്ന് ഞാൻ കേട്ട ഒരു ഹദീസല്ലാതെ ഒന്നും അവന്റെ കഴുത്തറക്കുന്നതിൽ നിന്ന് എന്നെ തടഞ്ഞില്ല. പ്രവാചകർ(സ) പറഞ്ഞു: "നിന്റെയടുക്കൽ ആരെങ്കിലും ജീവിതാഭയം തേടിയാൽ പിന്നെ അവനെ നീ കൊല്ലരുത്." ഇതാണ് അവനെ വധിക്കുന്നതിൽ നിന്ന് എന്നെ തടഞ്ഞത്. (ജ)', 'رِفَاعَةَ', 'രിഫാഅ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 564, 564, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ مُعَاذِ بْنِ جَبَلٍ، وَأَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ، وَعُبَادَةَ بْنِ الصَّامِتِ، وَشَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُمْ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمَرْأَةُ إِذَا قَتَلَتْ عَمْدًا لَا تُقْتَلُ حَتَّى تَضَعَ مَا فِي بَطْنِهَا إِنْ كَانَتْ حَامِلًا، وَحَتَّى تُكَفِّلَ وَلَدَهَا. وَإِنْ زَنَتْ لَمْ تُرْجَمْ حَتَّى تَضَعَ مَا فِي بَطْنِهَا، وَحَتَّى تُكَفِّلَ وَلَدَهَا". [ز: في إسناده ضعيفان] (جه)', 'മുആദുബ്നു ജബൽ(റ), അബൂഉബൈദ(റ), ഉബാദതുബ്നു സ്വാമിത്(റ), ശദ്ദാദുബ്നു ഔസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു സ്ത്രീ കരുതിക്കൂട്ടി കൊലനടത്തിയാൽ, അവൾ ഗർഭിണിയാണെങ്കിൽ തന്റെ വയറ്റിലുള്ളതിനെ പ്രസവിക്കുന്നത് വരെയും അവളുടെ സന്തതിയുടെ ഉത്തരവാദിത്തം (മറ്റൊരാളെ) ഏൽപിക്കുന്നത് വരെയും അവളെ കൊല്ലരുത്. ഒരു സ്ത്രീ വ്യഭിചരിച്ചാൽ അവൾ പ്രസവിക്കുന്നത് വരെയും സന്തതിയുടെ ഉത്തരവാദിത്തം (മറ്റൊരാളെ) ഏൽപിക്കുന്നത് വരെയും അവളെ എറിഞ്ഞുകൊല്ലരുത്. (ഈ ഹദീസിന്റെ പരമ്പരയിൽ ഭംഗമുള്ള രണ്ട് പേരുണ്ട്) (ജ)', 'مُعَاذِ بْنِ جَبَلٍ، وَأَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ، وَعُبَادَةَ بْنِ الصَّامِتِ، وَشَدَّادِ بْنِ أَوْسٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيفان', null, 564, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُ قَسْمًا أَقْبَلَ رَجُلٌ فَأَكَبَّ عَلَيْهِ، فَطَعَنَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِعُرْجُونٍ كَانَ مَعَهُ، فَجُرِحَ بِوَجْهِهِ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "تَعَالَ فَاسْتَقِدْ". فَقَالَ: بَلْ عَفَوْتُ يَا رَسُولَ اللهِ. (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): റസൂൽ(സ) ഞങ്ങൾക്കിടയിൽ എന്തോ വിഹിതം വെക്കുകയായിരുന്നു. അപ്പോൾ ഒരു മനുഷ്യൻ കടന്നുവന്നു. അയാൾ തിരുമേനിയുടെ മുന്നിൽ വീണു. തിരുമേനി(സ) തന്റെ കയ്യിലുണ്ടായിരുന്ന ഈത്തപ്പനയുടെ തണ്ട് കൊണ്ട് അദ്ദേഹത്തെ കുത്തി. അദ്ദേഹത്തിന്റെ മുഖത്ത് ഒരു മുറിവുണ്ടായി. റസൂൽ(സ) അദ്ദേഹത്തോട് പറഞ്ഞു: "ഇങ്ങോട്ടു വരിക, എന്നോട് പ്രതികാരം ചെയ്യുക." അദ്ദേഹം പറഞ്ഞു: വേണ്ട റസൂലേ, ഞാൻ മാപ്പ് ചെയ്തിരിക്കുന്നു. (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ، وَقَدْ خَطَبَ النَّاسَ، فَقَالَ: إِنِّي لَمْ أَبْعَثْ عُمَّالِي لِيَضْرِبُوا أَبْشَارَكُمْ، وَلَا لِيَأْخُذُوا أَمْوَالَكُمْ، فَمَنْ فُعِلَ بِهِ ذَلِكَ فَلْيَرْفَعْهُ إِلَيَّ أُقِصُّهُ مِنْهُ. قَالَ عَمْرُو بْنُ الْعَاصِ رَضِيَ اللهُ عَنْهُ: لَوْ أَنَّ رَجُلًا أَدَّبَ بَعْضَ رَعِيَّتِهِ أَتُقِصُّهُ مِنْهُ؟ قَالَ: إِي وَالَّذِي نَفْسِي بِيَدِهِ أُقِصُّهُ، وَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَقَصَّ مِنْ نَفْسِهِ. (د,ن)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): ജനങ്ങളോട് പ്രസംഗിക്കവെ അദ്ദേഹം പറഞ്ഞു: നിങ്ങളെ അടിക്കാനും നിങ്ങളുടെ സമ്പത്ത് അപഹരിക്കാനും ഞാൻ എന്റെ ഗവർണർമാരെ അയച്ചിട്ടില്ല. ആരോടെങ്കിലും ഇവർ അപ്രകാരം ചെയ്താൽ എന്നോട് പരാതി ബോധിപ്പിക്കുക. ഞാൻ അവരിൽനിന്ന് ഖിസാസ് (പ്രതിക്രിയ) എടുക്കുന്നതാണ്. അംറുബ്നുൽആസ്(റ) ചോദിച്ചു: നിശ്ചയം വല്ലവനും തന്റെ പ്രജകളെ അദബ് പഠിപ്പിച്ചാൽ താങ്കൾ അവനിൽനിന്ന് ഖിസാസ് എടുക്കുമോ? ഉമർ(റ) പറഞ്ഞു: എന്റെ ആത്മാവ് ആരുടെ കരങ്ങളിലാണോ അവൻ തന്നെ സത്യം, ഞാൻ ഖിസാസ് എടുക്കുകതന്നെ ചെയ്യും. റസൂൽ(സ) സ്വന്തം ശരീരത്തിന് ഖിസാസ് എടുക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ,ന)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 565, 565, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَطَبَ يَوْمَ الْفَتْحِ بِمَكَّةَ – وَفِي رِوَايَةٍ: عَلَى دَرَجَةِ الْبَيْتِ أَوِ الْكَعْبَةِ – فَكَبَّرَ ثَلَاثًا ثُمَّ قَالَ: "لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ، صَدَقَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ. إِلَى هَاهُنَا حَفِظْتُهُ عَنْ مُسَدَّدٍ ثُمَّ اتَّفَقَا أَلَا إِنَّ كُلَّ مَأْثُرَةٍ كَانَتْ فِي الْجَاهِلِيَّةِ تُذْكَرُ وَتُدْعَى مِنْ دَمٍ أَوْ مَالٍ تَحْتَ قَدَمَيَّ، إِلَّا مَا كَانَ مِنْ سِقَايَةِ الْحَاجِّ، وَسِدَانَةِ الْبَيْتِ". ثُمَّ قَالَ: "أَلَا إِنَّ دِيَةَ الْخَطَإِ شِبْهِ الْعَمْدِ مَا كَانَ بِالسَّوْطِ وَالْعَصَا مِائَةٌ مِنَ الْإِبِلِ: مِنْهَا أَرْبَعُونَ فِي بُطُونِ أَوْلَادِهَا". (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): തിരുമേനി(സ) മക്കാവിജയത്തിന്റെ ദിവസം പ്രസംഗിച്ചു. - മറ്റൊരു നീവേദനത്തിൽ: കഅ്ബാലയത്തിന്റെ ഉമ്മറപ്പടിയിൽ നിന്നുകൊണ്ട് - അവിടന്ന് മൂന്നുപ്രാവശ്യം തക്ബീർ ചൊല്ലി. പിന്നീട് പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല. അവൻ ഒരുവനാണ്. വാഗ്ദത്തം സത്യമാക്കിയവനാണവൻ. അടിമയെ സഹായിച്ചവനും സൈന്യങ്ങളെ പരാജയപ്പെടുത്തിയവനുമാണവൻ. സമ്പത്തിനാലും രക്തത്തിനാലും തേടപ്പെടുകയും പറയപ്പെടുകയും ചെയ്യുന്ന ജാഹിലിയ്യാ കാലത്തിലെ എല്ലാ നടപടിക്രമങ്ങളും ഇന്ന് എന്റെ കാലിന്റെ താഴെയാണ്. ഹാജിമാർക്ക് വെള്ളം നൽകുന്നതിനോടും കഅ്ബയെ പരിപാലിക്കുന്നതിനോടും ബന്ധപ്പെട്ടവയൊഴികെ." പിന്നെ പറഞ്ഞു: "വടികൊണ്ടോ, ചാട്ടവാറുകൊണ്ടോഉള്ള, മനഃപൂർവ്വമായതിനോട് സാദൃശ്യമുള്ള പിഴവിന്റെ നഷ്ടപരിഹാരം നൂറ് ഒട്ടകമാണ്. അതിൽ നാൽപതെണ്ണം ഗർഭസ്ഥശിശുവോടെയായിരിക്കണം." (ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 565, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=117), 1, 'وَفِي رِوَايَةٍ: عَلَى دَرَجَةِ الْبَيْتِ أَوِ الْكَعْبَةِ – فَكَبَّرَ ثَلَاثًا ثُمَّ قَالَ: "لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ، صَدَقَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ. إِلَى هَاهُنَا حَفِظْتُهُ عَنْ مُسَدَّدٍ ثُمَّ اتَّفَقَا أَلَا إِنَّ كُلَّ مَأْثُرَةٍ كَانَتْ فِي الْجَاهِلِيَّةِ تُذْكَرُ وَتُدْعَى مِنْ دَمٍ أَوْ مَالٍ تَحْتَ قَدَمَيَّ، إِلَّا مَا كَانَ مِنْ سِقَايَةِ الْحَاجِّ، وَسِدَانَةِ الْبَيْتِ". ثُمَّ قَالَ: "أَلَا إِنَّ دِيَةَ الْخَطَإِ شِبْهِ الْعَمْدِ مَا كَانَ بِالسَّوْطِ وَالْعَصَا مِائَةٌ مِنَ الْإِبِلِ: مِنْهَا أَرْبَعُونَ فِي بُطُونِ أَوْلَادِهَا". (د,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ مُجَاهِدٍ قَالَ: قَضَى عُمَرُ فِي شِبْهِ الْعَمْدِ ثَلَاثِينَ حِقَّةً، وَثَلَاثِينَ جَذَعَةً، وَأَرْبَعِينَ خَلِفَةً مَا بَيْنَ ثَنِيَّةٍ إِلَى بَازِلِ عَامِهَا. (د)', 'മുജാഹിദ്(റ): കരുതിക്കൂട്ടിയതിനോട് സാമ്യമുള്ളതിൽ നഷ്ടപരിഹാരമായി നാല് വയസ്സുള്ള 30 പെൺഒട്ടകവും, അഞ്ച് വയസ്സുള്ള 30 പെൺഒട്ടകവും, ആറിനും ഒമ്പതിനുമിടയിൽ പ്രായമുള്ള ഗർഭമുള്ള 40 ഒട്ടകവും നൽകണമെന്ന് ഉമർ(റ) വിധിച്ചു. (ദ)', 'مُجَاهِدٍ قَالَ', 'മുജാഹിദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 566, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: فِي شِبْهِ الْعَمْدِ أَثْلَاثٌ: ثَلَاثٌ وَثَلَاثُونَ حِقَّةً، وَثَلَاثٌ وَثَلَاثُونَ جَذَعَةً، وَأَرْبَعٌ وَثَلَاثُونَ ثَنِيَّةً إِلَى بَازِلِ عَامِهَا، وَكُلُّهَا خَلِفَةً. (د)', 'അലി(റ): കരുതിക്കൂട്ടിയുള്ളതിനോട് സാമ്യതയുള്ളതിൽ മൂന്ന് ഇനം ഒട്ടകം നഷ്ടപരിഹാരമായി നൽകണം. നാലുവയസ്സുള്ള 33 പെൺഒട്ടകം, അഞ്ചുവയസ്സുള്ള 33 പെൺഒട്ടകം, ആറിനും ഒമ്പതിനുമിടയിൽ പ്രായമുള്ള 34 ഒട്ടകം. എല്ലാം ഗർഭമുള്ളതായിരിക്കണം. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 566, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي دِيَةِ الْمُكَاتَبِ يُقْتَلُ: يُؤَدَّى مَا أَدَّى مِنْ مُكَاتَبَتِهِ دِيَةَ الْحُرِّ، وَمَا بَقِيَ دِيَةَ الْمَمْلُوكِ. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): കൊല്ലപ്പെട്ട, മോചനപത്രം നൽകപ്പെട്ട അടിമയുടെ വിഷയത്തിൽ, അവൻ യജമാനന് കൊടുത്തുവീട്ടിയ തോതനുസരിച്ച് സ്വതന്ത്രന്റെ നഷ്ടപരിഹാരവും അല്ലാത്തതിന് അടിമയുടെ നഷ്ടപരിഹാരവും കൊടുക്കണമെന്ന് റസൂൽ(സ) വിധിച്ചു. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 566, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَصَابَ الْمُكَاتَبُ حَدًّا، أَوْ وَرِثَ مِيرَاثًا، يَرِثُ عَلَى قَدْرِ مَا عَتَقَ مِنْهُ". (د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നിശ്ചയം നബി(സ) പറഞ്ഞു: "മോചനപത്രം എഴുതപ്പെട്ട അടിമ ശിക്ഷക്കർഹനാകുകയോ വല്ല അനന്തസ്വത്തിനും അവകാശിയാകുകയോ ചെയ്യുകയാണെങ്കിൽ, തനിക്ക് സ്വാതത്ര്യം ലഭിച്ചതിന്റെ തോതനുസരിച്ചാകും അവൻ അനന്തരമെടുക്കുക." (ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 566, 566, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ غُلَامًا لِأُنَاسٍ فُقَرَاءَ قَطَعَ أُذُنَ غُلَامٍ لِأُنَاسٍ أَغْنِيَاءَ، فَأَتَى أَهْلُهُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا رَسُولَ اللهِ، إِنَّا أُنَاسٌ فُقَرَاءُ، فَلَمْ يَجْعَلْ عَلَيْهِ شَيْئًا. (ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): പാവപ്പെട്ടവരുടെ ഒരടിമ സമ്പന്നരുടെ ഒരു അടിമയുടെ ചെവി മുറിച്ചെടുത്തു. അപ്പോൾ അവന്റെ ആളുകൾ പരാതിയുമായി നബി(സ)യുടെയടുക്കൽ വന്നു. അവർ പറഞ്ഞു: റസൂലേ, ഞങ്ങൾ ദരിദ്രരാണ്. അന്നേരം തിരുമേനി(സ) അവനുമേൽ ഒരുവിധിയും നടപ്പാക്കിയില്ല. (ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ نَشَدَ قَضَاءَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ذَلِكَ، فَقَامَ حَمَلُ بْنُ مَالِكٍ فَقَالَ: كُنْتُ بَيْنَ حُجْرَتَيِ امْرَأَتَيْنِ، فَضَرَبَتْ إِحْدَاهُمَا الْأُخْرَى بِمِسْطَحٍ فَقَتَلَتْهَا وَجَنِينَهَا، فَقَضَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي جَنِينِهَا بِغُرَّةٍ، وَأَنْ تُقْتَلَ بِهَا. (ن)', 'ഉമർ(റ)വിൽനിന്ന് ഇബ്നുഅബ്ബാസ്(റ): ഈ വിഷയത്തിൽ റസൂലുല്ലാഹി(സ)യുടെ കാലത്തുണ്ടായ വിധിയെക്കുറിച്ച് ഉമർ(റ) അന്വേഷിച്ചു. അപ്പോൾ ഹമലുബ്നു മാലിക്(റ) എഴുന്നേറ്റുനിന്നു പറഞ്ഞു: ഞാൻ രണ്ട് സ്ത്രീകളുടെ രണ്ട് റൂമുകൾക്കിടയിലായിരുന്നു. അപ്പോൾ ഒരുത്തി മറ്റവളെയും അവളുടെ ഗർഭസ്ഥശിശുവിനെയും തടികൊണ്ട് അടിച്ചുകൊന്നു. അപ്പോൾ ഗർഭസ്ഥശിശുവിനു പകരം അടിമയെ നഷ്ടപരിഹാരമായി നൽകാനും സ്ത്രീയെ കൊന്നതിന് പകരം അവളെ കൊല്ലാനും നബി(സ) വിധിച്ചു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اطَّلَعَ فِي بَيْتِ قَوْمٍ بِغَيْرِ إِذْنِهِمْ، فَفَقَئُوا عَيْنَهُ، فَلَا دِيَةَ لَهُ وَلَا قِصَاصَ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും മറ്റൊരാളുടെ വീട്ടിലേക്ക് സമ്മതമില്ലാതെ എത്തിനോക്കുകയും അവർ അവന്റെ കണ്ണ് പറിച്ചെടുക്കുകയും ചെയ്താൽ അവന് നഷ്ടപരിഹാരമോ പ്രതിക്രിയയോ ഇല്ല." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ أَنَّ امْرَأً اطَّلَعَ عَلَيْكَ بِغَيْرِ إِذْنٍ، فَخَذَفْتَهُ فَفَقَأْتَ عَيْنَهُ، مَا كَانَ عَلَيْكَ حَرَجٌ". وَقَالَ مَرَّةً أُخْرَى: "جُنَاحٌ". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും സമ്മതമില്ലാതെ നിന്റെ വീട്ടിലേക്ക് എത്തിനോക്കുകയും തൽസമയം അവനെ നീ എറിയുകയും അതുകാരണം അവന്റെ കണ്ണിന് കേട് പറ്റുകയും ചെയ്താൽ അതിന്റെ പേരിൽ നിനക്ക് ഒരു കുഴപ്പവുമില്ല." മറ്റൊരു നിവേദനം: "ഒരു കുറ്റവുമില്ല." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 567, 567, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=7 and h.hadith_no=125), 1, null, 'മറ്റൊരു നിവേദനം: "ഒരു കുറ്റവുമില്ല." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يُصَلِّي، فَإِذَا بِابْنٍ لِمَرْوَانَ يَمُرُّ بَيْنَ يَدَيْهِ، فَدَرَأَهُ فَلَمْ يَرْجِعْ، فَضَرَبَهُ، فَخَرَجَ الْغُلَامُ يَبْكِي حَتَّى أَتَى مَرْوَانَ فَأَخْبَرَهُ، فَقَالَ مَرْوَانُ لِأَبِي سَعِيدٍ: لِمَ ضَرَبْتَ ابْنَ أَخِيكَ؟ قَالَ: مَا ضَرَبْتُهُ، إِنَّمَا ضَرَبْتُ الشَّيْطَانَ، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا كَانَ أَحَدُكُمْ فِي صَلَاةٍ، فَأَرَادَ إِنْسَانٌ يَمُرُّ بَيْنَ يَدَيْهِ فَيَدْرَؤُهُ مَا اسْتَطَاعَ، فَإِنْ أَبَى فَلْيُقَاتِلْهُ فَإِنَّهُ شَيْطَانٌ". (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): അവർ നമസ്കരിക്കുകയായിരുന്നു. അപ്പോൾ മർവാന്റെ മകൻ അവരുടെ മുന്നിലൂടെ നടന്നു. അവർ അവനെ തടഞ്ഞുവെച്ചു. പക്ഷേ, അവൻ തിരിഞ്ഞുപോയില്ല. അപ്പോഴവർ അവനെ അടിച്ചു. കുട്ടി കരഞ്ഞു കൊണ്ട് മർവാന്റെ അടുത്തുചെന്ന് കാര്യം പറഞ്ഞു. അപ്പോൾ മർവാൻ അബൂസഈദ്(റ)വിനോട് ചോദിച്ചു: നിങ്ങളെന്തിനാണ് നിങ്ങളുടെ സഹോദരപുത്രനെ അടിച്ചത്? അവർ പറഞ്ഞു: ഞാൻ അവനെ അടിച്ചിട്ടില്ല. ഞാനടിച്ചത് പിശാചിനെയാണ്. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "നിങ്ങളിലൊരാൾ നമസ്കരിക്കുമ്പോൾ ആരെങ്കിലും മുമ്പിലൂടെ നടക്കാൻ തുനിഞ്ഞാൽ കഴിവിന്റെ പരമാവധി അവനെ തടഞ്ഞുനിർത്തുക. എന്നിട്ടും വിസമ്മതിച്ചാൽ അവനെ വെട്ടുക. കാരണം അത് ചെകുത്താനാണ്." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 567, 568, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=3 and b.book_no=7 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
